window.DUNE_SCRIPT={"scenes":[{"n":0,"h":"Title page and cast","b":[["p",1],["a","D U N E"],["a","Screenplay by Alexandro Jodorowsky"],["a","Adapted from \"DUNE\""],["a","by frank HERBERT"],["p",2],["i","Emperor of the Galaxy",null,332,true],["i","Baron Harkonnen",null,333,true],["i","Peter",null,183,true],["p",5],["i","Feyd Rautha",null,183,true],["i","Rabban the Beast",null,302,true],["i","Uman Kudu",null,null,true],["i","Kynes",null,null,true],["i","Leto",null,288,true],["p",10],["i","Paul (young) (adult)",null,334,true],["i","Bene Guesserit Mother",null,335,true],["i","Jessica",null,267,true],["i","Thufir Hawatt",null,315,true],["i","Duncan Idaho - Gurney Halleck",null,191,true],["p",15],["i","Fenring and Wife",null,null,true],["i","Yueh",null,316,true],["p",17],["i","Sardaukar",null,336,true]]},{"n":1,"h":"","b":[["a","A space-ship is crossing the galaxy"],["p",19],["i","Side view of galaxy",1,193,true],["p",20],["i","Ship flying away from us",2,null,true],["p",21],["i","Ship flying left to right",3,44,true]]},{"n":2,"h":"","b":[["a","The centre of the Galaxy : a sphere of emerald green light, the middle of which is a whitishyellow colour. Just one single planet is circling around it."],["p",23],["i","The planet circling around the emerald sphere",4,null,true]]},{"n":3,"h":"","b":[["a","The ship begins its descent on to the planet."],["p",25],["i","Ship descending to the planet",5,null,true]]},{"n":4,"h":"","b":[["a","A 25th century city : Frantic, baroque, gigantic architecture. Everything seems motionless and lifeless. Total silence."],["p",27],["i","Deserted city",6,null,true]]},{"n":5,"h":"","b":[["a","The ship lands in a park overgrown with brushwood."],["a","A vehicle leaves the ship."],["p",29],["i","The ship vertically landed",7,null,true]]},{"n":6,"h":"","b":[["a","The vehicle is crossing the city which is deserted, overrun with dust and vegetation. There are huge vegetal jelly-fish ; lots of beetles as big as motor-cars ; and ruins."],["p",31],["i","Dog-Beings in vehicle",8,39,true]]},{"n":7,"h":"","b":[["a","The vehicle stops opposite a steel building which looks like a temple. It bears the following inscription : \"MUSEUM OF MAN\"."]]},{"n":8,"h":"","b":[["a","Twelve DOG-BEINGS get out of the vehicle. They walk with electronic paws, imitating a human walk. After drawing aside the door's cobwebs they enter, showing signs of anxiety."],["p",34],["i","Dog-Beings walking into building",9,7,true]]},{"n":9,"h":"MUSEUM INTERIOR","b":[["a","The dogs enter an empty hall, enormous by its very length, and although there are no windows, there is light. The door closes automatically behind them."],["a","The light changes, and the sound of church music begins. Half-light. A projector illuminates the group of dog-beings, who huddle together in terror."],["d","A MECHANICAL VOICE","You are in Kaitan, capital of the Galactic empire of Man. You are going to hear the history of the human race."],["a","A projector reveals a man crucified at the back of the hall. The dog-beings become excited and begin to shout."],["d","THE DOG-BEINGS","It's man, the Master !"],["a","They run up to the crucified man. After arriving at the foot of the metal cross, they fall to their knees and bark pitifully, as if imploring."],["a","Seeing that he makes no reply, they draw nearer and examine him. With deep disappointment they discover a \"ROBOT PROJECTOR\" plate"],["p",36],["i","Dog-Beings see crucifix",10,41,true],["p",37],["i","Dog-Beings at the foot of the crucifix",11,17,true],["p",38],["a","under his feet."],["a","There is a button beneath the plate. After a dog has pressed it, the robot comes back to life and moans :"],["d","ROBOT","\"WHY .... HAVE YOU .... ABANDONED ME ? \""],["a","The robot is weeping tears of oil. Excited, a dog presses other buttons. A white screen comes down from the ceiling. The robot receives painful electric discharges which dehumanize him ; two rays of light come out his eyes and project the history of humanity on to the screen."],["a","On the screen, the planet Earth can be seen with thousands of ships flying away from it."],["a","The planet explodes."],["p",39],["i","Dogmen watching projection",12,42,true]]},{"n":10,"h":"DECOR ONE","b":[["a","Decor showing the Earth exploding."],["a","Fragments of planet are thrown out into space."],["a","Space-ships are flying away towards all points in space."],["d","VOICE OF THE ROBOT","The history of man begins with the destruction of his mother-planet Earth. There remains no record of the earlier period."],["p",41],["i","Exploding Earth with ships leaving",13,47,true]]},{"n":11,"h":"DECOR TWO","b":[["a","Thousands of ships travelling through the Galaxy."],["a","A planet in flames."],["d","VOICE OF THE ROBOT","Man travelled for centuries to conquer the Galaxy."],["a","On an exotic planet, men in space-suits are fighting against enormous white globules."],["d","VOICE OF THE ROBOT","With the extermination of the Bactoglobules, the war of conquest was over. From now on, man was Master of the Galaxy."],["p",43],["i","Men fighting the white blobs",16,43,true]]},{"n":12,"h":"DECOR THREE","b":[["a","A transparent wall, on the borders of the Galaxy. Beyond waves, lines and geometrical figures can be seen. Opposite the wall there is a space-ship cemetery. In the foreground, a ship tries in vain to get past the wall."],["d","VOICE OF THE ROBOT","But the Galaxy is an island, and a prison. Its force of gravity is such that man will never be able to overcome it. There is nothing left to conquer, nor learn."],["p",45],["i","Space-ship unable to pass Galaxy barrier",17,null,true]]},{"n":13,"h":"DECOR FOUR","b":[["a","Interior of a large room filled with machines, robots ; a luxurious atmosphere (couches, jewels) ; fat human beings, their skin daubed with colour, are taking drugs and making love. A sumptuous meal, and bottles filled with drink (a decadent atmosphere). Through a window, a magnificent glittering city can be seen, with various levels of overhead roads and a great many space vehicles."],["d","VOICE OF THE ROBOT","Triumph killed ambition. The machines did everything, and the citizen degenerated."],["p",47],["i","Humans in a room with computers behind them",18,10,true]]},{"n":14,"h":"DECOR FIVE","b":[["a","Streets of a luxurious city of the future. In the middle of a fat, drunk and bedaubed crowd, some impassioned young people, albino, bald and thread-like, are destroying the little cars which were used as legs : they can be seen getting rid of their mechanical crutches, while others, crawling, destroy a machine. Computers are falling from the windows. Machines which have been destroyed are strewn over the ground. Men are running after some robots. The robots are being destroyed by the crowd."],["a","Whole groups of robots and machines are being destroyed by ferocious groups of humans."],["d","VOICE OF THE ROBOT","Neptoris 22nd 20134 marked the beginning of the bio-revolution against the machines."],["a","A gigantic computer, shaped like a brain, is attacked by thousands of people. Mechanical arms are tearing men to pieces with their claws. Shells come out of openings, destroying the space-ships which are attacking the computer, a part of which is in flames. There are a lot of dead bodies."],["d","VOICE OF THE ROBOT","The central-computer was destroyed."],["p",49],["i","Man fighting machines",20,null,true],["p",50],["i","The central computer being destroyed",21,null,true]]},{"n":15,"h":"DECOR SIX","b":[["a","In the middle of a ruined city, the representatives of each planet, with their different emblems, are holding a conference around a table shaped like a horseshoe. Applause can be heard."],["a","Close-up on the face of one representative."],["d","VOICE OF THE REPRESENTATIVE","We shall not construct machines imitating the human mind."],["a","Ovations. Shots of the decors foreground, where delegations are burning flags and constitutional documents."],["d","VOICE OF A LEADER","No more wars ! No more atomic arms."],["d","ANOTHER VOICE","One language"],["d","A SECOND VOICE","One currency ! One law !"],["d","A THIRD VOICE","One religion !"],["a","Ovations, applause, flourishes of trumpets."],["p",52],["i","Men burning books and flags on a bonfire",22,null,true]]},{"n":16,"h":"DECOR SEVEN","b":[["a","A large tournament, both futuristic and mediaeval. Tents can be seen in a big valley, various coats of arms. Two champions are representing their respective planets. Behind each of them, armies and space-ships can be seen. The stands are occupied by noblemen from various planets, including a central box where the Emperor and his courtiers are sitting."],["a","A baroque banquet with slaves serving, minstrels, and officials doing business deals."],["d","VOICE OF THE ROBOT","Three centuries later, the good resolutions were forgotten...."],["a","Shots of the tournament in detail. A group of soldiers is killing off another group belonging to the defeated opposing army. In the stands, a group is celebrating victory. Hands receiving the money gained from bets."],["d","VOICE OF THE ROBOT","Wars were illegal, but not duels fought \"for honour\" ..."],["a","Various groups are shown sitting in the stands ; their arms, coats of arms and flags."],["d","VOICE OF THE ROBOT","The planet were organized into \"Houses\". The Houses established a Senate...."],["a","Shot in detail of the Emperor's central box."],["d","VOICE OF THE ROBOT","... which elected, or dethroned, the Emperors."],["p",54],["a","Shot in detail of the banquet. One group is conspiring together, another is exchanging money. Hands are signing contracts. Mouths are whispering into ears. A nobleman is whipping a slave."],["d","VOICE OF THE ROBOT","The Galaxy became a stock-exchange, where each planet sold, brought, stole, and plotted in search of the economic power which would enable it to dominate the System."],["p",55],["i","A tournament surrounded by armies and a table of food",25,null,true]]},{"n":17,"h":"DECOR EIGHT","b":[["a","An airport. A space-ship on the ground. Some traders are coming down the ladder leading behind them a file of natives in chains, whose eyes are completely blue and who are dressed like desert inhabitants."],["a","Within this shot, travelling on to the hands of a native. He is holding a blue paste."],["d","VOICE OF THE ROBOT","in 24950, slave traders came back from Dune, a lost planet somewhere in the system, with a few natives who were \"spice\" eaters. A group of scientists and soldiers, standing near an old native, are examining the spice."],["d","VOICE OF THE ROBOT","It was found that the spice could enable a person to see into the future, and could also prolong life !"],["p",57],["i","People examining the blue spice in front of a ship",null,null,true]]},{"n":18,"h":"EXTERIOR - THE PLANET DUNE","b":[["a","A space-ship marked with the Guilds emblem is circling around the planet Dune. Vast expanses of desert and a few small mountain chains can be seen, but no oceans, lakes, rivers, nor vegetation. The ship comes out of the night lit up by two moons (one orange and the other green) and enters daylight under a large white sun."],["d","VOICE OF THE ROBOT","Dune has become the most important planet in the Galaxy. It has not a single drop of water."],["p",59],["i","The surface of Dune, covered with men and machines",28,null,true]]},{"n":19,"h":"EXTERIOR - THE DESERT","b":[["a","The Guild's ship is in the desert, near some dried human bones."],["a","A ramp comes out from the ship and two human beings come down it."],["a","A woman, whose suit is reminiscent of the clothes worn by nuns or female priests, and a man whose suit is the type of dress worn by mechanics or by explorers."],["d","VOICE OF THE ROBOT","In the year 25000, two passengers land on Dune."],["a","The woman checks her exploration equipment, and loads up with a knapsack."],["d","VOICE OF THE ROBOT","The \"Missionaria Protective\", a nun from the \"Bene Gesserit\" feminine School for physico-mental training through psycho-tropical drugs. She has come to create a religious myth among the natives, for purposes which remain mysterious. The man checks his exploration equipment."],["d","VOICE OF THE ROBOT","Pardot Kynes, planetary ecologist for the Imperium. He has come to study geological forces, for the sitting up of Botanical Centres \"intended to camouflage military bases..."],["a","The two individuals say goodbye by bowing, and go off in opposite directions."],["d","VOICE OF THE ROBOT","These two people are going to change the course of human history !"],["p",61],["i","The two people outside the ship on Dune",null,null,true],["p",62],["a","The two individuals disappear among the dunes. The wind blows up and the sand and erases their footsteps."],["a","The shot changes to the dunes, from which swirls of sand fly away as if they were dancing ; over this shot the film's titles are printed :"],["a","...... PRESENTS"],["a","A ..... FILM"],["a","\"DUNE\""],["a","ADAPTED FROM THE BOOK BY ...."],["a","etc..."],["p",63],["i","Dune title card, with two people walking away",32,18,true]]},{"n":20,"h":"EXTERIOR - SENATE PALACE AND STREET","b":[["a","The senate Palace, built in gold like all the buildings in Kaitain."],["a","Large stairway in front of a colonnaded entrance."],["a","A title superimposed :"],["t","KAITAN, Ulin 5th 25400"],["a","From the streets emerges a wagon drawn by 6 horses and driven by Duke Leto Atreides."],["a","Behind the wagon comes a cart also horse-drawn ; Duncan Idaho, Gurney Halleck and Thufir Hawatt are in the cart, together with some soldiers and ten blood-stained bodies."],["a","The Duke does not stop the horses when arriving in front of the stairway, which he climbs up driving the wagon, to the great concern of the guards."],["a","The cart stops, and its occupants get down. Lifting the bodies on to their backs, they run after the wagon which enters the building."],["p",65],["i","Cart being driven up the steps",null,null,true]]},{"n":21,"h":"SENATE HALL. INTERIOR","b":[["a","An enormous hall, with statues and columns."],["a","Varied groups of soldiers are talking, playing, arguing."],["a","They have flags, banners, sword belts, shields and side arms."],["a","With his wagon, Duke Leto bursts into the hall which he gallops across towards the conference room."],["a","Everyone is surprised, but they have no time to move, as Idaho, Halleck and Hawatt run in, followed by ten soldiers each carrying a body. They cross the hall followed by all the other groups of soldiers."],["p",67],["i","The interior of the Senate hall",null,null,true],["p",68],["i","Leto racing his cart through the hall",null,null,true]]},{"n":22,"h":"INTERIOR. CONFERENCE ROOM","b":[["a","The Hall comes out on to a sort of arena. This is a circular room with a large number of tiers arranged in a circle, where delegations from all the planets are sitting, with their different colours. There are nearly three thousand delegates. Protected by transparent shields, the Boxes of the Emperor and the three Major Houses."],["a","Duke Leto enters the central circle, stops the wagon and pulls himself up on to the roof. Idaho, Halleck, Hawatt and the soldiers come running in and put down the bodies in front of everyone."],["a","Amazement in the assembly."],["d","LETO","We have intercepted an unidentified ship near our planet..."],["a","Leto and his companions open the sides of the wagon. In the middle of the cries of astonishment, indignation and greed emanating from the Senate, a cargo of spice appears. A pile of blue matter."],["d","LETO","I denounce the existence of an organization which is smuggling spice. The minor Houses do not have the economic power necessary to bring off such thefts. The thief is one of the Major Houses."],["a","Vindictive applause from the minor Houses, and insults. Protests from the three Major Houses, and angry reactions. One of the boxes belongs to Baron Harkonnen."],["d","LETO","We Atreides solemnly promise to open an investigation and to find out who is guilty."],["p",70],["a","Applause from the minor houses. Insults from the major houses."],["d","LETO","We have decided to distribute this cargo, which is ours by right of conquest, among the minor houses."],["a","The minor houses hurry briskly into the circle to receive their share. The major Houses react hatefully and longingly."],["a","In the centre, there are signs of frenzied enthusiasm. Some senators are stuffing themselves with spice, their mouths full. They are carrying Duke Leto in triumph. In the imperial box, the Emperor is talking with his adviser."],["d","COUNT FENRING","Duke Leto is becoming very popular. He is the honest, generous hero the minor Houses needed. He can unite them, build a great power and obtain the Senate majority."],["a","The emperor grabs hold of a wax statuette of Duke Leto, puts it on the table and cuts off its head with his dagger."],["p",71],["i","Leto in the centre of the filled conference room",null,null,true]]},{"n":23,"h":"EXTERIOR. PLANET GIEDI ONE","b":[["a","TITLE SUPERIMPOSED - \"THE PLANET GIEDI ONE, WHERE THE HARKONNEN MAJOR HOUSE RULES SUPREME\"."],["a","Vast expanse of land, near the sea. In the distance, on a mountain by the coast, stands Harkonnen castle, with its stone walls sculptured to resemble demons. It is surrounded by enormous storehouses."],["a","Thousands of slaves are transporting large stone blocks, to be used to terminate the construction of the temple shaped like a statue of Baron Harkonnen."],["a","An ants' nest of soldiers, torturing, marking the prisoners with their electronic whips, forcing them to work until completely exhausted."],["a","A lot of ships coming and going, transporting slaves. Vehicles filled with prisoners' bodies are thrown into pits and rapidly covered over with earth by bulldozers."],["a","Thufir, disguised as a slave merchant, unloads a group of slaves among whom Leto, Idaho Duncan and Halleck can be seen, in chains."],["p",73],["i","Harkonnen slaves building the Baron statue",null,null,true]]},{"n":24,"h":"EXTERIOR-INTERIOR. PRISON HOLE AT NIGHT","b":[["a","A large spiral-shaped pit dug out into the earth. The prisoners are going down. They are attached by the ankle to a long chain which runs vertically the length of the hole. A stream of disgusting soup runs in a channel which follows the hole's spiral. Like animals, the prisoners, lying on their stomachs, are forced to plunge their mouths into the paste-like pulp and eat what they can. Halleck begins to shout. The guard, who holds the key of the chain, looks at him angrily. Halleck throws a handful of soup at him, which stains his uniform. The guard, with his sword drawn, comes to kill him. Halleck disarms him, attacks the other guards, putting them out of action, and frees Leto, Idaho and the rest of the prisoners."],["a","Leto, Halleck and Idaho dress up as soldiers."],["p",75],["i","The spiral prison hole",null,46,true]]},{"n":25,"h":"EXTERIOR - THE STOREHOUSES, AT NIGHT","b":[["a","Leto, Idaho and Halleck are walking, dressed as Harkonnen soldiers, in the middle of the storehouses. There are large spheres with thick steel doors. In front of each, there is a single guard, a Sardaukar."],["a","Without being seen, they attack a guard. They open the door and enter."]]},{"n":26,"h":"INTERIOR - STOREHOUSE","b":[["a","The storehouse is full of thousands and thousands of cases filled with spice."],["a","Leto opens a case and pours out the contents on to the ground."],["a","It's a blue, vibrating substance : Spice !"],["d","LETO","The Harkonnen are accomplices. It's the Emperor who's guilty !"],["p",78],["i","Lots of barrels in the storehouse",null,null,true]]},{"n":27,"h":"EXTERIOR - IMPERIAL PALACE - KAITAIN","b":[["t","IMPERIAL PALACE. KAITAIN"],["a","Preceded by a battalion of Sardaukars, Leto, Halleck, Idaho and Hawatt enter the Imperial Palace with its extravagant architecture. On the walls, fruit, birds, women and animals are all featured, sculptured in gold."],["p",80],["i","Exterior of the gold Imperial Palace",null,null,true]]},{"n":28,"h":"INTERIOR - RECEPTION HALL","b":[["a","A reception hall, with pillars everywhere sculptured to resemble praying mantis insects. Under the crossed legs, Count FENRING and his Lady are standing surrounded by monkeys dressed as page-boys and female midgets just like in Velazquez' paintings."],["a","Leto and his companions enter. The Count receives them coldly : He gives a small bow and leads Leto up to a large sculpture of a four-legged clown. Duke Leto climbs a stairway leading to the open mouth of the clown, which he enters."],["a","His companions stay behind to wait for him."],["p",82],["i","Clown statue under row of praying mantis",null,45,true]]},{"n":29,"h":"INTERIOR - THRONE ROOM","b":[["a","Leto drops down a ramp into a luxurious room, built upside down."],["a","The floor seems to be ceiling, and the ceiling seems to be the floor. Furniture and various objects are screwed to the ceiling. On the floor, a lamp appears to be falling upwards. A group of courtesans is dressed in costumes the cloth of which seems to be hanging upwards. Their skirts are raised, and their plastered wigs look as if they are turning up towards the ceiling-floor."],["a","The Emperor is sitting on a swing which sways on the floorceiling. His starched clothes are also raised, and seem to be hanging. His wig is plastered down."],["d","THE EMPEROR (TO LETO)","Another madman who sees the world upside down !"],["a","A giraffe passes over the ceiling imitation floor, his head hanging towards the Duke."],["d","THE EMPEROR","That's my favourite spider. If you say it's a giraffe, who are they going to believe ?"],["d","THE COURTESANS","It's a spider."],["d","THE EMPEROR","If you say I'm a spice smuggler, and I say you're a liar just out for power, who are they going to believe ?"],["d","THE COURTESANS","He's a liar."],["p",84],["d","THE EMPEROR","When I gave you the ducal ring, you swore fidelity to me."],["d","LETO","I never swore to be an accomplice of a theft."],["d","THE EMPEROR","In a world of thieves, an honest man is just conceited."],["a","The room begins to turn round. The Emperor and his courtesans stay in place like wax figures, but Leto has to walk on the floor, the roof and the walls to stop himself falling."],["d","THE EMPEROR","What is Good ? What is Evil ? Where is Beauty and where is Ugliness ? Which is the floor and which is the ceiling ?"],["a","The room is going round at a dizzy rate. Leto is thrown from one wall to the other."],["p",85],["i","Emperor's upside-down room",null,74,true]]},{"n":30,"h":"INTERIOR. RECEPTION HALL","b":[["a","The large sculpture of the clown turns round, and the lowered trousers reveal a wide hole between the buttocks. Ejected through the sculptures anus, the Duke drops down on to the floor. Hawatt, Idaho and Halleck hurry over to help him get back on his feet. They are furious, but Leto remains dignified and calms them down with a gesture."],["d","FENRING","Tomorrow, His Majesty the Emperor will give the Atreides satisfaction in front of the whole Senate."],["a","The clown turns round again, and, while the Atreides are leaving, his jaws move letting out a mechanical laugh."]]},{"n":31,"h":"INTERIOR. ASSEMBLY ROOM AT THE SENATE","b":[["a","Before the Senate, the Emperor, surrounded by Sardaukars and sitting in the transparent plastic stomach of a pregnant woman, is reading an official statement :"],["d","THE EMPEROR","To give cause for satisfaction to the minor Houses who mistrust one of the major Houses, we have decided to take the Dune concession away from the Major House of Baron Vladimir Harkonnen and to grant it to the minor Houses of Duke Leto Atreides, who shall leave his native planet, Caladan, and repair, together with his armies, to Dune in order to prevent smuggling, and look after the Imperium's interests."],["a","The whole Senate breaks out in applause. Leto and his friends alone do not participate in this otherwise unanimous enthusiasm."]]},{"n":32,"h":"EXTERIOR. LANDSCAPE OF CALADAN","b":[["t","\"THE PLANET CALADAN, HEAD PLANET OF THE ATREIDES HOUSE."],["a","A small ship belonging to the Guild flies over fields of flowers where livestock (six-horned bulls) are grazing. Plastic farms and Spanish-type mills can be seen. The ship lands in a field of luxuriant flowers near a pretty little brook. In the distance, the Atreides castle is in sight. The whole building, its architectural style futurist but restrained, is covered with branches, leaves and flowers. The old Reverend Mother Bene Guesserit gets out of the ship."],["a","From the doors of the castle, and from the area around it, flows a wave of people, mostly soldiers, some followed by women with children in their arms. Loaded carts, donkeys, horses, packages and baskets. An army of Guild officials, coming and going like ants, is organizing the activity. Everything is being done very methodically, and sadly as well. Some people, before boarding, kiss the earth and weep. At a suitable distance from the castle, a space-ship is standing, the biggest the human mind can possibly imagine, capable of holding 500,000 or a million people, with their possessions. This is the Guild's ship, intended for the transport of all the Atreides in one trip. The Guild officials pass through the crowd, leading the old Reverend Mother to a little mechanical car."],["p",89],["i","People and vehicles in a long line towards the giant ship",null,null,true]]},{"n":33,"h":"INTERIOR. HALL OF CALADAN CASTLE","b":[["a","In an enormous hall, Guild employees and Atreides soldiers are busy packing various books, objects and furniture."],["a","On Jessica's orders, a group of Guild employees pass with a six-horned bull's head : two of the horns are blood-stained. They are also carrying a portrait of Duke Leto's father, dressed as a bullfighter, and the family coat of arms : a red falcon."],["a","The Reverend Mother silently approaches Jessica. Jessica sees her coming and remembers..."]]},{"n":34,"h":"INTERIOR. HALL OF CALADAN CASTLE. MEMORY","b":[["a","In the half-light, Caladan castle can be seen, silent and tidily furnished. Standing on the spot remembered by Jessica is the Duke, who sees the Reverend Mother coming towards him, bringing a woman covered with veils."],["d","THE REVEREND MOTHER","A Bene Guesserit concubine slave ... A gift from the Emperor."],["a","The Reverend Mother stands aside discreetly, leaving the veiled woman who is none other than Jessica. Leto draws his sword, and approaches the woman."],["a","Gradually, with his sword, Leto prudently lays Jessica bare, taking off veil after veil. First her legs, then her hips, breasts, shoulders, her hair and finally her face."],["a","They both stare at each other, with instantaneous passion. Although he had intended to behead her, the Duke raises his sword ; she offers her neck. The Duke brings down his sword with force, stopping only a tenth of an inch from Jessica's neck. She is impassive, giving herself up to her fate."],["a","The Duke caresses her face with the blade of his sword, then the ends of her breasts, and finally her sex."]]},{"n":35,"h":"INTERIOR. BENE GUESSERIT TEMPLE. MEMORY","b":[["a","A temple, with an architectural style both Egyptian and futurist. Hundreds of young women are carrying out physico-mental exercises, under the direction of groups of older women. They all have the same religious uniform. A group of the older women are leading a very young Jessica towards the old Reverend Mother."],["a","The temple is filled with esoteric symbols and scientific drawings of genetic origin. The whole atmosphere is a mixture of science and mysticism."],["a","Having arrived in front of the Reverend Mother, Jessica acknowledges her presence with a series of ritual gestures."],["a","Two nuns stick a needle into the upper part of the Reverend Mother's skull and, with a holy syringe, inject a dose of blue liquid."],["a","The Reverend Mother eyes turn white and she begins to speak in an inhuman voice."],["d","THE REVEREND MOTHER","I know where genetic paths come from, and where they lead. You will receive the genes of Duke Leto and give birth to a daughter, who will receive the genes of a Harkonnen and give birth to first Bene Guesserit man, the Saviour, the Kwisatz Haderach, for whom we have waited four hundred years. Do not break the chain. Give me a daughter."],["a","The older women surround Jessica, murmuring a hypnotic chant in an inhuman tone of voice."],["p",93],["i","The temple, with spherical rooms",null,null,true]]},{"n":36,"h":"INTERIOR. THE DUKE'S BEDROOM. MEMORY","b":[["a","Leto's bedroom is like a monastic cell ; it has white walls, a wooden bed without either a mattress nor sheets or blankets, and the stump of a tree-trunk for a pillow."],["a","The only ornament on the walls is the six-horned bull's head, and the portrait of the Duke's father, dressed as a bullfighter."],["a","The Duke is caressing Jessica very platonically, although she is lying naked in his bed."],["a","She leans towards him and begins to caress him passionately. The Duke stops her, sadly. He shows her the bull's head."],["d","DUKE LETO","This bull killed my father. I jumped into the arena. The animal attacked me. His head has two blood-stained horns ; one has the blood of my father, the other the blood of my sex."],["a","Jessica, moved by this confession, embraces him. The Duke is further saddened."],["d","DUKE LETO","You will never give me a son to continue my House. I am the last of the Atreides."],["a","Jessica, filled with love, passion and pity, jumps from the bed and opens the windows. A strong wind enters the room ; the sky can be seen dotted with stars."],["d","JESSICA","You will have a son."],["a","Jessica takes Leto's dagger. She lies down near him and takes hold of his right hand."],["a","She makes a cut in his finger. The blood flows. The wind, like a hurricane, shakes the curtains. Jessica helps the Duke penetrate her with his blood-stained fingers."]]},{"n":37,"h":"INTERIOR. JESSICA'S VAGINA. MEMORY","b":[["a","Red interior of Jessica's vagina. The walls of the vagina are throbbing."],["a","A drop of blood is moving towards the ovary."],["a","The sound of wind and Jessica's voice chanting a mantra."],["a","The drop of blood lodges in the ovary, and divides it in two."],["a","The moment of fertilization resembles a cosmic explosion."],["p",96],["i","Drop of blood fertilizing the ovary.",null,null,true]]},{"n":38,"h":"INTERIOR. JESSICA'S DRAWING ROOM. MEMORY","b":[["a","Jessica, pregnant, is sitting near Leto and looking out on to the landscape in bloom."],["a","Leto is talking to her with love and tactfulness."],["d","LETO","The Major Houses expect me to make an alliance in the shape of a marriage. It is useful to let them continue to foster these hopes. You can only be my mistress."],["a","Jessica, smiling : We exist only to serve."],["d","LETO","I will let them foster these hopes, but never shall I take a wife."],["a","The memories fade. Jessica is sitting in the same position, looking, sadly now, out over the landscape, where the crowd can be seen boarding the Guild's ship. Near her, instead of the Duke, sits the Reverend Mother."],["d","THE REVEREND MOTHER","We ordered you to give birth to a girl and you produced a boy. Through pride. For wanting to be the mother of Kwisatz Haderach, you have thrown the lines of genetic descent into disorder."],["d","JESSICA","I did it for the Duke. It was important for him."],["d","THE REVEREND MOTHER","You behaved like an animal."],["d","JESSICA","I shall never regret it."],["d","THE REVEREND MOTHER","Oh but you will regret it. The drug has shown you and your son running away like criminals tracked down by thousands of hunters."],["d","JESSICA","I knew it. Dune is a trap. I shall pay for my mistake."],["d","THE REVEREND MOTHER","Your son will pay for it with you."],["d","JESSICA","I shall protect him."],["d","THE REVEREND MOTHER","If you are over-protective, he will never be strong enough to fulfil his destiny, Call him. If he is not"],["p",98],["a","the Kwisatz Haderach, it will be a catastrophe."],["a","Jessica goes out. Jessica opens the door, and lets young Paul into the room. Jessica kneels down on front of the Reverend Mother and touches the ground with her forehead. Paul watches his mother and imitates her."],["d","JESSICA (to Paul)","You are going to do everything the Reverend Mother asks."],["a","Paul sits down. Jessica leaves the room looking very worried. The reverend Mother presses a button and the curtain closes. Half-light."],["d","THE REVEREND MOTHER","Come closer."],["a","Paul comes closer. The Reverend Mother smiles. From the folds of her clothing, she takes out a green metal cube with sides about 6 inches long, and turns it around. One of the sides shows a hollow where no light enters."],["d","THE REVEREND MOTHER","Put your right hand here."],["a","Slowly, Paul puts his hand inside the cube, which begins making an electronic noise."],["a","The old woman, like a beast of prey, puts her right hand on Paul's neck while holding up the cube with her left hand. Her right hand is holding a strange arm with a needle at its end. Paul tries to move his head to see what it is."],["d","THE REVEREND MOTHER (IN HER INHUMAN VOICE)","Stop."],["a","Hearing the inhuman tone of the voice, Paul is forced to obey. He remains motionless."],["d","THE REVEREND MOTHER","You have a Gom Jabbar near your neck. If you take your hand away, you will die in 2 seconds."],["a","Paul tries to calm his feeling of terror."],["d","PAUL","What's inside ?"],["d","THE REVEREND MOTHER","Suffering."],["d","PAUL","Why ?"],["p",99],["d","THE REVEREND MOTHER","To find out if you are really human."],["d","PAUL","It's burning me."],["d","THE REVEREND MOTHER","Be quiet !"],["a","The noise of the machine becomes louder, and Paul's painful expression increases. He is sweating and digging his fingers into the palm of his free hand. He bites his lips so as not to cry out. The bones of his hand can be heard cracking. The sizzling of burning flesh, and the sound of bones breaking ; this is the highest degree of suffering, but Paul endures it without flinching."],["d","THE REVEREND MOTHER","Nobody has ever endured such suffering."],["a","The Reverend Mother moves her hand and the noise of the cube stops. The pain stops immediately as well."],["d","THE REVEREND MOTHER","Take out your hand."],["a","Paul does not want to look at his hand, which he thinks must now be nothing more than a stump."],["d","THE REVEREND MOTHER (IN HER INHUMAN VOICE)","Take out your hand."],["a","Paul obeys slowly. He sees with amazement that his hand has remained intact."],["d","THE REVEREND MOTHER (laughing lightly)","Pain by nervous induction. (calling him) : When your mother took the Gom Jabbar test, she sat down beside me and I caressed her."],["a","Furious, Paul steps back."],["d","PAUL","I'm not my mother."],["a","Jessica enters and goes to kiss Paul, who pushes her away. She stops beside the Reverend Mother."],["d","THE REVEREND MOTHER","We can see into the past and the future, but we only use feminine methods. There is a place in time, like a dark spot, which we cannot reach. One man will discover what we cannot see, through our drug."],["d","PAUL","The Kwisatz Haderach ?"],["p",100],["d","THE REVEREND MOTHER","Yes. He will know the infinite possibilities of time. We have given our drug to a number of men, and all of them have died. Perhaps you will resist?"],["d","PAUL","You seek the Kwisatz Haderach so as to be able to use him for your horrible political purposes. But you have said nothing which might help my father."],["d","THE REVEREND MOTHER","If we were able to do something for him, we would have done it. Because of the myth which Our Missionaria Protectiva has spread in Dune, perhaps you two will be saved. But your father will die."],["a","Paul, stooping, trying hard not to show his sorrow, opens the curtains and breathes the twilight air. Bird songs and river noises can be heard."],["d","THE REVEREND MOTHER (IN HER INHUMAN VOICE)","Paul !"],["a","At the sound of the Voice, Paul falls into a hypnotic trance."],["d","THE REVEREND MOTHER","Never tell that to anyone !"]]},{"n":39,"h":"EXTERIOR. HARKONNEN CASTLE","b":[["a","Approaches to the sombre castle, bathed in the sound of sea waves."],["a","Bestial laughter. Music. Snatches of conversation."],["a","On the central balcony, Peter, the Baron's Mentat, and Feyd Rautha, the Baron's nephew and lover, can be seen playing chess."],["p",102],["i","The Harkonnen Castle, figures in a window",null,49,true]]},{"n":40,"h":"EXTERIOR. HARKONNEN CASTLE BALCONY","b":[["a","Peter and Feyd are sitting opposite each other. They are playing chess with a set where the pieces are shaped like spiders and scorpions on the Mentat's side- and like butterflies and wasps on the nephew's side."],["a","Beside Peter there is an outfit containing 24 hypodermic syringes arranged inside a clock-face. The syringes are filled with liquid spice. Peter looks at the time on a tiny watch-ring, takes out a syringe, places it in a surgical revolver and injects it into his leg. As the liquid progressively enters his blood, he moans with pleasure."],["a","Feyd : Why is my uncle giving a party? We've just lost Dune !"],["a","Peter : Lost Dune ?"],["a","And he bursts out laughing."],["p",104],["i","The chess board with insect pieces",null,null,true]]},{"n":41,"h":"INTERIOR. THE HARKONNEN DRAWING-ROOM-SWIMMING POOL","b":[["a","A frantic party. The walls are composed of thousands of gargoyles ; each of their mouths is spitting waves of wine. The floor is an enormous swimmingpool filled with wine, with passages and platforms made out of crystal. The pool is not deep, and the guests are in it, swimming, sitting or floating in the drink. A large proportion of them, with their mouths open, are drinking the streams of wine dropping from the gargoyles ; large hogs are swimming around, eating up the left-overs of food."],["a","Old half-naked women, between 70 and 80 years old, are dancing an erotic ballet together with effeminate young adolescents."],["a","On a palanquin, carried on their shoulders by a group of children disguised as Cupids, Baron Vladimir Harkonnen can be seen entering, his enormous body lying on its side, his face smiling. It's a splendid entry, as his master at arms Uman Kudu makes a way for him to pass through."],["a","The palanquin arrives at the central platform, passing over the old women, who, with their bellies, pay obscene homage to the Baron. Uman Kudu forces them aside with lashes of his whip. Slaves enter, carrying the food for the banquet. They circle around the palanquin offering various dishes to the Baron, so that he can have first choice. The slaves are young and strong, dressed in loincloths and made up like women. The baron helps himself to a tiny portion of each of the hundred dishes. The rest is thrown to the guests who fight for their meal."],["a","On a large plate of fried ostrich eggs, the baron only takes a small piece of bread. From giant artichokes, he takes just a leaf. From a paté of canaries' tongues arranged in the middle of a thousand dead canaries, blood stained and with open beaks, he takes one tiny"],["p",106],["a","little tongue. From an eight-hooved bull, entirely roasted, he cuts himself a bit of testicle."],["a","When, on his plate, he finally has a heap of food, three old toothless slaves, at each side, suck his fingers, made greasy by the food, so as to wash them. Lambs' heads are thrown into the pools. The guests dip them in wine. A group of monstrously fat naked women is then hurled into the wine. The guests rush towards them. Orgiastic, sinister, elephant-like scenes follow."],["a","The baron lets himself be applauded and adulated. He finishes eating. Uman Kudu cracks his whip. The band falls quiet, the gargoyles stop spitting wine, the pool empties. Powerful fires light up the gloom. The guests silently steal away from this crude light, like nocturnal animals wounded by daylight."],["a","The baron remains alone with Uman Kudu in the centre of the deserted room. Uman Kudu cracks his whip again. More slaves appear. They fix his anti-gravitation devices on the baron ; these are electronic appliances adjusted to his body, enabling him, in spite of his weight, to float like a feather. A pack of dogs, with their mouths made up, enter the room : snouts with painted lips, false eyelashes, necklaces, curly wigs, ear-rings. They run excitedly around the Baron."],["a","In an acute, tenor voice, Uman Kudu sings while the baron dances a weird parody of classical ballet, moving up and down like a sphere filled with gas... His dogs follow him, barking. As he dances, the baron throws them little pieces of raw meat, as if they were flower petals."],["p",107],["i","Harkonnen orgy",null,58,false]]},{"n":42,"h":"INTERIOR. BARON HARKONNEN'S NIGHT CLUB","b":[["a","An apartment like night-club. A theatre stage with footlights. On the floor, composed of various levels, plastic shapes designed for relaxation can be seen. In the middle of the shot is a large globeshaped cake, a replica of the planet Dune. The doors open and Vladimir Harkonnen, in euphoric mood, enters followed by Uman Kudu, Peter, Feyd and a group of slaves."],["a","With a greedy look on his face, licking his lips, the baron serves out pieces of the planet."],["d","THE BARON","A piece of desert ? A hurricane ? A spice-field ? A mountain chain ? A giant sand-worm ?"],["a","Peter nods to Uman Kudu. Crack of the whip. A curtain draws back. A group of Guild officials surrounds a wooden case like the cases they used for packing various objects at Caladan castle. They open the case, which they spread out on the floor in the shape of a cross. There lies Dr. Wellington Yueh, asleep."],["a","The Guild members stick a small tube into Yueh's mouth. They pour liquid down it. Yueh wakes up. The Guild men, forming a compact group, come together in a corner of the room. Peter nods again to Uman Kudu. Crack of the whip. On a rolling platform, servants bring a slave, standing fastened against a pillar, an adolescent looking like saint Sebastian."],["a","Yueh sits down in a Yoga meditation position. Motionless, he waits for what comes next."],["a","Peter takes a cross-bow gun loaded with arrows and gives it to Yueh. Uman Kudu grabs hold of Yueh's arms to stop him shooting off in a false direction."],["p",109],["d","PETER","Dr. Yueh, shoot this slave !"],["a","Yueh smiles gently and points to the diamond inlaid in his forehead."],["d","YUEH","The Suk School. Imperial conditioning. Mutilated agressivity. I cannot kill."],["d","PETER","Any conditioning can be eradicated. All that's needed is a means of pressure."],["a","Nod. Crack of the whip. A wall rises, revealing a torture room. The prisoner of a complicated and sadistic machine, Wanda is revealed naked. She is fourteen years old."],["d","YUEH","(beside himself) Wanda ! (to the Guild's men) Hypocrites ! Traitors ! (to the Harkonnens) Murderers !"],["d","PETER","Dr. Yueh's love for his wife will be our means of pressure."],["a","Vladimir and Feyd applaud Peter, like for a play at the theatre."],["a","Yueh, having suddenly calmed down, sits back again in a position of mediation. He remains impassive, but tears are running down his checks."],["a","In the torture room, Peter reveals a strangely shaped machine, joined by a tube to an energy source. He moves the machine on to one of Wanda's hands. A ray light crackles. Wanda screams with pain and faints. Her hand whitens, becomes covered with an icy film, hardens and changes into crystal."],["a","Peter takes hold of a small hammer. Yueh cries out. Peter brakes the glass hand. Wanda's stump can be seen. Yueh groans in despair. Again, Uman Kudu gives him the cross-bow gun. Yueh tries to shoot the slave. But he is overcome with epileptic shaking. With his mouth foaming, he falls down on the ground. He is helped up. He cannot kill."],["a","Peter freezes one of Wanda's ears. He changes into crystal and breaks it. He then aims for Wanda's breast with the intention of transforming it into crystal."],["a","Yueh takes the crossbow and riddles the slave with arrows ; he dies like Saint Sebastian."],["p",110],["d","THE BARON","You are to kill Duke Leto Atreides."],["a","Yueh nods his assent. Vladimir motions to Peter to stop the torture."],["d","THE BARON","You are also to kill his son and his mistress."],["d","PETER","Not Jessica ! You promised me !"],["d","THE BARON","I sometimes forget that a Mentat murderer has a human body."],["a","The Guild officials send Yueh to sleep. They shut him in the case and carry him away. Before going to sleep, Yueh, in despair, saw the torture room wall close, separating him from Wanda."],["a","The baron, satisfied, finishes off his sorbet, yawns and looks lustfully at Feyd. He pulls on a cord. The floor opens revealing a canal full of water. There are walls, giving out on to two tunnels. The water brings along a gondola, composed of two horses with the bodies of gold sea serpents. The back of the seats are made to look like two mammoth animals."],["a","The baron turns out the lights. In the darkness of the bedroom, a false sky dotted with stars can be seen. Only the boat is lit up. The baron goes aboard and sends Peter away."],["d","THE BARON","Your salary."],["a","Uman Kudu gives Peter a clock-face of 24 full syringes. The baron and Feyd, sitting in the boat, go out through the tunnel while Peter avidly injects himself with a dose of spice."],["a","The baron leans his nephew's head on his shoulder."],["a","BARON (murmuring sensually). They have all betrayed Leto. We shall betray them all. The Harkonnens can be emperors too."],["a","The gondola disappears in the darkness of the tunnel."],["p",111],["i","Baron in gondola, Wanda tortured, Feyd watching, Yueh with bow",null,65,true]]},{"n":43,"h":"INTERIOR : PAUL'S GYMNASIUM","b":[["a","A gymnasium. Weights, ladders, ropes, trapeziums, etc.. On the walls, anatomical engravings and very advanced geometrical studies can be seen."],["a","On a table, two by two, are all kinds of arms : pickaxes and masses of arms, sticks, hooks, saws, etc.."],["a","On a platform, dressed as Masters at arms, Duncan Idaho, Gurney Halleck, Thufir Hawatt and Wellington Yueh are all sitting in great ceremony, together with a mysterious individual wearing a large hat and full clothes. Impossible to see who he is. His hand is rhythmically waving a fan. Paul, dressed for combat, with his shield, sword-belt and sword, bows in front of his masters. He raises his head and makes as if to speak, but the stranger's presence stops him. He seems very sad."],["d","HAWATT","Speak. He's a friend."],["d","PAUL","We are leaving Caladan today. I'd prefer not to have a lesson."],["a","Idaho gives a violent roar and, with a punch, knocks him down."],["d","IDAHO","Don't mix feelings and fighting. Happy or sad, the Harkonnen won't spare your life. If you can't defend yourself, you might as well die straight away."],["a","Hawatt moves towards the stranger, takes the fan away from him, as well as his hat. A faceless ball of steel appears : It's a robot!"],["d","THUFIR","This robot will judge your courage, your speed and resistance. You cannot defeat him. If you try, you'll die. The longer the fight lasts, the more he'll confirm his superiority over you and the better he'll attack."],["p",113],["i","Paul fighting the robot",null,null,true],["p",114],["a","Thufir Hawatt opens a window in the robot's head. He reveals a microphone micro-cell."],["d","THUFIR","What's your name ?"],["d","PAUL","Paul."],["d","THUFIR","He has recorded your voice. From now on, you alone can stop the fight."],["a","Thufir pushes a button. The machine gets up, draws its sword and slowly comes face to face with Paul. It records each of his movements, the sound of his breathing, the beat of his heart. Paul attacks the robot and tries to throw him to the ground. The machine, clumsy as first, becomes more agile and stronger as it records Paul. The robot falls down and gets back up, each time more powerful. The fight becomes faster and more sustained. The robot records each blow, movement or noise made by Paul. The combat is now taking place at a giddy rate. Paul doesn't want to surrender. He feels himself overcome by a suicidal euphoria. The robot becomes monstrously aggressive."],["d","THUFIR","That's enough !"],["d","DUNCAN","Stop him !"],["a","Paul continues fighting. The machine's capacities are increasing. Paul falls down. As he dodges it, a blow of the robot's sword cuts the table in two and splits open the floor."],["a","Thufir breaks a pane of glass and takes out a laser-thrower Idaho and Halleck throw themselves on to Paul and make him roll across the floor. Thufir shoots. The robot explodes, throwing its smoking parts out on to the ground."],["a","While everyone gets up and makes sure that nobody is hurt, Leto, followed by Jessica and a group of soldiers, enters the gymnasium with a sword in his hand."],["p",115],["a","Paul, on his knees, his head lowered, sad and depressed, is incapable of weeping."],["a","The Duke draws near him and kneels beside him understandingly. Hawatt, Idaho, Halleck and Yueh move away discreetly. Jessica sits in a corner, hidden in the shade, and listens."],["a","Leto puts his arm around Paul's neck, drawing him closer. Paul leans on his father."],["d","PAUL","I have something to tell you, but I can't..."],["d","LETO","I know. Dune is a deadly trap."],["d","PAUL","Then why are we going ?"],["a","The Duke stands up, goes towards a wall and switches on a screen. A long list of figures appear on it."],["d","LETO","How much does that come to ?"],["a","Paul gives a quick look and answers unhesitatingly :"],["d","PAUL","Nine million four hundred and seventy five thousand six hundred and eighty nine."],["a","Leto changes the image on the screen, which fills up with a maze of figures in disorder."],["d","LETO","How many figures are there here ?"],["d","PAUL","(after a glance) : One thousand three hundred."],["d","LETO","How many nines ?"],["d","PAUL","Two hundred and fifteen."],["d","LETO","And fives ?"],["d","PAUL","A hundred and sixty four."],["a","Leto switches off the screen and comes back towards Paul."],["d","LETO","Paul, your brain has the power of a computer. Use that capacity..."],["p",116],["a","He picks up the pieces of the Robot and begins to put them away like tin soldiers."],["d","LETO (setting down a large piece)","The Emperor ! (surrounding it with pointed pieces) His Sardaukars : the Galaxy's most powerful army ! (He puts three pieces together) The Major Houses. There are not many of them, but they're rich. (setting down a piece with nuts on it). The Guild ! Masters of Industry and Transportation, working for the highest bidders : The Emperor and the Major Houses (opposite, he puts a lot of little separate pieces) The Minor Houses ! There are a lot of them, poor and disunited. (pointing to the other group) The only way the Minor Houses have of fighting against this block is to be united, which is not happening because the other side, infiltrating spies and agitators, is inciting internal hate, wars and the overthrows of governments (He takes a red piece) Duke Leto Atreides ... (he puts it in the middle of those pieces representing the Minor Houses) Being very popular, he can bring about this unity (he brings together the other pieces round the red piece). The block thus created outnumbers the opposing block)."],["d","PAUL","You would break the economic Block and the Minor Houses would become the greatest power."],["d","LETO","The Spice can only grow on Dune (he takes a metal board and puts the red piece on it). They are sending me there so that I fail and production comes to a halt. Then the Emperor and the Major Houses who, through years of smuggling, have accumulated the Spice can sell it at exorbitant prices ! And I will lose all my reputation with the Minor Houses (putting all the Minor Houses' pieces beside the Emperor's). Our friends will support the Emperor for money (He hits the metal board representing Dune). Even on Dune they will try to sabotage our installations, block our progress and destroy us."],["d","PAUL","We're lost !"],["p",117],["d","LETO","There is one hope (he pours a pile of screws out on the board, around the red piece). The Fremens : a warlike race spread out in the desert, who've endured, without water, hurricanes, sand storms, the burning sun and various persecutions. With their help, we can form an army more powerful than the Imperium's (he takes the Major Houses' pieces suddenly off the board). The solution lies in the very heart of the trap. That's why we are going to Dune. It's time to leave."],["a","Leto leaves. Jessica comes out of the shadow."],["d","PAUL","We have one chance in a thousand of surviving !"],["d","JESSICA (IN THE INHUMAN VOICE)","Attack me !"],["a","Paul, forced to attack her despite himself, draws his sword. Still using the Voice, Jessica utters a cry which paralyses his arm. She cries out again, and Paul falls down, and again, and now he can finally move. He gets back up."],["d","JESSICA","Use the Voice. Paralyse me."],["d","PAUL","I don't dare to."],["d","JESSICA","Go on !"],["a","Paul cries out fearfully, using the Voice. Nothing happens."],["d","JESSICA","I'm not your mother ! I'm an object ! An illusion ! Free me ! Shout !"],["a","Paul shouts. Jessica falls on the ground, paralysed. Paul, alarmed, tries to make her move again. She remains motionless and stiff. Paul cries out twice in vain. The third time he succeeds. Jessica happily gets up, massaging her body and head in the places where the fall had bruised her."],["d","JESSICA","You've already almost mastered the Voice ! We'll survive !"],["a","Rain begins to fall on the transparent dome covering the room."]]},{"n":44,"h":"EXTERIOR OF THE BIG SPACE-SHIP. CALADAN","b":[["a","It's raining."],["a","The last of the cargo is being loaded. Weeping families say their goodbyes to the soldiers."],["a","A siren can be heard. Before going aboard, the soldiers drink the falling water, their arms open under the rain."]]},{"n":45,"h":"EXTERIOR. DOORS OF CALADAN CASTLE","b":[["a","It's raining."],["a","Leto, Jessica, Paul, Halleck, Hawatt, Idaho and Yueh are waiting for the last soldiers to close the castle's great doors."],["a","Leto turns an iron key in the lock. He takes it out and, overcoming his sadness, presses it with both his hands against his heart. He then places the key in a little bag, which he hangs on Jessica's neck."]]},{"n":46,"h":"EXTERIOR. CALADAN LANDSCAPE","b":[["a","The big space-ship belonging to the Guild takes off. It becomes a point which soon disappears in the immensity of sidereal space."]]},{"n":47,"h":"EXTERIOR. STREETS OF ARRAKEEN. DUNE","b":[["a","The little town of Arrakeen is built in the middle of the desert. Nearby, Harkonnen banners are flying on the government palace. The atmosphere is one of heat, dryness, and whirls of wind raising sand-cloud. Half-starved donkeys graze on the rare clumps of grass growing on the dunes. Vultures are eating on a dead camel, lying with its legs in the air."],["a","The Harkonnen army, dressed and made up in a ridiculous manner, is persecuting beggars, massacring them in the streets. Throwing down doors and windows, they murder children, old men, women and disabled people."],["a","Drunk with blood and anger, Rabban the Beast is among them, transported in a chariot drawn by slaves with shells on their backs like horses, and reins in their mouths. Rabban whips them continually to make them run."],["a","Rabban looks up at the sky. He sees the large Guild ship bringing all the Atreides, looking like a distant sphere. He spits towards the sky, not caring that his saliva falls back on his face."],["d","RABBAN","SONS OF BITCHES ! You'll get to know Rabban the Beast."]]},{"n":48,"h":"EXTERIOR. GOVERNMENT PALACE","b":[["a","Opposite the government palace, there are a fountain and a palm grove of twenty trees, surrounded by gates and barbed wire. A crowd of beggars crowd around the fountain as if in a trance and watch the water running with expressions of thirst, adoration and greed. Others near the palm trees are watching a soldier who is watering the trees with a large bowl mounted on rollers. A gust of wind blows away a few drops of water which fall on the ground, outside the barbed wire. The beggars fight and the victor licks at the little muddy patch of damp sand."],["a","Rabban the Beast and his soldiers burst in on this scene like a hurricane."],["a","They throw grenades on to the fountain which explodes, killing the beggars who were surrounding it."],["a","The soldiers chase after the beggars who are running away like animals, and execute them."],["a","A beggar, dying, drags his body as far as a little pool which is all that remains of the fountain and drinks up the last few drops of dirty water."],["a","An old man and a group of beggars are the only people still on the scene. Rabban catches hold of the old man by his neck and, half strangling him, lift him in front of the palm trees."],["d","RABBAN","How many times have you come to see my palm trees ?"],["d","THE BEGGAR","Every day, for thirty years."],["d","RABBAN","How much water does each tree need ?"],["d","THE BEGGAR","Forty litres a day."],["d","RABBAN","How much water does a man need ?"],["d","THE BEGGAR","Eight litres."],["d","RABBAN","Twenty palm-trees, a hundred men."],["p",123],["d","THE BEGGAR","Every day enough water for a hundred men !"],["d","RABBAN","What were you doing sitting here ?"],["d","THE BEGGAR","I was watching for the wind to blow away a date and drop it into my hand."],["d","RABBAN","Your patience will be rewarded."],["a","The beggars are fastened against the trees. The old man is bound to the top of the tree, near the dates. The trucks are soaked with petrol. Rabban sets the palm-grove alight with a torch."],["a","While the trees are burning, Rabban looks up at the sky. The ship has come nearer. He enters the government palace, followed by his soldiers."]]},{"n":49,"h":"INTERIOR. HALL OF THE GOVERNMENT PALACE.","b":[["a","Rabban's soldiers bring Fremens servants, old men, slaves and women out from the Palace."],["d","RABBAN","Bring them all out to me ! I won't leave them a single cook, manservant or sweeper."],["a","On a sign from Rabban, the servants are killed. Rabban enjoys himself chasing after the children to massacre them."],["d","RABBAN","I want soldiers !"],["a","He calls them, shouting loudly. The soldiers begin to arrive. More and more of them are coming, but Rabban still isn't satisfied."],["d","RABBAN","More, more !"],["a","The hall is full of soldiers who can hardly move."],["d","RABBAN","Take your trousers down !"],["a","The soldiers obey, afraid of leader. Rabban also takes down his trousers."],["d","RABBAN","The first soldier who doesn't shit will have his head cut off !"],["a","The he crouches down and tries to defecate. The soldiers follow his example."]]},{"n":50,"h":"EXTERIOR. LANDING STRIP AND ROAD.","b":[["a","The large Guild ship lands on the strip. There is only one space-ship bearing the Imperium's emblem on the strip. A truck, in which count Fenring and his wife are sitting, comes out of this ship. Under Fenring's orders, an army of Sardaukars draw up on the direct road from the ship to the government palace."],["a","With mathematical precision, the Sardaukars separate into two files, in the middle of the road and along the whole of its length. One file watches over one side of the road and the other the opposite side. The file goes from the airport to the Palace."],["a","Count Fenring and his associates stand in front of the door of the ship which has just landed. The walls slide apart and Duke Leto appears, surrounded by his soldiers. Fenring bows slightly in front of Leto and brandishes a rocket-launching pistol."],["d","FENRING","The armies will begin to move only at my signal !"],["a","At full speed, Fenring's truck and his associates hurtle towards the palace, raising a cloud of dust. At the roadside some beggars are watching the truck. Free, haughty Fremens, with covered faces exposing only their completely blue eyes, are spying on the scene, half-hidden in the dunes."],["a","Fenring arrives at the Palace. Rabban is ready to face his troops."],["a","When the armies meet, the ten soldiers forming the last line in each army begin to mark time, on the spot. The armies move apart, one towards the ship, the other towards the palace."],["a","The two groups of ten soldiers are standing in the middle of the road. Suddenly, they attack each other and begin a ferocious but silent battle, so as not to give the alarm. Two Sardaukars run up."],["a","Nobody pays attention to them. Both Sardaukars then enter the fray and, in a fraction of a second, kill the twenty combatants."],["p",126],["i","Two armies passing each other from and to the palace",null,null,true],["p",127],["a","Fenring, who is arriving from the Palace, picks up the two Sardaukars in his truck. All the Sardaukars are boarding the imperial ship."],["a","The twenty bodies are lying on the road. A group of beggars in rags come up to them like a swarm. They begin to undress them and fight for their clothes. The group of free Fremens scares them away. The new arrivals cover the bodies with special cloths. They adapt little machines to these covers, each machine terminating in a tube. Under each tube, they put a container. They turn on the machines, and extract water from the bodies. As the containers fill up, the bodies shrink under the shrouds."]]},{"n":51,"h":"EXTERIOR. GOVERNMENT PALACE","b":[["a","The Atreides soldiers are making a big bonfire of the Harkonnen banners and emblems, while others are hoisting the Atreides coat of arms : the red falcon on a green and black background. Soon, a hundred large flags are flying in the wind, giving the palace a new face."],["a","As the war trucks, ambulances and transport lorries arrive, the army becomes organized."],["a","Leto, his family and chief of staff are following and directing operations."],["d","LETO (to Duncan Idaho)","Help the wounded ! (to Gurney Halleck) Search all the villages !"],["a","Halleck and Duncan run and carry out the orders ... Two groups of cars, soldiers and ambulances go off raising a thick cloud of dust."],["a","Gradually, the cloud disperses. Thousands of beggars come out of it and silently sit on their heels. Soon they fill the square, like a calm ocean of tattered rags."],["a","All at the same time, their mouths produce a noise like a hooting while their hands pound together two little stones. The noise is deafening."],["p",129],["a","Leto raises his arms and imposes silence. He shows the transport lorries to his soldiers and gives an order. The soldiers line up the lorries in front of the palace doors. The people can see enormous demijohns on them, filled with water. A great deal of confusion seizes the crowd, which is astonished and envious and wants to see the water from near at hand. The Atreides re-establish order, without brutality. The Duke addresses the people, very calmly but with sincere emotion :"],["d","LETO","We are not the Harkonnen ; we are Atreides ! We have not come to steal, to exploit the weak, not take anybody's water away ! We do not want to impose our power by force : We want no slaves ! We want colleagues ! The spice-fields will bring in enough money to fill this world with water !"],["a","Like one man, the people bow down. They all stand up straight again and begin walk away. Some place gifts at Paul's and Jessica's feet : Cactus fruits, stone necklaces, snakes eggs. They are murmuring \"Mahdi\"."],["a","An old Woman comes up, and kisses the hem of Paul's cape."],["d","THE OLD WOMAN","You are the holy child of the legend, son of a Bene Guesserit ! You will take us out of this hell !"],["a","One by one, the beggars kiss Jessica's and Paul's clothes. Paul is embarrassed. Leto urges him forward towards the beggars, murmuring :"],["d","LETO","They take you for the Messiah ! You must profit from this myth."],["a","Soon, the square is empty. The soldiers and the chief of staff have left. In the distance, a man claiming to have discovered water shouts out his fantastic cry. Leto, Paul and Jessica are now alone in the middle of the dust. Paul has filled his cape with the gifts donated by the beggars. Among them is a rag doll resembling him in the arms of another doll dressed like a Bene Guesserit. Both dolls have completely blue eyes. Leto is sad and preoccupied. Jessica takes the key of Caladan castle out from its velvet bag, caresses it and, determinedly, kneels down, digs a hole in the sandy earth, puts the key in it and covers it with earth. Walking resolutely, Leto, Jessica"],["p",130],["a","And Paul move towards the palace. The wind has erased their footsteps where the key was buried."]]},{"n":52,"h":"EXTERIOR. AN ARRAKEEN STREET","b":[["a","Idaho and his group of soldiers are actively helping the people to put out fires with buckets of sand, take the wounded out from the wreckage, and bandage the wounds. Besides the ambulances, files of wounded and laid out on stretchers. The Atreides have improvised a hospital. While the soldiers make bandages, Duncan Idaho organises blood transfusions."],["a","A group of free Fremens, distinguishable from the Beggars by their haughty walk and strange clothes, watch Idaho's actions with discretion. The completely blue eyes of the man appearing to be their leader are staring at the bottles of blood. The liquid sound of blood running in the tubes makes his ears move slightly, like an animal's."]]},{"n":53,"h":"EXTERIOR. A TOWN IN THE DESERT","b":[["a","Duncan, his ambulances and soldiers are approaching a town built in the middle of the rocky desert. The aftermath of battle can be seen : smoke, charred doors, streets full of bodies."],["a","A group of free Fremens is hiding among the rocks, the leader speaks to one of them, who begins to run towards the Atreides, like a deer. From behind the dunes fifteen Harkonnen soldiers emerge, ready to bar his way."],["a","The fremen draws a strange short, phosphorescent sword and scrapes the ground with it, surrounding himself with a cloud of dust which seems impenetrable. The Harkonnen enter the cloud. They come out of the strange dust mortally wounded, one after the other... All fifteen of them die. The Fremen comes out of the cloud, covered with wounds and staggering. He runs towards the Atreides."],["a","The Fremen in agony stops Duncan when the latter has just arrived at the town gates. He no longer has strength enough to speak. He draws his sword, gives it to Idaho, points to the sky, makes a negative motion and dies."],["a","Idaho looks up at the sky above the town and understands."],["d","IDAHO","There isn't a single vulture ! It's a trap ! Shoot the bodies !"],["a","The Atreides get ready and attack. The \"dead\" tear off their disguises revealing the Harkonnen uniform and hurl themselves into attack against Idaho's soldiers. Outnumbered, the Atreides are soon in great danger. The Fremens come silently out of the desert and throw birds of prey who go and peck at the Harkonnen's eyes. The Fremens use the resulting confusion to rapidly finish off the Harkonnen. The Fremens' leader speaks to Duncan :"],["d","FAROK","You have helped our brothers ! .. We have saved your life... The debt of water has been paid."],["a","The Fremens go off into the desert. Duncan pulls on the Fremen arm hidden under his cape, and takes it out of its sheath. To his great surprise, it gleams and gives out a vibrating sound."]]},{"n":54,"h":"JESSICA'S BEDROOM","b":[["a","With the help of soldiers, Jessica is busy making her bedroom look pretty. She has painted gardens, a valley, mills and a river on the walls. The whole room is a picture showing the Caladan landscape. Her assistants are putting up flowered curtains. Jessica is finishing a paper branch ornamented with roses."],["a","Soldiers enter, together with a group of female Fremen servants : beautiful women with blue eyes wearing the brown garment of slaves. Among them, there is an old woman called Mapes."],["a","All the others kneel down, except her."],["a","Jessica (to the soldiers) : Let nobody enter until I call ..."],["a","The soldiers, as well as those who were working on the room, go away closing the door behind them."],["a","Jessica violently confronts Mapes."],["d","JESSICA","Do you think I'm blind ? You're no servant...! You have had six children. All of them have died. You have killed men, and you'll continue to do so !"],["d","MAPES (surprised)","You can ....!"],["d","JESSICA","I heard the grandmother's voice !"],["a","Mapes falls to her knees, moved but still in doubt."],["d","JESSICA","You are hiding a dagger under your blouse !"],["a","Mapes draws out a black sheath from which she pulls a white, phosphorescent arm."],["d","MAPES","A gift if you are really Her !"],["d","JESSICA","And an instrument of death if I'm not !"],["a","Mapes gets up and, arm in hand, dangerously draws near Jessica."],["d","MAPES","Tell me what it is !"],["p",134],["d","JESSICA (guessing)","A tooth !"],["a","Mapes cries out and falls to her knees. All the Fremens touch the ground with their forehead."],["d","MAPES","You are Her ! (giving her the arm). Carry it on your body. Far away from you, it would disintegrate after a day. Let it accompany you till death ! It's a tooth of Shai-Hulud, the great father of the desert, the holy Worm of the sand !"],["a","Jessica (relentless) You draw out and put away this Krys without shedding blood ?"],["a","Mapes opens her blouse. She shows her hanging breasts."],["d","MAPES","This is the water of my life !"],["a","Jessica gashes her right breast, and a trickle of blue blood coagulates immediately, secretly. Mapes passes her hand over the encrusted blood which falls into dust, leaving no scar. She closes her blouse."],["d","MAPES","The legend is beginning to happen ; you are one of us. You will not leave this planet alive."],["a","Jessica opens her blouse and puts the Krys away between her breasts."]]},{"n":55,"h":"EXTERIOR. GOVERNMENT PALACE.","b":[["a","Groups of beggars, water sellers, lorries, and the group of soldiers under Duncan Idaho can all be seen. A car in which Leto and his group are sitting arrives at the Government Palace gates. Idaho has displayed some objects on piece of cloth."],["d","DUNCAN","The Fremens send us these gifts : distilling devices to economize water, jewels for Lady Jessica, spice brandy, medicinal plants... and something special for me."],["a","He points to the black sheath which contains the Krys of the dead Fremen. He makes as if to take out the arm, but a voice from the group of beggars stops him."],["d","VOICE OF FAROK","Leave it in its sheath !"],["a","Everyone is looking. Farok emerges from the group of beggars. The guards draw their swords."],["d","IDAHO","Stop ! He has saved my life."],["a","The guards let Farok come closer towards Idaho."],["d","FAROK","This arm belonged to a man who gave his life for you. You alone can see it, but never impure men. Their eyes would stain the honourable blade !"],["a","The Atreides, offended, react brutally. The Duke stops them with a motion of his hand."],["d","LETO","(to Farok) I am Duke Leto Atreides, imperial governor of Dune. Do you allow me to look at this sword ?"],["d","FAROK","I allow you to win the right to see it !"],["a","Again the Atreides feel offended."],["d","HAWATT","Only the Duke can give orders !"],["p",136],["d","FAROK","The Duke wishes to govern in respect of those he governs ! The Kryses are ours. He who looks at them dies or becomes a Fremen."],["a","Furious, the Atreides become excited."],["d","LETO","One moment (to Farok, gently); you have saved the life of my men, I have a debt towards you. And I away pay my debts. If your customs intend this knife to stay in its sheath, I order that this be so ! If I can do something to honour the fremen who died for us, tell me and I'll do it."],["a","Farok stares at the Duke, slowly takes away the veil covering his face and spits at Leto's feet. The Atreides draw their swords."],["d","IDAHO","Stop ! (to Leto). Water is precious for them. Spitting is a mark of respect !"],["a","Idaho spits near Farok's spit and tells him."],["d","IDAHO","We thank you for the gift of the humidity of your body, and accept it with respect, as it was offered."],["a","The Atreides understand and calm down. At a sign from the Duke, Idaho hands the Krys to Farok."],["d","FAROK","You fight well, Duncan Idaho, do you wish to be purified and put yourself at my service ?"],["d","IDAHO","I must first consult the Duke."],["d","FAROK","You can serve both of us (to all the Atreides) Isah was the name of our dead brother. You are Isah's friends."],["a","Farok puts a distilling tube to his nose and his mouth, veils his face and walks majestically towards the desert."],["d","LETO","If all the Fremens are like this one, we have the men we need."],["d","IDAHO","They are all like that : proud and free. It will be difficult to organize them militarily !"],["p",137],["d","LETO","We need ten battalions of Fremens. We are depending on you, Duncan."],["a","Duncan puts on a distilling device. Duncan and Leto kiss each other. Duncan runs to catch up with Farok. Both walk in the desert until a dune obscures them from sight."]]},{"n":56,"h":"INTERIOR. PAUL'S ROOM","b":[["a","A large room. On the walls a painted ocean extends to the horizon, under a cloudy sky. The room is square, but the horizon painted on each wall is curved and gives the impression that the room is circular. A curtain follows the shape of a window, which is that of a cloud. The bed, the covers of which are like scales, looks like a big fish. Lamps the shape of shells hang in the air. Yueh, using a projector, is giving Paul lessons. Paul is sitting on his bed."],["a","The pictures show animals which, without being really supernatural, have characteristics distinguishing them from everyday animals : blue rats, falcons with horned beaks, beetles with butterfly wings."],["d","YUEH","A fox-kangaroo, a horned falcon, a blue rat, a pig-cactus, a scaled hare, royal beetles, all the animals to be found on Dune are \"water thieves\". They fight each other and steal the humidity from the body of the defeated animal. It is the only way to survive. If you lived in the desert, you would have to do as they do. Become a thief or die."],["a","Yueh unplugs the projector and puts it away."],["d","YUEH","Take this sleeping pill."],["d","PAUL","I don't want to sleep. I'm going to go for a walk..."],["d","YUEH","Obey your mother ! I'll only go away when you've swallowed this pill."],["a","Ill-temperedly, Paul puts the pill in his mouth, and immediately begins sleeping. Yueh covers him over, and presses on a fish's eye. The lights go out. Yueh goes away on tiptoe and closes the door."],["a","Paul sits up attentively. He masks the lights, smiles, spits out the pill and, running to the window, opens it and lets in the night air. He opens a cupboard shaped like a rock and goes to take out one of his clothes when he hears a noise near the bed. The fish's mouth opens, Paul doesn't move. An electronic insect four inches long comes out of the fish's mouth. The body is carrying a miniature bomb, and the head has a detonator-needle. The insect, which has two large ears, is humming."],["p",139],["i","Paul facing the hunter-seeker in his bedroom",null,351,false],["p",140],["a","The ears spot the noise made by the wind moving the curtains. The little machine flies to the window and suddenly stops. A strip of the blue floor cracks. The insect draws closer to it."],["a","Attracted by the light, a little night butterfly runs into the shelllamp. At the noise of the wings, the little machine moves closer to the lamp"],["a","Paul's breathing can be heard. The insect turns round and moves towards his chest. Paul concentrates, and stops breathing. The machine turns back to the butterfly, but the heartbeats bring it back to Paul who, again concentrating, stops the beating of his heart. The mechanical insect moves systematically around the room, coming and going everywhere. Each time, he comes nearer and nearer to Paul, and passes an inch or two from his body."],["a","A woman's footsteps can be heard. The machine stops. The door-handle moves. A red lamp lights up in the machine and shines towards the door. Paul is perspiring. The mechanical insect is buzzing louder and louder. Jessica gently opens the door so as not to wake Paul who she thinks is asleep. The machine rushes towards her. Paul, as fast as a cat, seizes it between his thumb and his index finger and struggles to immobilize it. The insect slowly slides from his fingers. Jessica, with the end of one of her long nails, unscrews the insect's body and takes out a bomb which she throws against the wall. At the same time, she throws herself to the ground, taking Paul with her. A part of the wall explodes into pieces."],["a","Jessica and Paul get back up and shake themselves. Leto, Yueh, Hawatt and the soldiers run in. Paul points to the little device."],["a","Thufir grunts fiercely and runs off, followed by his soldiers."]]},{"n":57,"h":"INTERIOR. GOVERNMENT PALACE CORRIDORS.","b":[["a","Like a madman, Thufir Hawatt, followed by his soldiers, runs along the corridor knocking down doors using his artificial leg as a battering ram. He knocks down the last door, and finds the control panel for the murderous weapon. Nobody is there. Thufir tears away the appliance and, taking some wreckage with him, leaves the room."]]},{"n":58,"h":"INTERIOR. PAUL'S BEDROOM","b":[["a","Looking tense, Leto, Jessica, Paul and Yueh are waiting. The door opens. Pushing aside the soldiers on guard, Hawatt enters the room. He closes the door and throws himself at the Duke's feet, his hands clenched on the remains of the remote control machine."],["d","HAWATT","I swear that I searched inch by inch (he weeps with grief) I'm too old, I give up."],["d","LETO","(stroking his hair). You have served three generations of Atreides. Your lessons have saved my son. You can do nothing against treason !"],["d","HAWATT","A traitor ?"],["d","LETO","Duncan Idaho, Gurney Halleck, Wellington Yueh or you. Whoever it is, I shall be just as griefstricken. We were a family, and a corrupt system has sown bitterness among us (he brings Paul to the window). In this sky, there is now nothing left but decay ! The human being has been wrecked ! We cannot continue to honour an empire of sick people, hypocrites and criminals ! We shall fight, even if we have to run away into the desert and become snipers."],["a","Jessica comes over to Paul and Leto. Yueh is thoughtful, alone in a corner. It is dawn. Through the windows, beggars can be seen putting the dew from the dune cactuses into collectors."],["d","JESSICA","Every morning, they collect the dew and live off it in the hope of a better world."],["d","LETO","We shall make that world, even if we have to set alight the Galaxy to do it !"],["a","Paul's face, lit up by the morning light, is filled with anguish. The same anguish can be seen reflected in Yueh's face."]]},{"n":59,"h":"EXTERIOR. A ROCKY WALL ON THE EDGE OF THE DESERT","b":[["a","Near the desert, inside the rocky wall, there is a cave closed off by a large stone wheel. The wheel turns and some Atreides come out of the cave, pushing an ornithopter : a little flying device like a bird with folding wings. It can hold four people. Escorted by soldiers, Leto, Paul and Hawatt emerge. They are wearing distilling appliances. As these have been put on incorrectly, this new garment hinders the walk of Leto and Hawatt. But Paul, who has adjusted his, moves nimbly as if he had always worn it. On top of it, they wear their arms : sword-belt, shield, paralyser, and a mass of arms (fan-daggers, a lancet-bearing bracelet, wide, short swords). In the distance, from the depths of the desert, ten fremens move nimbly forward, as if floating on the dunes. Their very fast walk gives an animal impression, something not human."],["a","Leto, Paul and Hawatt watch them from the cave with telescopes."],["a","In the middle of the Fremens, Kynes has unveiled his face. His wrinkled head is like a mummy's. His eyes are already completely blue. His long hair and beard are white. His walk and bearing are those of a young man."],["d","LETO","This man must be at least eighty !"],["d","HAWATT","Let's be careful ! If he doesn't like something, we lose the Fremens' support."],["d","LETO","Let's be ourselves ! No friendship can come out of deceit."],["a","While approaching the Atreides, the Fremens are watching them and murmuring to each other."],["d","KYNES","All that flesh full of water !"],["a","Fremen One : We could draw twelve litres out of each."],["a","Fremen Two : Their distilling devices have been put on incorrectly..."],["a","Fremen Three : The young one knew how to adjust his !"],["p",144],["i","Ornithopter coming out of caves on a cliff",null,54,true],["p",145],["a","Fremen Four : How did he know ?"],["a","Fremen Five : He knows but he can never have learnt"],["a","Fremen Six : The prophecy is coming true !"],["d","KYNES","It's only a man !"],["a","The two groups draw closer. The Atreides turn on their protective screens. Kynes introduces himself."],["d","KYNES","Pardot Kynes, Imperial ecologist."],["d","LETO","I thank the Fremens for these distilling devices."],["d","PAUL","There's no need, my Lord, every gift is a blessing for he who gives it."],["a","Kynes reacts smartly to this, as do the Fremens who murmur :"],["a","Fremen One : The prophecy !"],["a","Fremen Two : \"He will welcome you and your presents will be a blessing !\""],["a","Fremen Three : (falling to his knees) Mahdi !"],["a","His companions help him up again quickly."],["d","KYNES","(to Leto). Allow me to adjust your device."],["a","Tension. Leto is suspicious ; Hawatt whispers to him discreetly :"],["d","HAWATT","He has a Krys under his cape..."],["d","LETO","He would be offended by a refusal."],["a","He turns off his sword-belt and opens his arms. Hawatt worriedly clenches the top of his sword."],["a","Kynes comes closer to the Duke, adjusts the shoulder fasteners and explains how the garment works."],["p",146],["d","KYNES","(pointing to the internal part sticking to the skin). This porous part collects perspiration (showing the second cape). Here, the salt is recovered (showing the third) This one accumulates the water in pockets (adjusting leg fasteners). The urine and excrement are collected here and transformed into water (pointing to the filter) For the mouth (pointing to the tube) for the nose. You breathe in through the mouth and out through the nose. In this way, you only waste five drops of water a day and the rest is recuperated."],["a","Leto's garment is properly in order now. Hawatt has copied the adjusttments and feels very much at ease. Hawatt, Paul, Kynes and Leto go aboard the ornithopter, which Leto is piloting."],["a","The machine takes off and enters the desert."]]},{"n":60,"h":"EXTERIOR-INTERIOR. FLIGHT OVER THE DESERT. CABIN OF THE ORNITHOPTER.","b":[["a","The orni is flying over the desert. While Leto handles the machine, Kynes describes and points out the various aspects of the landscape."],["d","KYNES","During the day, the temperature of these rocks can reach three hundred degrees. If an animal lands on one of them, it catches fire. The sand-drums : each step resounds for miles and attracts carnivorous animals... The lakes of dust where the swamps suck in imprudent people... Hurricanes which move at over four hundred miles an hour."],["a","An enormous worm two hundred metres long twists and turns in the sands. It makes a vibrating sound, similar but more intense than the noise made by the Krys."],["d","KYNES","Shai-Hulud, the grandfather of the Desert."],["d","LETO","I didn't think they were so big !"],["d","KYNES","This one is small. We have seen them four hundred metres long."],["d","HAWATT","What do they do ?"],["d","KYNES","They defend spice-fields. Each worm has his own territory. Where there's spice, there's a worm."],["d","LETO","Why haven't they been eliminated ?"],["d","KYNES","That would be too expensive... They resist atomic bombs !"],["d","PAUL","It's not only that. There is a link between the worm and the spice. Killing the worms would mean the end of the spice !"],["p",148],["i","Ornithopter flying over a harvester and spotters",null,180,true],["p",149],["a","Fascinated and repelled, Kynes looks at Paul with expression of both faith and incredulity."],["a","A field of spice appears. It's a large field of a beautiful blue substance, a spongy mixture of shapelessness and geometry, of animal, vegetable and mineral. Each pile of substance makes a vibrating noise, and they all make for a hypnotic note. The resulting sound is like that made by the worms and the Krys."],["a","In the sky, opposite the orni, the harvester appears, a large plastic and metal engine like a beetle with hooks as legs. Another machine composed of two carrying claws and two colossal wings, is transporting the harvester. Four little \"watchmen\" are following these two machines ; these are composed of a simple turbine with two little wings driven by a pilot."],["a","The wing-carriers put the harvester down near the spice field and take off again. Sixteen picturesque spice-searchers, drinking spice brandy neat, roasted by the sun, toothless, spitting and swearing handle the harvester which moves into position and immediately begins to extract the spice amid a cloud of dust. The watchmen, humming away, take their places at four key points."],["d","KYNES","These sixteen men have twenty minutes to collect the spice before the worm arrives. The watchmen will warn them in time. The wing-carrier will arrive just in time to pick them up and fly away !"],["a","The orni, flying over the harvester, watches the work. Suddenly, like a flower growing brutally fast, a worm emerges from the earth. He hides in the sand and comes forward towards the harvester underground, shifting a hillock of sand."],["a","The workers, without getting excited, carry out with their work."],["d","LETO","And now ?"],["d","KYNES","The wing carrier will be alerted. It'll come to pick them up a few minutes before the worm reaches them."],["a","Leto plugs in the radio."],["p",150],["i","Sandworm near the harvester",null,60,true],["p",151],["d","VOICE OF THE HARVESTER","Harvester to watchmen. The wing is not replying. Whoever sees it, make contact. Over."],["d","VOICE OF WATCHMAN ONE","This is watchman one. Negative. Over."],["d","VOICE OF WATCHMAN TWO","This is watchman two. Negative. Over."],["d","VOICE OF WATCHMAN THREE","This is watchman three. Negative. Over."],["d","VOICE OF WATCHMAN FOUR","This is watchman four. Negative. Over."],["d","LETO","Where's the wing ?"],["d","KYNES","A single wing carrier is used for several harvesters. It must be in another field. It'll come all right !"],["a","The Duke flies over the worm which is now very close to the harvester. The men are feverishly extracting the spice. Whistling blue piles are being built up. The men's eyes are gleaming with greed."],["d","LETO","Kynes, order them to abandon the harvester ! There are five ships for sixteen men. Each watchman can take three men. We have room for two more."],["d","PAUL","We can save fourteen men. Two will die !"],["d","LETO","Lots can be drawn to find which ones !"],["d","KYNES","Calling the harvester. Order to abandon. Over."],["a","The men from the harvester protest, shout insults, make obscene faces, show their five fingers and continue to work."],["d","KYNES","They refuse ! The worm will reach them in five minutes ! They prefer to wait. There's a lot of spice !"],["d","LETO","To hell with the spice ! (on the radio) Evacuate ! Without discussion. This is an order ! Over."],["a","The spice searchers laugh, pointing to the sky. In the distance, the wing carrier is coming. A minute later, it explodes and falls into desert surrounded by a cloud of flames."],["d","HAWATT","Sabotage !"],["p",152],["d","LETO","(by radio) Call to all life-saving units, come down !"],["a","The searchers run towards the watchmen who are landing."],["d","PAUL","But there aren't sixteen of them, there are eighteen !"],["a","The Duke lands while the watchmen, having each taken three men aboard, are taking off."],["d","THE DUKE","We shall save all the others !"],["d","HAWATT","We'll never get off the ground ! The weight will be considerable and the sand is soft !"],["a","Four searchers arrive in front of the ornithopter. Two men have remained quietly in the harvester."],["a","The Duke tears the radio away and throws it out the window, together with his arms."],["a","Paul and Hawatt do the same. They take off their sword-belt shields, tear away the back seat and throw it all (together with everything that can be thrown) out the window. They pick up the four men."],["a","After a hair-raising effort, the orni manages to take off, with all its passengers crowded together."],["a","The worm had almost reach them."],["a","The harvester leans to the right. A whirl of sand can be seen, and a terrifying mouth, bristling with thousands of white phosphorescent teeth appears. The machine drops into it and disappears. Sand covers over everything again."],["d","KYNES","(praying). Blessed be the creator and his water ! Blessed his mouth which purifies ! Blessed his power which keeps the World for our people !"],["d","A SEARCHER","What's this old man going on about ?"],["d","ANOTHER","Our spice, lost !"],["d","LETO","(furious). The Harkonnens will pay for it !"],["p",153],["a","Where the harvester was, a crater can now be seen. Two silhouettes are walking away from it, finding their way in the sand, as nimble as animals."],["d","LETO","Who are they ?"],["d","A SEARCHER","Two strangers. It was their first contract."],["d","LETO","I'll send for a plane to pick them up."],["d","KYNES","It's not necessary. They are going to die."],["d","PAUL","No. They were able to escape when the worm attacked. They know how to live in the desert. They're Fremens."],["d","KYNES","Who said so? You can't tell from here."],["d","PAUL","I know they're Fremens. They came to study our crop techniques."],["a","Kynes is quiet. The searchers are passing round bottles of brandy and, happy to be alive, they sing :"],["d","SONG OF THE SPICE SEARCHERS","The desert watches over us like a wild beast. Watching for the water of our blood. But I defy the sand and the Gods, at the least Because in times of danger my courage comes to me like a flood !"],["d","KYNES","The Duke is more worried about these men than about the spice. He has risked his life for them. Such a leader could have devoted supporters. If the Fremens were not what they are, they would love to serve so remarkable a Duke !"]]},{"n":61,"h":"INTERIOR. HALL OF THE GOVERNMENT PALACE.","b":[["a","The hall is lit and decorated for a ball. A rostrum for the band has been built. The musicians are playing crystal glass instruments."],["a","The hall is filled with guests belonging to the rich industrial classes of Dune. They are vain, pedantic and ridiculous \"nouveaux riches\". They are dressed in evening clothes, jewels and wigs, extravagantly luxurious."],["a","They each have a dog which is fat, shining and wears clothes, a wig and jewels."],["a","50 generals are also present, wearing uniforms with their distinguishing coats of arms. Their faces are bestial, cruel and stupid. They all have artificial limbs pointed at the end : artificial arms and legs, parts of the skull, jaws and ears. The young people are performing a court dance."],["a","In spite of the ventilators, the guests dispose of old slaves who are fanning them. They have dressed them in a ridiculous manner, and treat them cruelly."],["a","Some of them are refreshing themselves in the latest fashion : four slaves of various ages and sizes, a child, an adolescent, a woman and an old woman, lined up according to their size, are forced to blow on to their master from his feet to his head."],["a","The body of a woman is entirely inlaid with jewels. Her laugh reveals an emerald set of false teeth. She proudly shows off the enormous diamond which hides her anus. Many of the businessmen have their artificial limbs made of gold inlaid with jewels."],["a","A pompous young industrialist enters the room pushing in front of him three small beggars. The guests block their noses and make gestures of disgust. Three other young men bring in large clay caldrons."],["a","The guests surround the group. The young industrialist gives a stick to the children. The caldrons are fastened to a gallery by ropes."],["p",155],["i","The four rooms of the party, top down view",null,null,true],["p",155],["d","THE YOUNG INDUSTRIALIST","One of them is full of water !"],["a","The child thinks about this and chooses a caldron which he breaks. In despair, he receives a rain of flour which makes him cough. The guests laugh."],["a","The second child, with anguish and envy, chooses one of the remaining caldrons, breaks it and receives a flow of mud. Sitting in the middle of the mud, the child is weeping. The guests, happy with the game, are laughing."],["a","A third child, sure of winning, breaks the last caldron. Large stones drop out of it, injuring him. The audience applauds."],["a","The children hand over a dirty ladle. The young industrialist parsimoniously distributes them a bowl of water and chases them out with his whip. The dance begins again."],["a","Servants are passing round sumptuous foods and, instead of brandy, glasses of water, which the industrialists drink avidly and which they give to their dogs."],["a","Before eating, each businessman takes out his individual poison-taster and analyses the food. The machines gives out a negative signal. Then they eat."],["p",157],["i","The party guests, dogs, musicians, food etc",null,61,false]]},{"n":62,"h":"INTERIOR - SECOND FLOOR CORRIDOR","b":[["a","From the second floor-corridor, the first floor can be seen to be split up into four distinct, autonomous parts. In each of the rooms a different party is being given."],["a","Leto, Hawatt and Paul watch how the young industrialist treats the children. Paul, in indignation, takes hold of the top of his sword."],["d","LETO","Be patient, Paul !"],["a","Paul sheathes his arm. They are walking in the corridor, glancing at the other parties."],["d","LETO","A great idea, Hawatt ! Industrialists, Fremens, smugglers, spice searchers ! All we have to do is to convert the four dances into one !"],["d","HAWATT","Impossible !"],["d","LETO","Tonight or never !"]]},{"n":63,"h":"INTERIOR. FREMEN BALLROOM.","b":[["a","The Fremen party : a four-man band is playing folk music. A lot of dancers are turning around like dervishes."],["a","The Fremen have brought along their cushions and carpets. A large carpet with square drawings on it is placed in the middle of the room. On each side, groups teams. Each team, after violent discussion, moves pieces and takes pawns. It's a complicated game of chess. The rings worn by the women in their hair, around their arms and neck are the stake of the bets. Kynes, ill at ease in his uniform of Imperium employee, is leading one of the groups. His friends are feeling the military uniform and laughing at him without animosity."],["a","Farok is leading the second group. A violent Fremen, Stilgar, is at the head of the third and Duncan Idaho, dressed as a Fremen, leads the fourth. Involved in the game, he doesn't say no to the many spice pipes which the women hand him. The whole scene is bathed in the blue smoke of spice which is coming out of a lot of pipes."],["a","Servants are passing round typically Fremen dishes bathing in a blue spice sauce. None of them drinks the glasses of water which are served to them, but they pour the contents into their distilling device pockets."],["p",160],["i","The Fremen ballroom, dancers, chess game, smokers",null,null,true]]},{"n":64,"h":"INTERIOR. GOVERNMENT PALACE HALL.","b":[["a","Adolescents, industrialists' daughters, who are beautiful but outrageously sophisticated, are leaning through the opened upper window of a door giving on to the Fremens' room. The girls come down from the piece of furniture on which they had pulled themselves up, and are now fanning themselves."],["d","FIRST GIRL","What a smell !"],["d","SECOND GIRL","They eat their own excrement !"],["d","THIRD GIRL","And they're drinking blood !"],["a","Making disgusted and ironic comments, they lean through another window, giving on to the spice searchers' party."]]},{"n":65,"h":"INTERIOR. SPICE SEARCHERS' ROOM","b":[["a","The atmosphere is one of a large working people's orgy, The women and men are stout, peasant, simple and sporting types."],["a","They are eating like pigs. Their feet, wearing heavy boots, stamp the ground to the rhythm of an instrument which looks like a violin, played a thin bearded old man. The old man is chewing spice and spits it out in a metal bowl."],["a","Like drunks, they pierce a barrel with hefty blows, and take handfuls of spice from it, which they chew. The men and women woo each other brutally. The women are wearing dresses held up at the shoulders ; the men greet the Duke's passage with drunken hurrahs, while the women show him their behinds. The old, completely drunk violinist, is bathing in the water from a jar which is then poured over his head."],["p",163],["i","The spice searchers' ballroom, dancing, drinking, musicians",null,63,true]]},{"n":66,"h":"INTERIOR. SECOND FLOOR GALLERY","b":[["a","Leto, Hawatt and Paul are watching the spice searchers' dance. They return their greeting and set off again as far as the smugglers' room."],["d","HAWATT","To get them to come, we had to give ten soldiers as hostage for each of the smugglers !"]]},{"n":67,"h":"INTERIOR. SMUGGLERS' ROOM.","b":[["a","The smugglers are half pirates and half astronauts. They are giving a number of small shows : torch-jugglers, women turning, hanging by the neck, bears disguised as clowns performing wire acrobatics, a donkey made up and wearing a hat and a placard with 'RABBAN THE BEAST' written on it."],["a","Beautiful, half-naked women are wearing necklaces fastened to a padlock and behave like pets. They are wearing gloves provided with claws and false tails."],["a","Their leader, ESMER TUEK, is a one-eyed giant covered with scars. One of his hands is replaced by a hook. He is surrounded by six slaves covered with rings, necklaces, ear pendants and bracelets in massive gold. He is measuring his strength with another pirate, twisting an iron bar. Tuek wins."],["a","A large hippopotamus is in the middle of the circle from which the men, one after the other, try to get him to leave, without success."],["a","Tuek pulls the animal out of the circle. The smugglers applaud him admiringly. The women lie down on top of him and cover him with caresses."],["a","Everyone is taking spice powder through little gold tubes. They are pouring water over the body of a naked woman, which the men then lick all over."],["p",166],["i","Esmer Tuek wresting a hippo, dancers and jugglers",null,62,true]]},{"n":68,"h":"EXTERIOR. GOVERNMENT PALACE ENTRANCE","b":[["a","Some brackets where the arms handed over by the guests have been put away, are installed in the hall. A group of soldiers are acting as porters, some of whom watch over the square."],["a","Using tables, four different halls have been created. In one of them, a rich businessman, accompanied by his family, his slaves, dogs and bodyguards, is putting on his arms. On the other side of the tables, the spice searchers are handing in their hooks. Seeing them, the businessman's wife reacts disgustedly. The searchers make fun of her. To shock her, one of them lifts the skirts of his girlfriend, takes down his trousers and mimes an exaggerated orgasm on the table. The bodyguards want to intervene but the Atreides soldiers step in, make the spice searchers enter their dance without delay, and calm is re-established. There are a number of beggars. Their thin hands are outstretched in an imploring gesture. A slave of the industrialists' group has put down in front of him some fingerbowls together with a small towel. He pours water into them, which he takes out in potfuls from three large barrels. The industrialist's family washes its hands, each in his own personal fingerbowl ; then each member wipes his hands with a towel, which they throw to the ground, together with the water. The beggars fight for the towels. The strongest go off wringing them and licking them while the others lick the floorboards. The businessman, offers the end of his snow to a beggar, who licks off the drop of water which has fallen on it."],["a","Leto, Hawatt and Paul are present at this scene, and are indignant."],["d","LETO","(to the slave) Who put you here ?"],["d","THE SLAVE","It's a favour from Linger Webt, the Water trader."],["d","LETO","Take these fingerbowls away immediately !"],["d","THE SLAVE","But... it's the custom !"],["a","Leto draws his sword and puts the point of it to the slave's throat."],["d","LETO","The old customs are dead ! I shall teach you new ones. During the dance, you will distribute water ! Start straight away !"],["a","The trembling slave loads up with a barrel and begins to distribute the water to the beggars who line up. They arrive in hundreds from all sides."],["p",168],["a","Leto and Paul overturn the table where the finger-bowls, which they smash, used to be."]]},{"n":69,"h":"INTERIOR. GOVERNMENT PALACE HALL.","b":[["a","The dance continues. On a long table, women are playing cards. Behind them, their husbands and some soldiers are watching."],["a","The table is composed of three superimposed transparent surfaces. The round cards are printed out both sides, so that the top and the bottom are visible. The players use the three levels, vertically and horizontally. They are betting for small bottles filled with water. They discuss while playing."],["d","BUSINESSMAN'S WIFE","(sarcastic) : A \"generous\" gesture from the Duke... giving our water to these...these..."],["a","Unable to find a scornful enough word, she replaces it with a motion of her hand."],["d","THE BUSINESSMAN","They've been thirsty since birth. It's no favour to take that away from them : they'll be alarmed !"],["d","A WOMAN","These animals can't be treated like human beings. Each should know his place !"],["d","A FAT MAN","What does Lord Lingar Webt think about it ?"],["d","LINGAR WEBT","As long as the Duke only wants to change the forms of our customs, there's nothing to worry about. But if he attacks our interests, we'll trim his sails. I can blow up my water reservoirs. Without water, Dune will perish."],["d","GRAIN TRADER","My silos are also mined. I control the food supply!"],["d","TRANSFORMATION DEALER","If my lorries are paralysed, the towns will die of hunger."],["d","GENERAL","If we bring the bodyguards together in an army, we can attack the Duke."],["d","LINGAR WEBT","For the moment, we shall put up with him confusing us with the rabble, but tomorrow we'll see..."],["a","Lingar Webt goes through the motion of tightening a screw."]]},{"n":70,"h":"EXTERIOR. GOVERNMENT PALACE","b":[["a","Leto, Hawatt and Paul, preceded by Gurney Halleck, covered with dust and a group of soldiers perspiring, heavily, draw near a military lorry. Halleck boards it, opens a case and scatters a pile of cut-off heads at the Duke's feet."],["d","HALLECK","Harkonnens ! There are a lot of ambushed men."],["d","LETO","They must be killed."],["a","Halleck nervously makes no reply. He tries to speak, but can't. It's an effort for him to open his mouth."],["a","He takes a letter, and hands it to the Duke."],["d","HALLECK","We found it on a body. It bears the authentic seal of Baron Harkonnen."],["a","Leto reads the card, murmuring to himself."],["d","LETO","Jessica !"],["a","Hawatt takes the letter, and reads it anxiously."],["d","HAWATT","I knew it ! Trust a Bene Guesserit witch !"],["d","HALLECK","When I read that Lady Jessica has accepted to assassinate the Duke, I ...."],["a","Anger and suffering stop him continuing."],["d","PAUL","It's not true."],["d","LETO","It's formal proof ! We shall keep watch on Jessica until we find her accomplices !"],["d","PAUL","My mother couldn't have tried to kill me !"],["d","HAWATT","The Bene Guesserit aren't human !"],["a","Paul growls, draws his sword and tries to wound Hawatt. Leto holds him back by the arm. Hawatt and Halleck look at Paul with pity and go off. When they are alone, Leto smiles sadly at Paul."],["d","LETO","If she had wanted to kill me, she would have done it a long time ago. It's a lie to throw me into confusion."],["p",171],["d","PAUL","Why did you make me keep quiet ?"],["d","LETO","They'll think I've fallen into the trap and the real traitor will act rashly; Paul, when I die ..."],["d","PAUL","You won't die !"],["d","LETO","If I die, tell Jessica I must have hurt her but that never ... Tell her that I ... (emotion stops him speaking)."],["d","PAUL","I understand, My Lord ...."]]},{"n":71,"h":"INTERIOR. GOVERNMENT PALACE.","b":[["a","Jessica is coming down the main stairway. Stopping half-way, she waits for someone who is also coming down. The natural beauty of Jessica is remarkable."],["a","She is wearing the jewels offered her by the Fremens ; on her shoulders, the modest Fremen cape takes on the class of a high fashion garment."],["d","A WOMAN","This is too much ! She dares to wear Fremen clothes."],["a","Gradually, silence settles in the room. Attention is drawn to Jessica, who is like a magnet. Anger, vanity and disapproval can be read on the faces. Nobody bows before her. Kynes crosses the room, walks up the stairs and bows in front of her, with a fervent expression on his face. Jessica offers him her hand to kiss and murmurs when she realizes that to do this, he has kept his lips tightly closed."],["d","JESSICA","A day will come on Dune when there will be so much water that men will no longer fear to lose a drop of water when kissing women."],["a","Kynes raises towards her his eyes filled with religious fervour."],["d","KYNES","\"She will share our dreams ...- Did you bring the Kwisatz Haderach ?"],["a","Kynes' garment, wrinkled, shiny and too short fits him so badly that the whole dancefloor bursts out laughing and makes fun of him. Kynes gives out a ferocious animal roar, so powerful that the wall trembles. The frightened industrialists become quiet and begin to dance once again, without daring to look at him any more. Leto comes down the stairway, followed by Paul, Hawatt, Duncan, Yueh and Halleck."],["d","JESSICA","According to the custom, the masters of the house propose the last toast and close the Dance."],["a","Jessica takes the Duke by the arm, but he moves aside."],["d","LETO","Remember, you're not my wife, but my mistress. It would go against the custom to propose the toast together. Your place is in the shadow."],["a","The Duke comes to the bottom of the stairway, still followed by Paul,"],["p",173],["a","Hawatt, Duncan, Yueh and Halleck. Tears of pain glisten in Jessica's eyes. She leans on Kynes' arm."],["d","JESSICA","(murmuring) We exist only to serve."],["a","Leto, Paul, Halleck, Hawatt and Yueh get up on to the musicians' rostrum. Paul stops the band. Silence. The Duke comes forward, a glass full of water in his hand. Everyone draws nearer to hear him."],["a","Leto gently sings a ballad, appearing to be in a trance. Halleck accompanies him on his balisette."],["d","LETO","The final toast : (singing) : Ah, how long seems the days... But the years keep running by When we shall be buried in sand As black will be this water Today pure as crystal glass !"],["a","Nervous laughs and murmurs :"],["d","LINGAR WEBT","He's drunk !"],["a","Leto slowly turns the glass over. The guests follow his example with irony, fear, greed or scorn. Kynes also turns over his glass but he collects the water in a container which he stops up and puts away in one of his pockets. Leto violently smashes his glass. It's a signal. The hall fills up with armed Atreides. Protests, complaints and cries can be heard. In a second, the dance changes in aspect : rebellious industrialists are hit, all the guests are forced to kneel down, and hysterical women are dragged along by the hair. The face of an adolescent shouting insults is slashed, slaves are put aside and the generals, who taken by surprise, haven't had time to defend themselves, are brought together in front of the Duke. An Atreides steps into place behind each general, with his sword raised. Leto draws his sword, turns it in the air, as if beheading someone, and immediately the Atreides cut off the heads of the fifty generals. On another signal from the Duke, his soldiers move a stone in one of the walls separating the hall from the Fremen room ; the wall goes down into the floor, followed by the wall separating the Fremen from the spice searchers, and the walls separating the spice searchers from the smugglers and the smugglers from the industrialists."],["p",174],["a","Without the walls, the four rooms are now reduced to one, to everyone's surprise."],["a","On another signal from the Duke, the hall doors are opened and a crowd of beggars, serious, respectful and impressed, burst in."],["d","LETO","This is what Dune needs, a united people ! There is room for everyone on this earth ! I offer you a planet without mercenaries at the service of greedy commercial traders ! Now we control the water reservoirs, the food reserves and energy sources ! (to the industrialists) Never come back this planet !"],["a","Under the menace of the swords, the industrialists do not dare to protest. They leave the hall silently with their wrists tied, led by the Atreides soldiers. The beggars fill the room left vacant by the industrialists."],["d","LETO","Let us unite ! Respect my government and Dune will be respected ! (to the smugglers) Instead of losing fifty per cent of your profits in fighting against the State, I offer you immunity in exchange for a reasonable tax! (to the spice searchers). If you stay on this planet, be no longer employees but associates ! (to the free Fremens) As for you, a free people, I offer you a share in the government, with the right to vote, in exchange for men to defend Dune against the Imperium. Either we now unite, or the Harkonnen will come back to exploit, torture and massacre !"],["a","A deathly silence settles in the hall. Instinctively, the groups form again quietly. Kynes, leaving Jessica, goes back to his Fremens."],["a","Jessica, with nobody to support her, waits for the replies with anguish written on her face. The servant Mapes approaches her devotedly, under the pretence of fanning her. Jessica takes her hand and presses it."],["a","Farok, followed by Kynes, steps forward a few paces and stops."],["d","FAROK","You are a great man, but more than a great man is needed to reunite the Fremens ! We know our fate, and the time has not yet come. We do not serve foreign governments, however honest they may be. However, we respect the Duke, and, for this reason, between him and ourselves there will be peace, to the extent that our"],["p",175],["a","lands are not invaded. In the desert, all animals fight with their own claws."],["d","KYNES","As representative of His Majesty the Emperor, I protest against the Duke, but as a Fremen I congratulate him. Because of this internal conflict, all I can is do is keep quiet and wait. We'll see each other again !"],["a","The free Fremens and Kynes leave the room. Idaho remains alone, and comes up to the Duke. Esmer Tuek approaches."],["d","ESMER TUEK","Our fathers and grandfathers were smugglers. We have no planets to defend, laws to accept or leaders to obey. It will be always thus ! The Duke is our friend. We shall pay his tax but his war will not be ours. If he wins, we shall be happy. If he fails, we shall place our ships at his disposal so that he can make good his escape."],["a","The smugglers leave the hall."],["a","The half-drunk musician, one of the spice searchers, comes a few steps forward, stumbling, and urged on by his companions."],["a","The OLD MAN : Your enormous Lordship... Don't ask us to fight. Give us something to drink and some money. That's all. Don't ask us either to stay in this hell, eating these disgusting rats. The Galaxy is rich in paradises filled with passionate women. We work like animals to earn money which will enable us to leave as rich men. Don't count on a degenerate lot like us ... Your health."],["a","The spice searchers have a last drink and then leave, ashamed of themselves."],["a","The beggars keep coming in. The preoccupied Duke sits on his heels, hiding his head in his hands."],["a","Jessica, her eyes filled with tears, runs towards him, gets up on the rostrum, crouches beside him and embraces him."],["a","The hall is full of beggars watching the Duke with veneration in their eyes."],["a","An old man intones a beautiful lullaby. Gradually, the thousands of beggars murmur the song. A path opens up in their midst. An old man carrying a pot filled with earth emerges. Another brings a glass of water. They put the pot down in front of the Duke and sprinkle a few"],["p",176],["a","drops in it. In a few seconds, a spiny fungus is growing, producing a flower."],["d","THE OLD BEGGAR","The earth of the desert, my Lord. It needs just a few drops to bear fruit. My Lord, you have given us as more than a little water. You have given us back our dignity... we shall die for you."],["a","Leto looks at them and begins to laugh, more and more."],["d","LETO","Old men... weak men... sick men... madmen... That's all I have ! (laughing like a madman) An army in rags ! A people of beggars ! (he tears at his clothes and tears off pieces of Jessica's, leaving her half naked). From now on, the Atreides will become beggars ! Music ! Let the party begin !"],["a","He throws Jessica into the arms of a beggar and takes an old woman in his arms. He begins to turn. The beggars are laughing. The beggar makes Jessica dance. The others fight for her. The music is playing at a dizzy rate. They all want to dance with the Duke or with Jessica. The dance spreads everywhere."],["a","Ghastly, beggar-women hang on the neck and arms of the Atreides soldiers and make them dance."]]},{"n":72,"h":"EXTERIOR. THE COSMOS","b":[["a","Thousands of space-ships with the Harkonnen coat of arms are crossing sidereal space."]]},{"n":73,"h":"EXTERIOR. GOVERNMENT PALACE","b":[["a","Atreides soldiers take away the gates surrounding the government palace and give iron bars to the beggars. On the orders of the Atreides, thousands of beggars separated into small groups clumsily perform military exercises."],["a","Children, old men, the sick, mothers with their babies and emaciated men are making primitive arms, fastening stones and cactus tips to the end of ropes, broken bottles to pieces of cloth, and sharpening table knives and forks, sticking them into desert reeds."],["a","Halleck is training a group of beggars armed with donkeys' jaws, sticks, spades and iron bars."],["a","Trembling and moaning, the beggars group together and attack Halleck, who raises his sword and yells out a war-cry. The beggars, paralysed, fall to their knees. Halleck furiously pushes them to the ground and treads on them. He sits down, depressed. A sick man comes up to him."],["d","THE SICK MAN","Don't scorn us, my lord. We know the Harkonnen will exterminate us and we want to sell our skin at a high price. But we've been slaves for centuries and we no longer know how to fight. We lack the impulse."],["d","HALLECK","(brightening up). That's it. They need someone behind them."],["a","Halleck calls over the Atreides soldiers, arranges them in an attacking position, forms a group of beggars and stands in the middle of them. Surrounded by the beggars, he shouts :"],["d","HALLECK","Charge !"],["a","The beggars, urged on by the dynamic warrior, attack the soldiers, assail them and rout them. Halleck jumps up and down with shouts of joy. The beggars help up and shake the soldiers, who are covered with bruises."]]},{"n":74,"h":"EXTERIOR. IN SPACE.","b":[["a","The group of Harkonnen space-ships draws closer to Dune, separating into two files going off in opposite directions and forming a ring around the planet."],["p",180],["i","Harkonnen ships circling around Dune",null,null,true]]},{"n":75,"h":"EXTERIOR. DESERT NEAR ARRAKEEN.","b":[["a","On the dunes from which, in the distance, the government palace can be seen, beggars and Atreides soldiers are preparing for a military exercise."],["a","From a hill, the Chief of staff is watching the manoeuvre, including Leto, Paul, Hawatt, Halleck, Idaho and other generals. Hawatt describes the manoeuvre to the Duke :"],["d","HAWATT","We have divided them into groups (he points) the old men and the sick (towards the second group) the children, the freaks, the blind and madmen ; (group three) the women and their sons ; (the group of half-starved men) the men ; (pointing to the soldiers armed with bows and arrows) the warriors."],["a","Halleck sounds off a bugle as big as an orange. An electronic roar comes out of it, which can be heard all over the field."],["a","The thousands of beggars and the few soldiers form a circle, which becomes square, triangular or adopts various shapes similar to amoeba."],["a","The first line contains the old men and the sick, then come the children, the freaks, the blind and the madmen ; then, there are the mothers using their children as shields. The following line is made up of the women and the half-starved men. Finally, in the centre, the Atreides soldiers."],["a","The bugle sounds off again. The group separates into two, keeping the same order. The bugle sounds several times. Each time, the groups, still in the same order, split into two until there are a number of small groups where the beggars surround only one soldier. From inside his cell, he fires arrows. Halleck's bugle gives out a different sound. The groups begin to integrate into each other, still in the same order, until they again form the initial circle."],["d","HAWATT","Each Atreides will be protected by a wall of bodies. Many Harkonnens will die before they can get to him !"],["p",182],["i","Halleck showing the army tactics",null,null,true]]},{"n":76,"h":"INTERIOR. GOVERNMENT PALACE HALL.","b":[["a","There is a large machine in the middle of the hall. Soldiers are finishing the connection of some cables, under Yueh's orders. Leto and his Chief of staff inspect the installation. Yueh pushes some buttons. The machine lights up."],["d","YUEH","Due to this protective screen, the government palace is invulnerable !"],["a","He raises a lever."]]},{"n":77,"h":"EXTERIOR. DESERT. VIEW OF THE GOVERNMENT PALACE","b":[["a","In the middle of the desert, the government palace can be seen in the distance. Slowly, a semi-transparent bell of slightly yellow light covers the palace like a dome."],["a","Ships arrive from all points in space. They land in a semi-circle in front of the government palace, little more than half a mile away. These are the Harkonnen ships."]]},{"n":78,"h":"EXTERIOR. GOVERNMENT PALACE TOWER.","b":[["a","Leto, Paul and the Chief of Staff are watching the enemy. From the tower's terrace, the armada of space-ships can be seen in the distance, together with battalions in attacking formation."],["d","LETO","The Guild has lent its ships and the Emperor is paying for half the army !"],["d","DUNCAN","Nobody can defeat the Sardaukars !"],["d","LETO","Either we surrender or die fighting !"],["a","They all react smartly, having been offended by this."],["d","HALLECK","Would we have less courage than beggars ?"],["d","LETO","(moved) They'll kill us but they won't defeat us ! To legally govern Dune, they have to produce my head, and Paul's, in front of the senate (showing Paul) We shall shut ourselves in the Palace ! The protective screen will last centuries ! They'll never get hold of our bodies !"]]},{"n":79,"h":"EXTERIOR. BATTLE FIELD IN FRONT OF THE GOVERNMENT PALACE","b":[["a","The Harkonnen armies and the Sardaukars move forward to meet the Atreides and the beggars. The Harkonnens, with their military band, their display of arms, their coloured uniforms, camels, elephants and war machines, look like a circus parade."],["a","The Sardaukars, because of their incredible discipline, give an impression of terrifying power with a minimum of effects. Their uniform, iron masks, rubber gloves provided with sharp tips, swords with triple blades, etc... all give a feeling of murderous efficiency."],["a","The Atreides and beggars' army forms three sections. In the centre of each group, aboard rolling triangular platforms drawn by three men, are the three section leaders : Hawatt, Idaho and Halleck. Nobody moves. Silent like wax figures, they are waiting for the enemy army to draw near. The armies are about to meet. An order rings out, and the Atreides-Beggars' army dissolves into a host of small groups which move to attack the enemy ranks."],["p",187],["i","The Harkonnen army and vehicles",null,null,true]]},{"n":80,"h":"EXTERIOR. THE DUNE SKY","b":[["a","The sky fills with vultures. The sound of battle can be heard : a deafening uproar, the clash of arms, explosions, wails, military bands, mingling their rival hymns."],["a","A black smoke darkens the sky."]]},{"n":81,"h":"INTERIOR. GOVERNMENT PALACE CORRIDORS.","b":[["a","Out of breath, Yueh runs down a corridor, arrives in front of a door and knocks despairingly."],["a","Leto, sword in hand, opens up. Yueh can hardly, speak."],["d","YUEH","Jessica ...! Paul ...! The Harkonnens ... ! in the underground passages !"],["a","Leto follows him into the corridor. As they turn into another corridor with walls formed of large blocks of stone, a woman's silhouette comes staggering towards them."],["d","LETO","Jessica !"],["a","They run towards her. It's old Mapes who collapses, a dagger planted between her shoulders. She tries to speak."],["d","MAPES","My Lord, ... don't..."],["a","She tries to get enough strength together to talk. Yueh has taken her in his arms. Mapes moves, then dies."],["d","YUEH","This way !"],["a","They set off running again."]]},{"n":82,"h":"INTERIOR. THE GOVERNMENT PALACE UNDERGROUND PASSAGES","b":[["a","Jessica and Paul are lying in a pool of blood. They appear to be dead. Through the open door, Leto can be seen running in, followed by Yueh."],["a","With a great cry, Leto falls to his knees in the blood and embraces Jessica and Paul. Yueh, benefiting from his distraction, sticks a little syringe in his neck. The effect is immediate. Leto feels a paralysis begin to come over him. Jessica and Paul drop from his arms. He falls on his back, breathing with difficulty through his mouth."],["a","His vision distorted by the drug shows him the image of Yueh coming closer and taking out one of his teeth. He then sees him taking a false tooth out of a small box. Yueh puts the tooth in front of his eyes. It seems enormous, while Yueh's head seems tiny and far away."],["d","YUEH","An exact replica ! When you bring your jaws together, it will break and release a deadly gas. When Baron Harkonnen comes near you, don't forget the tooth, Leto Atreides, the tooth !..."],["a","Yueh lifts the Duke up and sits him down in a corner of the room. That way he can follow all his movements. As if in a dream, Leto sees Yueh bind and gag Jessica and Paul. He points to the pool of blood."],["d","YUEH","Artificial blood ! In exchange for the Baron's death, I shall save your wife and son."],["a","Yueh injects Jessica and Paul. They begin to come half-awake, struggle and moan... Leto sees Yueh take off his ducal ring and slip it into one of Paul's pockets. He sees him pushing on a part of the wall, which gives way, making a path for two brutal and drunk spice searchers (CZIGO and KINET). He sees the giant Kinet load Jessica and Paul on to his shoulders. Yueh gives Czigo a large bag, a purse full of gold and two full bottles of brandy. Kinet weighs the money in his hand. The two searchers laugh like animals. They drink and leave with his wife and son. The wall closes. Yueh gives him a second injection. Before he finally loses consciousness, Leto sees Yueh putting in his false tooth. Yueh's face is distorted. He tells the Duke."],["d","YUEH","The tooth ... Don't forget... The tooth..."]]},{"n":83,"h":"EXTERIOR. BATTLEFIELD.","b":[["a","The battlefield, silent and motionless, is seen to contain thousands of dead, and wrecked war machines. Beggars run through with spears, blood-stained women, babies bristling with arrows, disembowelled camels, elephants eating each other, carved-up Atreides, bloodless Harkonnens and a few dead Sardaukars can all be seen. Sometimes a groan is heard, or again, birds of prey fighting for a piece of flesh."],["a","In the middle of the field, three individuals are standing : Idaho, Hawatt and Halleck, covered with wounds, blood and dust. They are turning, shoulder to shoulder, their swords drawn. They have the exalted eyes of madmen. Silently, passing among the dead, a battalion of Sardaukars is coming towards the three heroes, grouped together in an ever-shrinking circle. Halleck plays a gentle tune with his left hand, on the balisette hanging from his shoulders. The Sardaukars quicken then run towards the three Atreides. The circle closes."],["a","Hawatt struggles, imprisoned by the innumerable ropes which hold him in the air, his legs and arms apart."],["a","Halleck is immobilized under a net, his limbs and neck held under by large forks."],["a","Idaho, invincible and mortally wounded, keeps on fighting and killing enemies. He falls to his knees, having lost almost all his blood. The soldiers take him by the legs and arms, four to each limb, sixteen Sardaukars in all. A group which has difficulty dominating Idaho's strength. Soon they press his chest against an old cannon. Brandishing a lighted torch, laughing like a madman, Rabban the Beast sets light to a fuse and makes the cannon explode, tearing Idaho into pieces. Hawatt is lying on the ground, fettered by ropes. Beside him, Halleck has his feet, neck and hands in irons."],["d","RABBAN THE BEAST","(pointing to Hawatt) \"Take him to the Baron. He wants to interrogate him\"."],["a","The Sardaukars take Hawatt away. Rabban comes closer to Halleck, seizes the balisette near him, and stamps on it until it breaks. Dried flowers come out of the instrument, Rabban is curious, and picks up some of them, smelling them."],["p",192],["d","HALLECK","(singing gently) \"But you never forget the flowers of Caladan\"."],["d","RABBAN THE BEAST","(stamping on the flowers until they are no more than a pile of dust) \"You'll forget the flowers, you'll forget Caladan ! You'll forget your rotten tart of a mother !\""]]},{"n":84,"h":"INTERIOR. HALL OF THE GOVERNMENT PALACE.","b":[["a","Leto, naked, his sex hidden by a little bandage, is laid out on a table, his arms and legs fastened and stretched out. He is sleeping."],["a","Yueh lowers the lever on the protective shield machine. The machine stops vibrating. The lights go out."],["a","EXTERIOR. GOVERNMENT PALACE"],["a","A triumphant parade is approaching the government palace. The Sardaukars move forward in military order. A few Harkonnen survivors are following their military band. A \"chariot of triumph\" is moving in the middle of them. This lorry is decorated like a golden marriage cake. Pillars in the shape of young adolescents hold up a globe, an exact replica of Dune. A throne is constructed on top of it ; here Baron Vladimir Harkonnen is sitting. In front of him, lying on a couch made out of two gold crocodiles, is Feyd Rautha. Beside him are Uman Kudu and the Mentat Peter."],["a","Sixteen lorries disguised as winged horses are pulling the chariot. They have enormous swan-like wings, and are decorated as if for a gala evening with feathers, jewels and luxurious saddles, and are pined together by silk bridles. In front of the horses, sitting on a large shell carried on their shoulders by Harkonnens, is Rabban the Beast, making obscene masturbatory gestures he ; like a buddha, is leading the parade."],["a","The rest of the Harkonnens, in spite of their beards and scars, are dressed up as women, nymphs and fairies and, running beside the chariot, they throw confetti towards it. At the palace doors, the baron nimbly gets down from the chariot, thanks to his anti-gravitation devices and, followed by Kudu, Peter and Rautha, he walks towards the palace entrance. He gives an order, and the Sardaukars bring the table, where Duke Leto is fastened, out into the daylight."],["a","The army breaks out in cheers. The baron acknowledges the applause and enjoys it, jumping each time over fifteen feet in the air, like a sphere."],["a","Suddenly, a tomb-like hush comes over the army, caused by Yueh, who is slowly coming out of the palace."],["a","His head lowered, Yueh goes and stands near the prisoner. Shouts are heard"],["d","A SOLDIERS VOICE","Yueh ! Traitor !"],["a","All the soldiers join this voice and begin to shout."],["d","ALL THE SOLDIERS","Yueh ! Yueh ! Traitor !"],["a","Some of them start throwing clods of earth at him. The Sardaukars rapidly take the Duke back inside the palace, followed by the baron, Peter, Uman Kudu and Rautha. Yueh remains a moment alone, groaning excuses to the army, bathed in the light of the sand. The Sardaukars take him away. The"],["p",195],["i","The Harkonnen parade chariot, with the Baron sat on top",null,156,false]]},{"n":85,"h":"","b":[["a","doors close with a bang."],["a","Rabban the Beast starts shouting orders. He takes off one of his boots and begins to hit his Harkonnens with it to calm them down."]]},{"n":86,"h":"EXTERIOR. DESERT NEAR THE TOWN OF ARRAKEEN.","b":[["a","Halleck, dying of thirst, is lying in the sand. From his wrists and ankles ropes are fastened to four sticks. Each sticks belongs to a large sunshade under which two Harkonnens are looking on."],["a","Halleck is delirious."],["d","HALLECK","(shouting with hate) Jessicaaaa!"]]},{"n":87,"h":"INTERIOR. ROOM IN THE GOVERNMENT PALACE.","b":[["a","This is a large room which is almost empty. Its walls, floor and roof are made out of large blocks of grey stone. There is a small door and, on the roof, a cut-glass dome. On one side of the rectangular room, on a carpeted rostrum leaning against the wall, Baron Harkonnen is sitting on a throne shaped like a golden calf inlaid with precious blue stones. On the opposite wall, Duke Leto is fastened by straps on to a metal Saint Andrew's cross. The straps surround his wrists, ankles and waist. He is so drugged that he can hardly raise his head. Peter and Yueh are also present."],["a","In front of him, the baron has a foot-table loaded with food : cheese, wine, a cooked crab with mayonnaise. While hollowing out a leg and eating it, the baron angrily talks to Yueh."],["d","THE BARON","Where's Paul ? I must have his head !"],["d","PETER","Where's Jessica ?"],["d","YUEH","I promised to hand the Duke over to you ; I've carried out that promise. Jessica and Paul left under heavy escort before the battle. Only the Duke knows where !"],["a","The baron rings a small gold bell. The door opens, giving way to a stretcher where Wanda is lying, covered with a white sheet. Her face, the only visible part of her body, is white and her eyes are closed."],["d","YUEH","Wanda !"],["a","Yueh wants to rush towards her. Peter sticks a dagger in his back. Yueh falls forward, hangs on to the towel and reveals Wanda's body, completely vitrified. Uman Kudu laughs like an animal, and, seizing the glass body, smashes it beside the dying man. On the point of losing consciousness, Yueh delicately picks up a few fragments of glass, kisses them, points at Vladimir Harkonnen, breaks out in a mocking laugh, and dies."],["d","THE BARON","You can't trust a traitor ! Peter, interrogate our friend ..."],["p",199],["a","Peter moves close to the Duke and slaps his face twice."],["d","PETER","Where are Jessica and Paul ?"],["d","LETO","Jessica ... Paul... alive ... all is not lost !"],["d","THE BARON","Show us what you can do, Peter ! Do what you want with the body, but spare the head... I promised the Emperor that the Duke would have a death worthy of his title. The senate must see a clean, well combed, healthy head."],["a","Peter is excited, with a sadistic gleam in his eyes, and injects the drug into his leg, groaning with pleasure. He takes a trunk from a corner of the room, empties it and places it in front of the Duke. He tears a jagged sword away from Uman Kudu as if he were drunk, and begins to chisel off one of Leto's shoulders. The arm eventually drops off, and Peter throws it into the trunk."],["a","The baron applauds, satisfied, and starts eating again, ecstatically joyful at the sight of the torture."],["d","PETER","Where are they ?"],["a","No reply from the Duke. Peter saws off his other arm and throws it in the trunk."],["d","PETER","Where ?"],["a","The Duke faints. The baron throws a bottle of wine over to Peter who just manages to catch it, and empties the contents over the Duke's face. The duke regains consciousness. Peter cuts off one of his legs, which joins the other limbs in the trunk."],["d","PETER","Where ?"],["a","As the Duke remains silent, Peter smiles. He throws the sword to Uman Kudu, who cleans it and puts it away, and then tears his dagger out of Yueh's body. Kudu, guessing what Peter intends to do, comes closer to the Duke, with an unhealthy expression on his face. Vladimir Harkonnen get up, comes down from the throne, still eating the crab's head. Slowly, Peter takes away the bandage over the Duke's sex ; he stares at the sex, first with surprise, then incredulity, and finally bursts"],["p",200],["a","out laughing, imitated in this by Uman Kudu."],["d","PETER","(to Vladimir) He's got no..."],["a","He can't go on. The Baron quickly gets down from the throne and, eaten up with curiosity, comes closer, leaping nimbly. The Duke presses his jaws together, and the deadly gas begins to escape."],["a","Peter brings his hands to his throat and falls down. He stifles and takes on a purple colour, as does Uman Kudu."],["a","The Baron stops up his nose, and takes a big leap which sends him to the ceiling ; his head breaks through the glass dome."],["p",201],["i","The Baron flying upwards, escaping the gas from the tooth",null,null,true]]},{"n":88,"h":"INTERIOR. A ROOM IN THE GOVERNMENT PALACE.","b":[["a","The visible upper part of the stands out in the middle of a small room where Harkonnen soldiers put their arms, relax and play dice."],["a","Breaking the glass with a loud noise, Vladimir Harkonnen's head emerges from the dome, with a mad expression on his face."],["d","VLADIMIR","A mask ! Ventilators !"],["a","The soldiers, petrified in surprise, make no reaction. The baron is vomiting with fear and rage."],["d","THE BARON","Get on with it, you asses !"],["a","The soldiers come out of their astonishment, panic and run in all directions. Vladimir's head is still yelling. They get together some masks and some ventilators, and run out of the room."],["d","VLADIMIR","A maaask !"],["a","A mask is applied to his face. His head disappears through the hole in the skylight."],["p",203],["i","The Baron breaking through the dome by some guards",null,null,true]]},{"n":89,"h":"INTERIOR. A ROOM IN THE GOVERNMENT PALACE.","b":[["a","Baron Vladimir Harkonnen, armed with his gas mask, drops slowly from the dome."],["a","He kneels down beside the purplish bodies of Peter and Uman Kudu and tries to bring them back to life, moaning hysterically. The doors open violently. The soldiers come in with their gas ventilators and purify the air. Feyd, also provided with a mask, follows them. The Baron hangs on to him, weeping like a child. Suddenly, overcome with an uncontrollable fury, he rushes towards the Duke (only his abdomen remains) and slashes at his face. Then he cuts off the head which he throws in the trunk. As there is no further danger, the soldiers take off their masks, as does Feyd. The Baron half-keeps his on, looking ridiculous."],["d","THE BARON","Throw him into the desert ! Let the worms get at him ! So that there's nothing left ! I don't want the Senate to make a martyr out of him ! I want the army to go out and look for the woman and the child ! And not spare anyone, Atreides or Fremen ! Let them all die ! Total extermination !"]]},{"n":90,"h":"EXTERIOR. ROAD BETWEEN ROCKY MOUNTAINS.","b":[["a","A six-legged vehicle is moving towards the desert."],["p",206],["i","A six legged vehicle in the desert",null,null,true]]},{"n":91,"h":"INTERIOR. SIX-LEGGED VEHICLE. MOVING.","b":[["a","The inside of the vehicle : in front are Czigo and Kinet, and behind, Jessica and Paul."],["a","Jessica is sitting in an uncomfortable position ; bound and gagged, and is trying in vain to break her bonds. Paul tries to get rid of his gag by hanging it on a nail sticking out on the door."],["a","Czigo is holding two bottles. He pours the contents of one of them into the mouth of Kinet, who's driving. They are drunk. In the driving mirror, Kinet can see Jessica's legs uncovered in her uncomfortable position. He nudges Czigo. Czigo looks at Jessica and also notices a breast uncovered."],["a","Czigo spits out wine-coloured saliva on to the breast and both he and Kinet roar with laughter."],["a","Kinet stops the vehicle."],["a","Czigo and Kinet put the front seat of the vehicle away into the floor."],["a","They cut the ropes binding Jessica's legs ; Kinet feels her legs while Czigo pinches her breasts. Kinet and Czigo begin to unfasten their trousers and drop them ; the wine has made them clumsy."],["a","Paul manages to get rid of his gag. He immediately tries to use the Voice. The result is not very successful."],["d","PAUL","(showing Jessica) Take off her gag."],["a","Kinet and Czigo stop, and are surprised. They look at Paul. The sound of his voice has not impressed them, but distracted them a second."],["d","CZIGO","Eh ?"],["d","KINET","What ?"],["d","PAUL","(Using the Voice) Take off her gag."],["a","This time Paul has found the right tone. Like robots, the two drunk men take off the gag from Jessica's mouth."],["a","She immediately assumes an erotic and very seductive pose, offering her body like a prostitute."],["p",208],["d","JESSICA","(in the VOICE) Why are they fighting over me ?"],["a","Kinet throws his hands around Czigo's neck. Czigo dodges but Kinet's dagger traces a bleeding furrow in his face. Czigo replies, stabbing his dagger in Kinet's heart. Kinet falls to the ground, dead. Czigo, transformed into an animal, passes his hand over his face, trying in vain to stop the bleeding ; he attacks Paul and tries to strangle him."],["d","JESSICA","(in the VOICE) Stop."],["a","Czigo stops, yet fights against the order. Jessica opens her legs, making erotic gestures."],["d","JESSICA","(in the VOICE) You mustn't kill him. Let him go, I'll do what you want."],["a","Czigo hesitates, shrugging his shoulders. He cuts Paul loose and opens the car door, pushing Paul outside."],["a","Paul pretends to lose balance. He leans on the door and makes a turning movement while throwing his legs in the air like scissors so as to hit Czigo's liver and neck. A stream of blood springs from Czigo's mouth and he collapses, dead. Paul falls in the sand, turns over and takes up a defensive position. Seeing Czigo dead, he returns to the car and frees Jessica. A vibration can be heard, sign of the presence of a sand worm."],["a","They take the packet which Yueh had given the two spice searchers, and get out of the car."]]},{"n":92,"h":"EXTERIOR. DESERT NEAR SOME ROCKS.","b":[["a","Jessica and Paul, carrying the packet, run as far as the rocks. Behind them, a mountain of sand can be seen moving. Jessica and Paul reach the rocks. An enormous hole opens under the vehicle, and sucks it in. There is nothing left. The mountain of sand moves away."],["a","Jessica and Paul open the packet. There is a large plastic bag, some water-bottles and a tape-recorder. They turn on the tape-recorder."],["a","- Voice of Yueh \"when you hear my voice, the Duke and I will already be dead. Now Paul Atreides is the new Duke and lord of Dune. If my plan fails and Vladimir Harkonnen is still alive, I hope they will survive to avenge the Duke's death. That way, my suffering will not have been in vain\"."],["a","Paul takes the ducal ring out of his pocket and puts it on his finger."],["d","PAUL","\"My father is dead\"."],["d","JESSICA","\"Yes...\""],["d","PAUL","He never denied the trust he had in you. He loved you more than himself and his only regret was not to have made you Duchess."],["a","Jessica begins to sob. She tries to stop but can't."],["d","JESSICA","\"It's silly to waste water...\""],["a","Jessica tries violently to stop from weeping."],["d","PAUL","My father hid some atomic bombs. I know where they are."],["d","JESSICA","What can you do alone ?"],["d","PAUL","I'll find the power of the desert."],["d","JESSICA","The Fremens."],["d","PAUL","We'll sleep by day and travel by night."],["a","They open the plastic bag, bury the metal stakes, make fast the ropes, open a valve and blow up a transparent plastic tent. At the end of a wide tube is a contracting entrance. Paul and Jessica, carrying the water-bottles with them, crawl along the tube as far as the main bedroom. They sit down in a meditation position, their eyes closed."]]},{"n":93,"h":"EXTERIOR. DESERT. NEAR THE GOVERNMENT PALACE.","b":[["a","Halleck is in chains, dying of hunger. His lips are swollen and torn, his skin red and covered with blisters. Beneath the sunshades, the eight Harkonnen soldiers are fanning themselves in despair."],["a","A soldier tries to drink a trickle of water from his water-bottle, but in vain. The soldier curses, comes to a decision, draws his sword and goes towards Halleck to kill him."],["a","An arrow runs through his throat."],["a","Daggers and arrows exterminate the seven other soldiers. A group of smugglers emerges, led Esmer Tuek, who puts a water-bottle to Halleck's mouth."],["a","Halleck begins to tremble convulsively."],["a","After he is untied, a woman covers his whole body with grease and puts a silk coat on his back."],["a","Halleck has become mad."],["a","Tuek presents him with a gleaming new balisette, and plays on the strings."],["a","Halleck immediately reacts. He takes the balisette, drops down sitting on the sand, plays ... stammers a few words... becomes silent.... and then with bare hands, without worrying about pricking himself, he takes some cactus leaves and puts them into the balisette."]]},{"n":94,"h":"EXTERIOR. DESERT NEAR SOME ROCKS.","b":[["a","It's night. On the horizon the two enormous Dune moons can be seen emerging, one green and the other orange. Everything bathes in a greenorange light, seeming to protect two shadows."],["a","Paul and Jessica roll up their plastic tent. The engine of an ornithopter can be heard."],["d","PAUL","The Harkonnen."],["a","Paul and Jessica hide among the rocks. An ornithopter appears, bearing the Harkonnen coat of arms. They throw out a box which breaks open as it falls on the rocks, just where the desert begins. The limbs of Leto Atreides scatter over the sand."],["a","The ornithopter moves away."],["a","Paul and Jessica run up to the remains."],["a","They both hold on to each other and, turning round, look with horror at the remains surrounding them. They fall to their knees."],["a","Jessica picks up the Duke's head, respectfully, religiously, takes the sand off it and puts it on the ground, then takes the abdomen and arranges it under the head. Jessica and Paul both arrange the legs, then the arms ; the body has been restored. Jessica, kneeling in front of Leto's feet, tells Paul imploringly."],["d","JESSICA","Let me change death into life."],["a","Paul walks away and sits on the top of a small hill, turning his back to her."],["a","Jessica undresses and lies on the Duke's body."],["a","Paul begins to feel a change in his sense of perception : a host of images pass through his mind. Fugitive pieces of the future. Flags bearing the Atreides colours, flames, words, a Fremen yelling fanatically, ships exploding, sand worms and faces ( a rapid montage of scenes from the second part of the film)."],["a","The visions come on with hallucinating speed. Soon Paul begins to see all the dead bodies of the future, strangled, shot, stabbed, burned and hanged, stamped on, eaten by wild animals, buried in the sand, rotted or devoured by a giant worm, then the images begin to go back towards the past"],["p",212],["i","Jessica on top of Leto's body parts. Paul in the tent.",null,67,true],["p",213],["a","(montage of fragments of the film's first part)."],["a","Then, a gigantic blue egg coming out of the earth and bursting in a field of spice."],["a","Paul sees himself, his eyes completely blue. The vision comes to an end."],["a","Paul moans, taking his head between his hands."],["d","PAUL","I'm a monster, a freak !"],["a","Paul runs to his mother, takes her by the arm and tears her away from his father's body. He sends her rolling in the sand, then digs with his hands, buries the remains and covers them over, shouting."],["d","PAUL","You didn't want a son. You wanted a Kwisatz Haderach. A Bene Guesserit male. What did you do with me? Time is there, within me, and it doesn't stop. I'm at the crossroads of everything possible : the present, the future, and the past. I've died an infinite number of times, and I was born, and I am also emptiness filled with shadows... with heavens... with hells... you're already dead...I set the galaxy alight... Now, you are carrying in your stomach a piece of my father's flesh, which you will transform into life to bring a daughter into the world, my sister, here, on Dune itself."],["a","The Fremens will pick us up... the spice will enter our bodies and will bind us forever to this sand. We shall stop thinking about revenge, because you and I are Harkonnens. You are the daughter of Vladimir Harkonnen. The Baron is my grandfather. He was once attracted by a woman, and she was your mother. We shall have blue eyes... We shall steal water from the dead... you and I will be mingled into a single being... I'm not Kwisatz Haderach... I'm something different. I am the unexpected ; I am the end of the Galaxy."],["p",214],["a","Paul hides his face in the sand. Jessica helps him up and wipes his face."],["d","JESSICA","\"The Fremens will pick us up...\""],["d","PAUL","Yes, they'll call me Muad'Dib, he who shows the way... Now let me weep for my father...."],["a","Leaning on Jessica's arm and breast like a child, Paul begins to sob."]]},{"n":95,"h":"EXTERIOR. ROCKY WALL RUNNING ALONG THE DESERT.","b":[["a","There are two moons in the sky. A hurricane is starting. The wind is blowing strongly, raising waves of sand in the dunes."],["a","A scaled hare crosses the desert, afraid and looking for shelter. A laserbeam coming out of the sky disintegrates it."],["a","The sky is filled with Harkonnen space-ships sweeping the desert with laserbeams."],["a","Paul and Jessica, carrying the packet containing their tent, walk along the rocky wall, hiding."],["a","Rabban the Beast, together with a group of Harkonnens and Sardaukars, is leading a pack of hairy mutants with violet skin, long teeth, and hands and feet ending in claws. They move forward on all fours, sniffing the ground, with metal rings around their necks, chained like animals."],["a","A group of pursuers appears behind Paul and Jessica. A long way in front, another group is cutting off their path. Paul and Jessica stop in front of a smooth wall. Although they have not been spotted, Paul draws his sword, ready to face the army."],["d","PAUL","No future shows that they've taken us."],["a","The two groups have seen them. Rabban the Beast, who is travelling in a chair on a steel carrier borne by four solid-looking men, grips the arm of his slaves and, with ferocious roars, makes them run towards Jessica and Paul. The soldiers free the mutants who, thirsty for blood, rush towards the fugitives, letting off screams."],["a","A rock moves apart from the wall revealing the entrance of a tunnel. Kynes and Farok appear. They help Paul and Jessica to enter the opening. The rock moves back into place, closing off the tunnel."],["a","The powerless mutants yell and persist in scratching the rock with their claws. The soldiers come together to try and loosen the heavy rock."],["a","The wind is blowing more and more powerfully."]]},{"n":96,"h":"INTERIOR. A CAVE IN THE ROCKS.","b":[["a","An average-sized cave, lit up. In the middle there is a large packet covered with cloths. Also a curtain, some cases with cielagos, instruments, vases with cactuses and plants, and two chests."],["a","Kynes, Farok, Jessica and Paul run out of a tunnel. Kynes opens the chests, takes out two distilling appliances and two garments, which he gives to Jessica and Paul, who immediately begin to dress like Fremens."],["a","Meanwhile, Kynes and Farok uncover the packet which fills the room. It's an ornithopter. Jessica and Paul, wearing the appliances, get ready to board the machine. Kynes stops them :"],["d","KYNES","I'm risking my life for you, and I don't even know why?"],["a","Paul replies with calm and certainty."],["d","PAUL","For three reasons : because I am the legitimate Duke, Lord of Dune and you are to obey me, because I'm Lisan Al Gaib : the Voice of the other world, he who will fulfil your dream : fill this planet with water ; and because you know that my mother is the only woman you have ever loved in your life !"],["a","Jessica makes a gesture of surprise. Kynes falls to his knees in front of her and kisses the hem of her cape."],["d","KYNES","Holy woman, I've waited four centuries for you !"],["a","Emotion strangles his voice. Jessica, tears falling from her eyes, maternally kisses the old man who is weeping with happiness like a child."],["a","An explosion can be heard. A whirl of dust blows into the tunnel. Kynes tells them to board the ornithopter. He hands an automatic hammer to Paul ; it is a tool made by the Fremens. Farok moves a lever. A large stone rolls aside, revealing a hole : the exit for the orni. A very strong wind blows in, bringing clouds of sand. Farok gives a bat to Kynes. At its neck a tiny distrans has been hung. Kynes says a few words into the device and throws the cielago out of the cave."],["p",217],["d","KYNES","(to Paul) I hope they'll receive my message. In the desert strangers are killed so that their water can be extracted."],["a","They push the orni in front of the opening. The wind is now of hurricane force. Everything is the cave flies into the air."],["d","KYNES","(to Paul) Don't fly away from the hurricane. Enter it and let it carry you until it peters out. Always stay at the same height. Look for the centre and you'll be saved."],["a","Paul presses his hands to say goodbye. Kynes (kissing the ducal ring) \"Duke\" (kissing the top of his hand) \"holy child\" (kissing his palm, fervently) \"Prophet\". He runs over to Jessica, who takes his head."],["d","JESSICA","\"For the son\" (she kisses his forehead). For the man\" (she kisses his cheek). For the lover \" (she kisses his lips passionately)."],["a","Growling, chases and shouting in the tunnel..."],["a","They push out the orni which becomes invisible in the storm. Kynes draws his krys and stands in the middle of the room devastated by the hurricane."],["a","Farok takes off his cape and his turban, draws his Krys and goes over to Kynes."],["d","FAROK","You give your life for them and I give mine for you, old holy man."],["a","The gallery fills with soldiers, and mutants foaming at the mouth, all led by Rabban the Beast who roars and laughs like a madman."],["a","A brutal battle begins."]]},{"n":97,"h":"EXTERIOR. CENTRE OF THE TEMPEST.","b":[["a","A large black pillar marks the centre of the cyclone. The Fremen orni carrying Jessica and Paul is flying towards it, pursued by three Harkonnen aircraft. The Harkonnens try to shoot them down with laserbeams, but the whirlwinds prevent them."],["a","The orni enters the cyclone. The aircraft turn around and fly away."]]},{"n":98,"h":"INTERIOR. CABIN OF THE FREMEN ORNI IN THE STORM.","b":[["a","The hurricane batters the cabin. Paul is fighting with the controls. Through the windows, the wings can be seen retracting. The faces of Paul and Jessica became drawn under the effect of acceleration. They enter a cloud of dust which becomes progressively thicker. The moons and the desert disappear. Darkness. The machine turns round. Paul struggles to try and stabilize it. The wings, straight and rigid, can be seen extending. Then they crack."],["a","The orni leans to its left, and drops. Paul fights to put it back in an upright position. He finally succeeds."],["d","JESSICA","We're going at 500 miles an hour !"],["d","PAUL","We can't go down, nor go up, nor leave. We have to wait !"],["d","PAUL AND JESSICA (eyes shut, they intone)","Fear is the assassin of the mind. It is the little death which leads to annihilation. I shall confront my fear. I shall permit it to submerge me and pass through me and, after its passing, my inner eye will find its way again. From whence the fear will have come, nothing will remain of it. I alone shall be there\"."]]},{"n":99,"h":"EXTERIOR. ORNI IN THE MIDDLE OF THE CYCLONE.","b":[["a","The cyclone moves towards the desert interior with the orni still inside it. The litany of Fear comes to an end."]]},{"n":100,"h":"INTERIOR. HALL AT THE GOVERNMENT PALACE.","b":[["a","The hall has been redecorated. The walls are covered with Harkonnen flags and emblems. A huge bed stands in the centre of the room."],["a","The bed looks like an elephant skin split into two : two hooves lie one side, and two the other. The frame, five square metres in area, features an elephants head, cut widthwise. The upper part of the skull, the forehead and ears, forms the back of the bed, the lower part, the eyes, trunks, jaws and tusks, are the bed itself. The enormous sculptured skull is covered with grey, velvet and satin. On the bed, there are baskets filled with fruit and sausage. Baron Vladimir Harkonnen uses Feyd Rautha's stomach as a pillow. He is dressed, like a courtesan, in glittering négligés. Feyd Rautha is holding a large gold phallus giving forth a stream of wine which the Baron collects in a glass and drinks."],["a","The Baron lowers one of the elephant's tusks. A gong rings out. While Feyd Rautha is trying his skill at throwing darts at the buttocks of kneeling black slave women kept on the ground by soldiers, sticks pressed against their necks, Rabban the Beast, excited and happy, enters making a number of respectful gestures. Two soldiers push forward stretchers where Kynes and Farok are lying, asleep and covered with wounds."],["d","RABBAN","They're dead, Baron : the woman and the child."],["d","VLADIMIR","You saw their bodies ?"],["d","RABBAN","(hesitating) We saw them disappear into a storm."],["a","Vladimir throws his glass in his face."],["d","VLADIMIR","You ass ! Why do you say so if there's no proof !"],["a","Rabban's reflex is to grab the top of his sword in anger. Feyd Rautha runs his fist through with a dart. Rabban tears it out in pain and, beside himself, sticks it in the buttocks of a black woman, shouting."],["d","RABBAN","It was a hurricane moving at five hundred miles an hour. No machine can resist that. They're dead !"],["a","Vladimir, calm again, puts on some more lipstick while looking at himself in a pocket mirror."],["d","VLADIMIR","You can kiss my Imperial anus."],["p",222],["a","Rabban buries his head in the voluminous behind presented him by the Baron and kisses it."],["a","Vladimir drop his negligés again, comes closer to the stretchers and uncovers the bodies of Kynes and Farok. He grazes lasciviously Farok's athletic body."],["d","VLADIMIR","Hmm... I'll take him with me to Giedi One. He'll make a good gladiator (pointing to Kynes). He represents the Emperor. We can't kill him. Perhaps... an accident... Take them away and bring Hawatt... we'll make him think Jessica and Paul are alive..."],["a","While Rabban goes out with the two anaesthetized bodies, the Baron starts singing and dancing, floating with the use of his anti-gravitation devices and getting Rautha to dance."],["a","Thirty soldiers led by Rabban bring in Hawatt. Several soldiers armed with long sticks tipped with leather straps are needed to contain the old man, whose blood-stained clothes are in rags. He is fastened by the arms, legs, abdomen and neck. The sticks enable the soldiers to keep him at a distance of over twelve feet. They make him fall to his knees in front of Vladimir."],["d","HAWATT","\"What more do you want ? The Duke and all the Atreides are dead .. Let me die as well\"."],["a","From his false chest, Vladimir draws a little bottle which he places on a small gold tray in front of Hawatt. He gives orders. Hawatt's right arm is freed."],["d","VLADIMIR","Die if you so wish..."],["a","Hawatt unplugs the flask and breathes its contents."],["d","HAWATT","The irrevocable poison !"],["d","VLADIMIR","Death inside five minutes ..."],["a","Hawatt breathes in deeply and calmly, with dignity and courage, he drinks the poison to the last drop."],["a","The liquid seems to burn his throat. His stomach turns over. His body is suddenly seized with a convulsion, even though sticks are holding it down."],["a","Vladimir draws another phial from his breast. He talks quickly."],["p",223],["d","VLADIMIR","Even if you know Jessica is alive ? She has seduced Dr. Yueh. She has betrayed us, the Duke and I, by murdering Peter and running away into the desert. Don't you want to take revenge on this woman ? I need a Mentat. Help me carry out my plans and I shall help you avenge the Atreides."],["a","Hawatt is already almost in agony."],["d","HAWATT","The Bene Guesserit witch... I must live to see her gutted !"],["a","He painfully stretches out his hand and drinks the antidote. Vladimir gives the order to free him."],["d","VLADIMIR","You will receive your antidote every day. It will keep you alive. If you don't serve me, I shall stop giving it to you and the poison, which will always be in your bones, will kill you."],["a","EXTERIOR. LARGE FLAT LAND WITH SOME ROCKS. NIGHT."],["a","The ornithopter comes out of the cyclone and lands laboriously in a large desert filled with rocks. On landing, the ornithopters wings break. The cyclone is dissolving. Paul and Jessica quickly jump from the machine, taking their possessions with them. They run to the rocks. A loud whistling can be heard. A hillock of sand rushes towards the orni and the mouth of a worm sucks in the machine."],["a","Paul and Jessica shelter among the rocks. They spread out their possessions in front of them. An inflatable tent, a hammer, a compass, a tetanizer and a telescope."],["d","JESSICA","We'll learn how to hunt. We'll survive like the Fremens...."],["d","PAUL","We'll have to meet them. We'll walk at night and sleep by day..."],["a","They set off again. The sand is soft and their feet sink. Some heaps of sand collapse like rock avalanches, nearly burying them alive. They escape by sticking to a path winding between the rocks."],["a","They keep walking in the sand between blocks of stone. The dust flies up at them, and blocks their breathing. Exhausted, they take a rest. They open the packet, taking out energy pills. Jessica takes the pills and drinks a few drops of her distilling-appliance water with disgust. It tastes horrible."],["d","PAUL","Your body is the best place for keeping water. Drink it all. Trust your distilling appliance..."],["a","Paul takes a long drink of the water which he draws from his pockets, several litres of it. Jessica, revolted more and more by its smell and bitter taste, drinks the water, getting the better of her desire to vomit. They finally arrive at the point where the rocks finish, and the vast, flat Land can be seen."],["a","Jessica looks through the telescope. A mile or two away, there are other rocks and dunes covered with vegetation, visibly cultivated by human beings."],["d","JESSICA","Brushwood to keep down the sand. Someone lives over there."],["a","Paul grabs hold of the telescope and looks through it."],["d","PAUL","We'll have to cross three miles with no cover..."],["a","A giant worm passes nearby. Its whistling is deafening. Paul buries the mechanical hammer between some rocks and turns it on. A powerful hammering can be heard."],["d","PAUL","That'll distract the worm ! Let's go !"]]},{"n":102,"h":"EXTERIOR. THE FLATLAND. NIGHT.","b":[["a","The sky is dotted with stars."],["a","An expanse of sand and the sky all there is to be seen."],["a","Paul and Jessica are crossing a spice field. In the distance, the hammering and the worm's whistle can be heard."],["a","The spice grows bigger and ripples in the gentle breeze. Its blue canals, geometrically arranged, emit a soft murmur."],["d","PAUL","Break the rhythm of your steps to stop the worm discovering us. Imitate the natural noises of the sand."],["a","They keep walking, making their steps as irregular as possible, half walking, half sliding."],["a","The sound of the hammer can be heard, and a sudden explosion of rocks."],["d","JESSICA","The worm has destroyed the hammer. Let's hurry !"],["a","The spice has come to an end. The ground is as hard as stone. Suddenly, their steps start resounding very loudly indeed."],["d","PAUL","The sand-drums ! Run !"],["a","He and Jessica begin to run towards the rocks somewhere further away. Their steps resound like explosions prolonged by the echo."],["a","The worm hears the echo of these steps and rushes towards the source of the noise. Paul and Jessica hear the worm's noise and run faster."],["a","They reach the rocks, having successfully crossed the Land."],["a","They are now in front of the dunes covered with brushwood, cactuses and spiny plants cleverly arranged in wide rows."],["a","Paul and Jessica climb up the rocks. Jessica cries out in horror. The worm's whistle is deafening."]]},{"n":103,"h":"EXTERIOR. ROCK LEDGE. NIGHT.","b":[["a","There is a crack in the ledge. Jessica and Paul enter it, pressed against each other."],["a","The open mouth of the worm emerges in front of them. An enormous hole with teeth gleaming in the light of the two moons."],["a","The mouth looks around, sways, closes, opens, moves forward and then backwards."],["a","Jessica's and Paul's hearts are beating rapidly. Their breathing is irregular. They stop their hearts and cease breathing. Only the deep breath of the searching monster can be heard."],["a","In the distance, another... boom... boom... rings out very loudly."],["a","The monster disappears."],["a","Paul leans out, Jessica comes closer to him. Paul drinks a mouthful of water from his appliance. This time Jessica takes a long drink with pleasure."],["d","JESSICA","Another..."],["d","PAUL","The Fremens..."],["d","JESSICA","They have come to help us."],["d","PAUL","They don't know were here. They're calling the worm for something else..."],["d","JESSICA","Do you think they can ..."],["d","PAUL","Communicate with the worms ? Maybe..."],["a","Paul and Jessica gather up their possessions and continue trying to climb the rocks."],["a","Jessica shows Paul some steps cut into the rocks."]]},{"n":104,"h":"EXTERIOR. STEPS CUT INTO THE ROCKS. NIGHT.","b":[["a","Paul and Jessica climb the perfectly cut steps."],["a","They come out on to a pass."],["a","They walk a few yards."],["a","The pass opens on to a ravine."]]},{"n":105,"h":"EXTERIOR. RAVINE-GARDEN. NIGHT.","b":[["a","The ravine is filled with bushes, cactuses, grass, flowers and fruit trees. It's a wonderful garden, with a fine geometrical layout."],["a","From the pass above, Jessica and Paul look with wonder at the beauty of this place."],["a","A stairway connects the pass to the garden."],["a","Paul and Jessica take it and walk down."],["a","In the garden, they breathe the smell of the flowers, and eat the fruit."],["a","Then they blow up the inflatable tent."],["d","PAUL","Let's sleep here. We'll meet the fremens tomorrow."],["a","Voice of STILGAR : Intruders have always regretted meeting the fremens."],["a","Voice of JAMIS : Hurry up, Stilgar. Soon it will be dawn. Extract their water, and we'll go."],["d","JESSICA","(to Paul) How many are there ?"],["a","Paul listens carefully in all directions, receiving and hearing the imperceptible breathing of the hidden fremens."],["d","PAUL","(to Jessica). Forty."],["a","A big fremen lets himself fall down from the top of a tree and drops motionless a few steps away from Jessica and Paul, who, strategically, moves away from his mother."],["a","Two knives are planted at the feet of Jessica and Paul."],["d","STILGAR","(arrogantly) Such is the law of the desert. You can take your lives yourselves, with dignity; otherwise, I'll have to kill you."],["d","JESSICA","(arrogantly) Who comes out of the night like this ? Like a common murderer ?"],["d","STILGAR","Stilgar. Head of his tribe !"],["d","PAUL","I know you. You were at my father's party."],["d","STILGAR","The Duke's son ! We've received a message from Kynes about you. He believes you are Lisan Al Gaib. You"],["p",229],["d","STILGAR","have conquered the desert, you can join us. But the woman..."],["d","A VOICE","Don't waste time, Stilgar. Carry out the law !"],["d","STILGAR","Woman, take this knife and cut your jugular vein with it. A single clean cut will be enough. Understand us. You know nothing of the desert. One mistake by you and the whole tribe would be lost. Your water belongs to us by right."],["a","Jessica goes to take the knife... pretends to trip... and attacks Stilgar who, taken by surprise, draws his Krys. Jessica dodges the blow, hits him, presses a nerve centre on his neck and leans with her back on a rock using Stilgar, now immobilized, as a shield. Paul runs towards the trees. Jamis, a bearded fremen, attacks him with his gun. Paul hits him in the chest, leaps aside and knocks Jamis out with the side of the hand on his neck. The fremen loses consciousness. Paul and Jessica have used the voice to partially immobilize the fremens."],["a","Paul picks up the arm and begins to climb the rocky wall. Shots break out around him. He shelters behind a ledge, from which he can cover and defend Jessica."],["d","STILGAR","Stop ! She's cutting my neck !"],["d","JESSICA","Don't chase after my son !"],["d","STILGAR","Leave the child !"],["d","JESSICA","Come out, everyone ! I know there are forty of you."],["a","A group of fremens comes out from the cover of the trees. They stop in front of Jessica."],["d","PAUL","Careful, Jessica. There are only thirty-nine. One's missing."],["a","Voice of CHANI : I'm here. . ."],["a","Chani comes out from behind a rock. Paul is on the end of her gun. Chani is fourteen years old."],["d","STILGAR","Leave him, Chani"],["d","JESSICA","You can come down, Paul."],["p",230],["a","Paul and Chani lower the arms with which they were threatening each other. The look at each other, and like each other."],["d","PAUL","I have dreamed about you, Chani."],["a","Chani takes off her turban, freeing long and beautiful hair which is red instead of brown."],["d","CHANI","I'm Pardot Kynes' daughter."],["a","They come down. Chani goes back to the group of Fremens and Paul goes and stands near his mother and Stilgar."],["a","The Fremens bring Jamis out of his unconsciousness and hold him up so that he can listen to Jessica."],["d","JESSICA","I taught my son to fight. We have beaten two armed Fremens."],["d","STILGAR","It's a considerable measure of power. If you have been able to finish me off, this strange art can help you defeat all the others."],["d","JESSICA","And what if I teach you this strange art ?"],["d","STILGAR","We'll accept you into our group."],["d","JESSICA","How do I know you're not lying?"],["d","STILGAR","Here we have no contracts and no papers. We don't forget promises made at night, when dawn is up. My word is that of my people. Teach us the strange Art and your water shall mingle with ours."],["d","JESSICA","The Harkonnens will ask a reward for us."],["d","STILGAR","Your art is worth more than all the Harkonnens' money."],["a","Jessica cautiously frees Stilgar. She and Paul draw closer to each other, in the event of a betrayal."],["a","A fremen hands two green crape handkerchiefs to Stilgar. They all wear these handkerchiefs around their necks. Stilgar rolls them between his fingers and knots them around Jessica's and Paul's necks."],["d","STILGAR","Now you belong to Stilgar's sietch (to Chani). Attend to the child-man."],["d","PAUL","My name is Paul."],["d","STILGAR","If you want to be a true fremen, Paul must die. Soon we shall give you a new name (to Jamis) Jamis, can you walk ?"],["d","JAMIS","(grunting). Of course I can."],["d","STILGAR","I'll attend to the woman (naming two men) follow us and erase the footsteps ! The two newcomers haven't been told. Get into line."],["a","Like an army, the fremens get into line."],["d","CHANI","(to Paul). Watch where you put your feet, don't touch the bushes, don't break a single leaf, and leave no footsteps."],["d","STILGAR","We should arrive at the Sietch before daylight."],["a","They all set off marching."]]},{"n":106,"h":"EXTERIOR. ROCKS AND DESERT, NIGHT.","b":[["a","The forty Fremens, Jessica and Paul reach the edge of the rocky area. A flat desert stretches in front of them. Two fremens set up an automatic hammer."],["a","Chani sticks Paul against her back and fastens him to her waist with a belt."],["a","Stilgar binds his body to Jessica's."],["a","The hammer starts ringing out rhythmically."],["d","STILGAR","Woman, if you make a mistake, our lives are lost. Adapt your body to mine, and we're saved."],["a","The forty Fremens take hooks off their belts and hold them up in their hands."],["a","They kneel down and stick their foreheads on the sand, putting the hooks in front of them. Only Chani and Stilgar remain standing, together with Paul and Jessica."],["a","In the distance, a hill of sand can be seen moving, and the worms whistle can be heard."],["a","Stilgar : Shai-Hulud, Father of the desert."],["a","The other Fremens : Shai-Hulud, father of the desert."],["d","STILGAR","You will carry your people."],["a","The FREMENS : You will carry your people."],["d","STILGAR","Through death."],["a","The FREMENS : Through death."],["d","STILGAR","Till the end of the universe."],["a","The FREMENS : Till the end of the universe."],["d","STILGAR","There where life begins."],["a","The FREMENS : There where life begins."],["a","A gigantic worm draws near."],["p",234],["a","The Fremens run towards a strategic point and while the monster, attracted by its noise, moves towards the hammer, Stilgar, of necessity followed by Jessica, rushes towards the worm."],["a","The other Fremens follow him."],["a","The entirely ringed side of the worm can be seen. Stilgar sinks the hooks into the edge of one of the rings and throws up a sort of blanket, giving his feet a grip on the worm's body. The other Fremen do likewise. So as not to feel the sand on its sensitive skin, under the ring's scales, the worm turns over. This way all the fremens are on its back."],["a","The worm goes off into the desert, carrying the Fremen who are directing it."]]},{"n":107,"h":"EXTERIOR. DESERT AND ROCKS. DAWN.","b":[["a","The worm, together with the fremens, is approaching some rocky hills."],["a","Dawn begins to break. Both moons, one green and the other orange, are still in the sky but a huge white sun begins to emerge on the horizon."]]},{"n":108,"h":"EXTERIOR. SIETCH TABR. DESERT. DAYLIGHT.","b":[["a","Printed Title: THE SIETCH TABR."],["a","View of the Sietch : plantations in the dunes. Two or three large gardens."],["a","Rocks and caves."],["a","Clumps of flowers covered with canvases."],["a","A large oasis in the middle of the desert."]]},{"n":109,"h":"INTERIOR. THE CAVES AT SIETCH.","b":[["a","The forty Fremens, Jessica and Paul close off the entrance to the grotto with a plastic slab. The Fremens take off their distilling devices, as do Paul and Jessica."],["a","Fremen women - a large number of them - men and children run to welcome them."],["a","They are in a large cave, from where tunnels lead off in different directions."],["a","The inhabitants of these caves suspiciously at Jessica and Paul, and rush towards Stilgar, who talks to them in a dialect which Jessica and Paul do not understand. They can only pick out the words \"Lisan Al Gaib\" and \"Mahdi, Mahdi\" murmured by the fremens."],["a","The group, led by Stilgar and followed by the fremen people, takes a tunnel. In this tunnel, a number of entrances covered with tapestries lead in to the rooms where fremens live. They come out to the doorstep to watch the group pass by. These are dry, stout men, savagely beautiful women. Chani accompanies Paul. They pass by the entrance to a large room where children are studying. In another room, machines are producing blue blades... made out of plastic. There are also women filling cases with blue dust, an explosive spice by-product."],["a","They all arrive in a large cave which is round-shaped. The fremens, who now number several hundred, sit down on the stands arranged in a circle. In the middle of a closed circle, Stilgar, Jessica and Paul remain standing."],["d","STILGAR","Pardot Kynes has asked us to accept these strangers into our people. The woman possesses a strange Art which enabled her to defeat me."],["a","The fremen people react admiringly."],["d","STILGAR","She will teach us her fighting techniques. Kynes says that the child could be the Kwisatz Haderach. His mother is a Bene Guesserit, as the legend goes..."],["a","The fremen people again react."],["d","STILGAR","We haven't had the time to put them to the test."],["a","Jamis gets up, mad with rage."],["p",238],["d","JAMIS","The time has come. You know the Law, Stilgar, I demand proof. I defy this woman. The legend says that she'll choose a non-fremen champion : her own son."],["d","STILGAR","Jamis, he's only a child."],["d","JESSICA","I choose a champion who's not a fremen : myself. I shall fight against you. That doesn't go against the legend."],["d","JAMIS","No foreign woman will change our customs. I demand that the Law be carried out. I demand evidence."],["d","STILGAR","Woman, he's a mean man. Your son got the better of him."],["d","JAMIS","That was an accident. Witchcraft. I demand the fight !"],["d","JESSICA","(to Jamis, in the VOICE) : Listen !"],["a","Jamis moans with pain and, motionless, he listens."],["d","JESSICA","When you fight, your suffering will be such that..."],["d","JAMIS","(escaping her power). She's trying to bewitch me ! (he blocks both his ears with his fists) I demand silence !"],["d","STILGAR","Let it be so ! Carry out the Law. Woman, if you speak again, we shall expel you from the sietch and you will die in the desert."],["a","The fremens group together in a ring, leaving a large round space in the middle. Jamis is naked from the waist up and grabs a knife in his right hand. Chani helps Paul to get undressed and hands him a Krys. She whispers in his ear :"],["d","CHANI","(to Paul). Jamis fights with both hands. Look out for the moment when he puts the Krys into his left hand..."],["a","Slowly, Paul and Jamis draw near the centre of the circle."],["d","JAMIS","Let my Krys bathe in your blood !"],["a","He attacks Paul, and gives him a stab-wound, but Paul dodges and, from behind Jamis, tries to stab him while he has him at his mercy. But Paul's aversion to killing prevents him from doing so."],["a","He stops his knife not far from Jamis' back. Jamis turns round furiously and stabs forward again. Paul again dodges and, again, stops his Krys short"],["p",239],["a","of Jamis' back. This happens four more times."],["d","STILGAR","(to Jessica) Your son is playing with Jamis. There's nothing honourable about cruelty !"],["a","Jamis attacks once again. This time Paul, instead of dodging, disarms him and puts the point of his knife to Jamis' chest."],["d","PAUL","Do you give up ?"],["a","Jamis groans with shame and despair."],["a","The fremens are yelling hysterically."],["d","STILGAR","Calm down ! The child doesn't know our laws. (to Paul) Nobody can surrender during the ultimate test. One of you must die."],["a","Paul moves away from Jamis, letting him take up his krys again. Jamis, who is more cautious than before, now that he has recognized Paul's superiority, trembles in panic."],["d","STILGAR","(to Paul) Finish him off quickly. Don't play with him."],["a","Paul hesitantly begins to turn, following Jamis who is now almost mad with terror. Unable to decide whether to kill Jamis, Paul does not attack."],["a","An angry and scornful murmur, directed against Paul, rises from the audience."],["a","Jamis attacks Paul, who wards off this assault. The crowd roars excitedly."],["a","Jamis attacks once again and, at the last minute, passes his krys into his left hand. Paul does likewise, counter-attacks with his left hand and sinks the krys into Jamis' heart. Jamis collapses, having died instantaneously."],["a","A group of fremens rushes towards the body, shrouds it in a carpet and carries it off into a corner of the cave. Chani sadly helps Paul to get dressed. Paul is radiant, drunk with his victory,"],["d","CHANI","Why did you behave like a murderer ?"],["a","Paul's happiness immediately clouds over. From the other side of the cave, Stilgar remarks."],["d","STILGAR","When the time comes where you'll have to defy me to take my place, I hope you won't play with me as you did with Jamis. We kill with dignity !"],["p",240],["d","PAUL","(sadly) I wasn't playing with him. I couldn't... I didn't want to."],["d","JESSICA","It's the first time my son has killed a man with a side-arm."],["a","All the fremens murmur admiringly."],["d","STILGAR","That's why you asked him to surrender? Now we understand. It's good to know we haven't taken a scorpion in among us."],["a","Stilgar runs towards Paul and kisses him. Chani comes over to them. The fremens shout a cry of triumph. A few \"Mahdi\" can be heard."],["d","STILGAR","You must have a man's name. Which would you like ?"],["d","PAUL","What's the name of the mouse that jumps through the desert ?"],["d","STILGAR","Muad'Dib ! That's a good choice. Muad'Dib has the wisdom of the desert. She sleeps by day and hurts at night. She's fertile and doesn't abandon her young. Muad'Dib, we wish you welcome among us."],["a","Stilgar puts the palm of his right hand on Paul's forehead, then kisses him, murmuring \"Muad'Dib\"."],["a","Chani follows suit, then the other fremens kiss Paul and call him \"muad'dib\"."],["a","A group of old fremen women is preparing the funeral ceremony. There is not much light. Jamis' body is lying shrouded in a carpet. He is much smaller than when he was alive. Near him a transparent flask, containing six litres of murky water, has been placed."],["a","Around the body, the women are arranging an eight-petal flower with the help of variously coloured cloth pieces. In a corner Paul is resting, leaning on his mother's knees. Chani arrives, carrying a steaming dish in her right hand. With her left hand, she takes the flask filled with water, and goes and places it, together with the dish, at the feet of Paul and Jessica. On one plate, two roast birds are bathed in a blue spice sauce. Paul starts eating. Chani hands him the flask full of water :"],["d","CHANI","It's Jamis' water. It belongs to the victor, so that he can recover the water lost during the fight."],["d","PAUL","(with disgust) I don't want it."],["p",241],["d","CHANI","But... it's water !"],["a","Jessica realizes the importance which Chani attaches to water."],["d","JESSICA","(to Paul, in the VOICE) : Take the water !"],["a","Paul understands, changes his attitude immediately and takes the flask."],["d","CHANI","Water was the first creation ; it produced life."],["a","Paul, overcoming his revulsion , takes a long drink out of the flask."],["d","CHANI","Now, eat !"],["a","Jessica and Paul eat the birds. The spice immediately affects Paul who becomes motionless, falling under a vision."]]},{"n":110,"h":"INTERIOR. GOVERNMENT PALACE HALL. PAUL'S VISION.","b":[["a","Paul, now adult, is standing in front of the Emperor, his family, the soldiers, the fremens, the bene guesserits and the Guild representatives. At his feet Feyd Rautha is lying dead. Count Fenring attacks Paul and sinks a dagger into his back. Paul collapses, dead. Jessica and Chani scream."]]},{"n":111,"h":"INTERIOR. SIETCH CAVE.","b":[["a","The floral arrangement around Jamis' body has been finished. On the periphery of the cave green hanging tapestries can be seen. The fremens, all wearing green coats sit around the body, forming an eight-cornered star which prolongs the eight petal flower design."],["a","Stilgar and Chani are standing beside the body. Paul and Jessica, at the other end, are also wearing green coats. The fremens are intoning a funeral hymn while swaying backwards and forwards."],["a","A Krys is shining on Jamis' body."],["a","The few possessions left by Jamis are lying beside him ; a distilling device, a manual, a handkerchief, an automatic hammer, hooks and a balisette."],["a","Paul presses the flask containing Jamis' water. A line shows how much water is left."],["d","STILGAR","Where the root is, there the ash is. Jamis return to the place where days disappear. Jamis has given his water back to the water."],["d","THE FREMENS","As long as we live, Jamis will live !"],["a","Chani brings a large vase. She takes the flask held by Paul and pours the remaining water into the large vase. Chani is also holding a leather bag full of water, which she pours into the vase."],["d","STILGAR","Jamis had thirty three litres, seven drams and three seconds of the tribe's water. We bless that water."],["d","ALL THE FREMENS","Blessed be it !"],["a","Stilgar takes out a series of rings from a casket. He counts them like coins."],["d","STILGAR","Thirty three litres, seven drams and three seconds."],["a","There are three types of ring. Stilgar gives them to Chani, who shows them to Paul."],["d","CHANI","This is Muad'Dib's share .. Let him keep it and give it back at the end of his life for the good of the tribe."],["d","ALL","Bilal Kaifa."],["p",244],["a","Chani gives him the rings, Paul not knowing what to do was them, keeps them in his hand."],["d","CHANI","Later I'll show you how to wrap them in a handkerchief so that they don't ring when silence is necessary."],["a","Paul hands the rings back to Chani."],["d","PAUL","Could you keep them for me ?"],["a","The fremens smile and whistle maliciously. Chani blushes, and gives the rings back to Paul. Stilgar laughs softly."],["d","STILGAR","You don't know our customs, Muad'Dib. Proposing to a woman that she keep your water measures means..."],["a","Paul looks at Chani and understands. On the adolescent's face, love and anguish can be seen. Paul takes her hand, and gives her back the rings."],["d","PAUL","Can you keep my rings ?"],["d","CHANI","Where I am the water, let you be the tree !"],["d","THE FREMENS","Bilal Kaifa."],["a","The fremens solemnly intone a chant and surround the body."],["a","Chani and Paul carry away the large vase containing the water."]]},{"n":112,"h":"INTERIOR. WATER CAVE.","b":[["a","Chani and Paul come down a stairway cut into the stone. They are in an enormous cave, the ground of which is a basin fill of water. The distant banks are hardly visible. The reflections of the water transform the cave into a cathedral. Paul stops dead at the sight of this place :"],["d","PAUL","I know this place. I saw it in a dream."]]},{"n":113,"h":"INTERIOR. DREAMY EFFECTS","b":[["a","Bloody images of a religious crusade : fires, bodies, fanatical fremens screaming \"Muad'Dib\" ... Paul, now an adult, is at the head of the fremens, brandishing a blood-stained Krys. Madness can be read on his face."]]},{"n":114,"h":"INTERIOR. WATER CAVE.","b":[["a","Chani and Paul are coming down the bottom steps to the stairway. They are standing in front of a water-counting machine."],["a","Paul helps Chani to empty the water. A needle show the quantity of liquid poured out."],["d","CHANI","Exactly thirty three litres, seven drama and three seconds."],["a","Paul bends down to touch the water. Chani stops him."],["d","CHANI","Men dying of thirst came here and didn't touch this water. We now have more than thirty three million decalitres of it."],["d","PAUL","How long have you been collecting this water ?"],["d","CHANI","For four hundred years. Each fremen sietch has a basin like it. There are thousands. Listen..."],["a","They listen to the drops falling from the roof."],["a","There are not many of them."],["d","CHANI","Each drop extracted by the condensators is a blessing. A few centuries from now, we'll have as much as we need. We can then change the desert. Settle the dunes with plants, and create a habitable world of lakes, forests, fertile earth... Our descendants will live in a garden."],["d","PAUL","Who thought up this plan ?"],["d","CHANI","He who, at the age of three hundred and eighty six years produced me : Pardot Kynes."]]},{"n":115,"h":"EXTERIOR. DESERT. DAYLIGHT","b":[["a","Kynes, whom a burning sun is gradually killing, is making his way among the dunes, dragging himself along and tripping like a drunk. He had no distilling device but he is wearing his uniform, now in rags."],["a","His skin exposed to the sun is bright red, covered with sores. His swollen lips are encrusted with white scabs."],["a","The young Kynes, dressed in the planetologist's suit he wore on his arrival on Dune, appears at the top of a dune."],["d","THE YOUNG KYNES","I'm Pardot Kynes, His Imperial Majesty's ecologist, servant of this planet..."],["a","The old Kynes kneels down in the sand and strokes it with his arms and hands."],["a","The young Kynes, in the uniform of a soldier of the Emperor, is sitting on top of another dune."],["d","THE YOUNG KYNES","We shall try to do on Dune what has never before been seen on any other planet. We shall use man as an ecological force. We shall inject life into the sand."],["a","The old Kynes crawls on the sand, and groans."],["d","THE OLD KYNES","Men have been the plague of planets (getting up and shouting). We can't keep on plundering with no thought of those who'll follow us..."],["a","The young Kynes appears on another hill, and moves forward to meet the old Kynes."],["d","THE YOUNG KYNES","I ask you to have a mind of faith, sacrifice and courage. In a thousand years, our work will be a reality !"],["a","The old Kynes reaches a stretch of desert where the whistling of Spice can be heard. Something is boiling under the sand. The old man plunges his arms in this place, looking for humidity."],["a","The young Kynes, standing near him, tells him :"],["d","THE YOUNG KYNES","The gestating spice is fermenting. Little worms are beginning to lose their water in the solid mass.. the carbonic gas is going to explode..."],["p",249],["d","THE OLD KYNES","The excrement of the large worm, and the sperm of its larvae : excrement and seed in mother-water..."],["a","A blue sphere begins to emerge from the sand, becoming enormous... It lifts the old man, envelopes him and tears him into its centre. The sphere explodes in a noise of thunder. A large part of the desert becomes covered in a blue substance, the spice, vibrating and whistling."],["a","Pardot Kynes, with his arms in a cross, half buried in spice, is lying dead. A spice flower is growing from his open mouth."]]},{"n":116,"h":"INTERIOR. CAVE FOR THE GREAT CEREMONY.","b":[["a","The fremens are gathered together for the ceremony in an enormous cave which can hold thousands of people. Tunnels leading to all parts of the sietch come out on to a number of entrances."],["a","The ground is covered with carpets and the fremen people, sitting in perfect order opposite a platform set up at the back of the cave. They are waiting. On the platform, two seats cut out of stone face each other about ten feet apart."],["a","Two entry paths have been left free. They come out from two opposite tunnels and meet in the centre of the group, finishing up at the platform."],["a","The fremens are singing a mystic tune, all seeming to be in a trance. Two groups appear on the two paths. Jessica sitting on a board, carried on their shoulders by eight women, arrives to the right. Her naked body is covered with a semi-transparent green material."],["a","On the left, eight women are transporting a very old woman sitting on a board, like Jessica. She is almost bald, as thin as a skeleton, her back bent down with age. She looks like a monkey. She floats in Bene Guesserit clothes which are now too big for her. Like all the fremens, her eyes are completely blue. The two groups meet on the central path and move directly towards the platform."],["a","Paul, sitting between Stilgar and Chani in the first row, sees the two groups moving forward. Jessica and the old woman, are confused together in his eyes. He looks away, horrified."],["a","Jessica and the old woman are sat down on the platform seats, face to face."],["a","Stilgar rises and gets the singing to stop."],["d","STILGAR","The Harkonnens have put power into the hands of our worst enemy, Rabban the Beast. Tonight, we shall have to leave the sietch and go and hide in a place to which we alone, the Fremens, have access. The reverend mother will not be able to survive the trip and she wants to pass on her knowledge. Jessica, with her strange art, is going to try this experience. If she doesn't die, the prophecy will be verified, and we shall have a new mother superior."],["p",251],["a","The Fremens start singing again. Two other processions appear on the left and right paths : a group of men carrying on their shoulders a transparent plastic basin about ten feet long, filled with water ; and another group of men carrying another basin containing a little desert worm, alive and ten feet long."],["a","They place the basin filled with water between Jessica and the old woman. The singing becomes louder. They solemnly lift the basin with the worm and drop the animal in the water."],["a","A deathly hush settles."],["a","The worm begins dissolving on touching the water. The liquid bubbles and steams. Blue precipitates occur. Soon the worm disappears, leaving a murky blue substance in the basin. Singing breaks out again in the audience. The Reverend Mother gets up, and leaps forward like an animal. She is given the end of a tube which has been put into the basin and she carries it over to Jessica."],["d","REVEREND MOTHER","If you are not HER, this is the water of your death. If you are HER, it is the door to the universe."],["a","Jessica opens her legs slightly. The old woman kneels down in front of her and inserts the tube under the green veil. The old woman turns a key on the tube and the water begins irrigating Jessica's stomach."],["a","Jessica is suffering. She has the impression that her ovaries are being burned. Then it becomes cool and pleasant. Finally the pleasure arrives. A pleasure that she cannot contain, an intense orgasm she cannot prevent. She utters long cries of pleasure, then falls into a lethargy, breathing deeply."],["a","The old woman takes away the tube and leans over Jessica. She brings her face against Jessica's, and opens her closed eyelids. Jessica is in the middle of an epileptic attack. She is trembling and contracting. An abundant foam is coming out of her mouth."],["d","REVEREND MOTHER","The poison is in your blood. If you are HER, transform it or die."]]},{"n":117,"h":"INTERIOR. JESSICA'S VISIONS","b":[["a","A carbon atom. A twisting formation. A molecule of glucose. An entire chain of molecules."],["d","VOICE OF JESSICA","Methyl-Protein... The chain of molecules is transforming..."],["d","VOICE OF JESSICA","Change an atom of oxygen... Extract an atom of carbon... Mix it with oxygen... hydrogen...catalytic reaction..."]]},{"n":118,"h":"INTERIOR. CAVE FOR THE GREAT CEREMONY.","b":[["a","Jessica heaves a sigh of relief and, still a little dazed, she opens her eyes and smiles."],["d","REVEREND MOTHER","She has transformed the poison. She has changed the water of death into the water of Life. THIS IS HER !"],["a","The fremen people utter cries of joy."],["a","The women who carried the boards are overcome with a frenetic agitation and rush towards Jessica and the Reverend-Mother. They take off Jessica's green veil and undress the Reverend Mother. They put the Bene Guesserit costume on Jessica."],["a","They place the naked body of the old woman on Jessica's lap, as if she were a baby."],["a","The OLD WOMAN : Look at me. I am going to pass on my knowledge to you."],["a","Jessica looks at the old woman, who changes, her face becoming younger. Soon Jessica is holding a beautiful naked girl between her arms. The girl presses her mouth to Jessica's."],["d","THE GIRL","This is how I am. Don't fight against me. I haven't got much more time. Open your mouth, let me enter."],["a","Jessica opens her mouth. The inside of Jessica's mouth can be seen, dark and red."]]},{"n":119,"h":"INTERIOR. JESSICA'S VISIONS","b":[["a","A red sphere is floating, on the rhythm of a heartbeat, in the middle of the darkness. A green point appears, which grows until it becomes a green sphere."],["d","GREEN SPHERE","Don't be afraid, we are going to come together (voice of the old woman)."],["d","RED SPHERE","I'm not afraid (voice of Jessica)"],["d","GREEN SPHERE","There is some interference..."],["a","A blue point is now forming. It increased in volume, finally becoming a blue sphere."],["d","GREEN SPHERE","You didn't tell me that you were pregnant ! It's a woman ! I've no more time, I must come together with both of you. Help me, unite with your daughter... gently...absorb her fear... calm her... gently..."],["d","RED SPHERE","My daughter ... my poor little girl... I brought you into life and I have subjected you to knowledge, defenceless."],["a","Slowly, the red sphere absorbs the blue sphere. United, the two spheres are now only one, a violet colour."],["d","GREEN SPHERE","Now, accept me. I have four hundred years to bequeath you. I am the Missionaria Protectiva... You will carry me forever, as I have carried so many others !"],["a","The green sphere and the violet sphere come together, making a purple sphere."],["d","PURPLE SPHERE","Jessica is dead !"],["a","Inside the sphere Jessica's face appears. It splits vertically in two, revealing the face of an old woman. The face again divides, and again still more faces appear, young faces and old, young and old. Soon the changes are being made at a dizzy speed."]]},{"n":120,"h":"INTERIOR. THE CAVE FOR THE GREAT CEREMONY.","b":[["a","Jessica, changed and completely awake, takes the corpse of the Reverend Mother between her arms and approaches the fremens."],["d","JESSICA","I wasn't lying. I am the Reverend Mother ! The knowledge had been passed on. Let the ceremony continue !"],["a","The fremens stand up, take each other by the arm and begin to move their feet on the spot in a rhythmic motion, while singing. Jessica takes the tube, fills her mouth with liquid and spits in the glass put in front of her. The women empty this glass into the basin containing the poison. The water immediately begins to boil and ferment. It changes colour, becoming red."],["d","JESSICA","I have changed the water of death into the water of life. Let the fremen people drink and be united from now on !"],["a","Everyone passes round flasks filled with the liquid taken from the basin, and drinks."],["a","Chani hands a flask to Paul."],["d","CHANI","We are going to become as one being. We are going to dissolve in life..."],["a","Paul drinks. The fremens start shouting."],["d","THE FREMENS","Mahdi... Mahdi... Mahdi..."],["a","Paul comes closer to Jessica. She takes him by the shoulder and both walk towards the centre of the cave. Thousands of fremens are surrounding Paul and Jessica. They eventually form a large, dense wheel of bodies, singing and turning around faster and faster."]]},{"n":121,"h":"EXTERIOR. THE ARENA. DAYLIGHT.","b":[["a","The walls surrounding the arena look like the wall of a medieval castle. The place is black with people."],["a","Printed card : GIEDI PRIME - FOUR YEARS LATER."],["a","A band is playing a military march with strange instruments."],["a","A matador is parading in the arena with his assistants : there are horses with their backs in shells, torero-gladiators armed with large whips and, in the middle, Feyd Rautha, wearing boots, a small loincloth and a big hat."],["a","Vladimir Harkonnen is spread out on a couch in the royal box. Hawatt and a group of bodyguard soldiers are with him."],["a","Slaves are carrying fruit and flowers."],["a","In a corner of the box are Count and Lady Fenring, together with a group of Sardaukars as body guards. Baron Vladimir is applauding his nephew Feyd, who approaches the box, takes off his hat and instead of throwing it to Vladimir gallantly hands it to Lady Fenring."],["a","Vladimir, red with anger and jealousy, apologizes to the count."],["d","VLADIMIR","The empire's representative should not be offended by this hommage to his wife's beauty. My nephew is young and ignorant of court protocol."],["a","Count Fenring who brought his hand to the tetanizer hanging at his belt, smiles sourly. Lady Fenring takes a flower and throws it into the arena."],["a","Feyd receives it, breathes it and puts in in his loincloth, Vladimir shouts loudly for the band to start playing again."],["d","VLADIMIR","Muuusic !!!"],["a","The arena is deserted. A wooden door is opened. A gladiator, his eyes starting out of his head and his mouth dribbing, runs out. This is Farok who, overcome with a murderous madness, runs with an arm in his hand."],["d","VLADIMIR","(to Fenring). He has drunk some elacca, and that produces a mad fit of violence."],["p",257],["a","The audience is impressed, and cries out."],["a","Four horse picadors chase the gladiator and drive him into a corner. One of them sinks a pike in his left side. The four horsemen go off again, leaving Farok with a gaping wound. Farok throws down his arm like an animal, takes off his cape, tears it up and bandages his side."],["a","Two torero-gladiators run in and bind Farok's wrists with their whips. They almost completely immobilize him holding his arms in a cross-like position."],["a","Feyd Rautha, with two banderillas in his hand, runs towards Farok amid the cheering of the audience. He also sinks the banderillas in Farok's shoulders."],["a","He moves away, applauded. The gladiator-toreros free Farok, who runs towards Feyd to kill him. Two other gladiators bar his way, and immobilize him again with their whips."],["a","Feyd Rautha sinks two more banderillas into Farok's shoulders. At a signal from Rautha, the band plays a tune. The audience is screaming frantically ."],["a","Rautha takes a long sword and a short dagger. The gladiator free Farok. Rautha and Farok are the only people left in the arena."],["a","Rautha draws nearer to Farok. The tense audience watches the scene in silence."],["a","Rautha runs towards Farok, and a fight begins between the two warriors. Despite his wounds, Farok is getting the better of Feyd. His arm chips Rautha's flesh in the biceps. This is a superficial wound."],["a","Baron Harkonnen screams despairingly. The crowd is shouting."],["a","Farok is holding Rautha on the ground. Slowly his arm draws closer to Rautha's neck."],["d","FAROK","(shouting) Death to the Harkonnens !"],["d","RAUTHA","(in a murmur) Bring the blade nearer my neck. Nearer, nearer still ! My audience is overcome with emotion. Now, listen to the keyword : (shouting) Scum !"],["a","(At this word, Farok freezes)"],["d","RAUTHA","You are conditioned. You won't move for two seconds. Now, I give you a little nick with my poisoned dagger..."],["p",258],["a","(he wounds him slightly on the shoulder) And ..."],["a","Rautha gets away from Farok, who recovers the use of his movements. But an intolerable pain immediately burns at his shoulder, he tries to insult Rautha, in vain... He totters. He comes up to Rautha who waits from him while performing a few dance steps."],["a","The public is going mad with enthusiasm. The new attack is brief. Farok is lost. He is in agony, and falls to his knees. Rautha looks him up and down, turns his back to Farok who tries a new attack. The crowd yells. Farok is unable even to lift his sword. Rautha, with winged elegance, plunges his sword in Farok's heart. A military tune breaks out. The audience, impressed, stands up. Farok runs, struggles against death, then falls. Rautha plunges the dagger in his neck. Farok dies instantaneously."],["a","The audience, deliriously excited, waves white handkerchiefs. An alguazil approaches Farok's corpse with a knife, and leans over him."],["a","While two mules drag Farok's body away, Rautha makes a lap of the arena, with an ear from Farok's body in each hand. The audience throws flowers and hats on the ground."],["a","A golden ladder comes down from Vladimir's box. While Rautha is climbing it, Vladimir's slaves cover him with white flower petals. When he arrives at the top, Vladimir kisses Feyd who is crowned with gold laurels."],["d","VLADIMIR","Hail Rautha !"],["a","The whole stadium raises their left arm, hands outstretched towards the sky, and shouts."],["d","THE CROWD","Hail Rautha !"]]},{"n":122,"h":"INTERIOR. DINING ROOM AT HARKONNEN CASTLE.","b":[["a","A red room, with sausages, hams, smoked fish, roast animals, etc... hanging from the roof."],["a","The large room is covered with baroque-styled plates. A gastronomical orgy is taking place : bottles of drink, cakes, incense, and magnificently built men doing a belly dance."],["a","Pleased with his victory, Feyd Rautha is drinking. Beside him the baron, aroused, is caressing him. Hawatt is silently watching the scene."],["a","Near them, are Count Fenring and his wife. The Sardaukars and Harkonnens are keeping guard. The back of each seat is a portrait of the baron, in relief. The baron is skilfully serving two plates of soup. The tureen is shaped like an iron dwarf."],["a","Two plates are set down before Count and Lady Fenring. A Sardaukar immediately takes out a poison-taster and places it beside the plates. Before Fenring has been able to use it, the offended baron breaks out."],["d","VLADIMIR","A poison-taster ? This is an insult which it is hard for us to forgive. Especially today when we are celebrating my nephew's victory !"],["d","FENRING","A victory ? I know Hawatt's style. The slave was conditioned to the word \"scum\" and Feyd's sword was dipped in poison. An easy way of making a hero out of him !"],["a","The baron and Feyd stand up aggressively. The Harkonnens make as if to go for their swords. The count gestures towards the sky."],["d","FENRING","If we die \"accidently\" the Emperor's Sardaukars will raze this planet to the ground tomorrow morning. There are five battalions who have the order to blow it up if we have a fatal accident."],["d","THE BARON","(soaking his hands in the soup plates). It is disgusting ! Flies in the soup !"],["a","He throws the plates of soup on to his slaves and has a plate full of other foods passed to Fenring and his Lady... He eats off the plate as well."],["p",260],["d","BARON","This is better."],["d","THE COUNT","The emperor mistrusts the Harkonnen house... through our Imperial Messengers on Dune ..."],["d","FEYD","The spies..."],["d","THE COUNT","We know that Rabban the Beast is oppressing the people, who hate him to death... This will allow Feyd Rautha to land on Dune and be welcomed as a hero."],["d","VLADIMIR","That's true. It's a very clever plan devised by Hawatt. When my nephew kills Rabban, they will all collaborate with him ."],["d","THE COUNT","How many free Fremens are there ?"],["d","HAWATT","About two thousand. Rabban has gradually exterminated them."],["d","THE COUNT","Not so. We know that ten million Fremens are hiding in the desert. If Feyd Rautha becomes a hero, he will have an army big enough to enable the Harkonnens to fight for the throne."],["d","VLADIMIR","A plot against the emperor ? Never ..."],["d","THE COUNT","If our suspicions prove founded... we shall have the support of the major houses and the minor houses to eliminate this planet."],["d","VLADIMIR","(perspiring in fear). What can we do to prove our innocence to the emperor ?"],["d","THE COUNT","Kill all the Fremens ! So that not one remains ! We cannot tolerate the existence of an army stronger than our own !"],["a","Fenring stand up."],["d","FENRING","Of course the extermination of the Fremens will be exclusively the work of Rabban the Beast. The emperor declines any historical responsibility for this genocide."],["d","VLADIMIR","We shall safeguard the Imperial honour ! In the hope that our fidelity may be rewarded."],["d","THE COUNT","(leaving). The emperor knows how to put vassals in their place."],["p",261],["a","Lady Fenring, without being seen, slides a ring off from her thumb and, ensuring that she is seen only by Rautha, moistens it with a little saliva. Then, under the table, she slides it on to Feyd's index finger."]]},{"n":123,"h":"INTERIOR. BEDROOM IN HARKONNEN CASTLE.","b":[["a","A room in which the large circular bed is surrounded by veils. The door opens gently. In his bed, Count Fenring is sleeping deeply with his mouth open. Fenring opens the door cautiously, she is dressed in a very short negligé ! Her lascivious beauty comes as a surprise. Feyd sticks out his head, and Lady Fenring lets him in. She closes the door, presses her whole body against Feyd and kisses him. Feyd pulls apart, worried, showing her the bed, and Fenring sleeping. The lady laughs, takes his arm and brings him to the bed, beside the count. She undresses Feyd and makes him stretch out on top of her."],["d","LADY FENRING","I drugged his coffee. He'll sleep till morning."],["a","Feyd laughs, and brutally tears off Lady Fenring's clothes. She embraces him."],["a","Dawn appears through the open window. Lady Fenring wakes Feyd. She closes the door behind him, breathing a sigh of relief. Count Fenring then stops pretending to sleep and sits up on his bed. Lady Fenring sits beside him and kisses him tenderly. The count touches her stomach."],["d","THE COUNT","All right ?"],["d","THE LADY","Yes"],["d","THE COUNT","I'm still old-fashioned. I suffer."],["d","THE LADY","My poor love ... But it was the only way of saving the genetic line of descendants."],["d","THE COUNT","I understand the Bene Guesserit. The man is a failure... A change is needed."],["d","THE LADY","This wouldn't have been necessary if Jessica..."],["d","THE COUNT","Don't complain ! The plan for genetic heredity is saved. The Kwisatz Haderach will be born !"],["d","THE LADY","And the Bene Guesserit will dominate the galaxy."],["d","THE COUNT","We shall dominate it !"]]},{"n":124,"h":"EXTERIOR. THE DESERT IN FRONT OF SIETCH","b":[["a","A troop-transporter has just landed in front of a sietch. Harkonnen soldiers come out of it and hide among the dunes. They watch the way the children are collecting the dew from the planets. The desert is covered with dry stubble twenty inches high, making a little forest."],["d","A HARKONNEN LEADER","Don't spare a single child, nor woman ! The extermination must be complete !"],["a","Still hiding, the Harkonnens move forward among the stubble towards the sietch. Just when they are in the middle of the brushwood, the fremen emerge from the sand where they were buried, breathing through reeds of stubble."],["a","Paul appears first, then Chani, and finally the fremens. This surprise attack enables them to put all the Harkonnens out of action. The plane tries to fly off and activates its wings. The fremens reveal a cannon hidden under a tarpaulin filled with sand, and shoot the plane which explodes."]]},{"n":125,"h":"EXTERIOR. ROCKS NEAR THE LARGE FLAT LAND.","b":[["a","The rocks are covered with fremens wearing the Fedaykin uniform : this is the army trained by Paul."],["a","As if in another world, they all intone a ritual chant. Stilgar is talking with Paul, whom Chani follows like a shadow ; she is holding a baby in her arms : Paul's son."],["a","Paul has completely blue eyes and his skin is burnt by the sun."],["d","STILGAR","Today you are going to prove that you are a true Fremen. For the first time, you are going to call a worm and get on its back. The least mistake will be fatal."],["a","Paul kisses the child which Chani sets in front of him, then kisses Chani and goes off alone, together with his fremens."],["a","One of them hands him two hooks ; another gives him an automatic hammer."],["a","Paul walks off into the large flat expanse, towards a spice field. The blue matter is vibrating, whistling and palpitating."],["a","Paul buries the hammer and turns it on."],["a","The hammer resounds : boom ... boom ... boom..."],["a","The fremens chant and become more and more excited."],["a","A gigantic mountain of sand approaches. Paul gets the hooks ready."],["a","The largest worm that has ever been seen comes out of the sand. It must be about half a mile long ; it is white and as high as a building. The fremens dance on the spot, up on the rocks."],["a","Chani shouts."],["d","CHANI","The prophecy is being fulfilled once again. This is the king of the worms, Shai-Hulud the white, the everlasting old father."],["d","THE FREMENS","Mahdi, Mahdi, Lisan al Gaib !"],["a","Paul runs towards the monster, sinks his hooks into one of the rings. Turning over, the worm raises him up. Paul, at the top of the ring, drunk with his success, cries with joy."],["p",265],["d","PAUL","Shai-Hulud heard my call. I was born today. I am a fremen !"],["a","From the rocks, Stilgar cries out in reply."],["d","STILGAR","You are the Kwisatz Haderach."],["a","Two hundred fremens leave the rocks and rush out towards the worm, with hooks in their hands, crying."],["d","THE FREMENS","Muad'Dib ... Muad'Dib ... Muad'Dib ..."]]},{"n":126,"h":"INTERIOR, CAVE-SANCTUARY.","b":[["a","Geometrical and mystical drawings, together with tapestries decorate the cave."],["a","Old fremen men and women, kneeling and sitting, are mumbling prayers."],["a","Jessica, sitting on a stone throne, is leading the prayer."],["a","Her eyes are completely blue, her gestures those of the Reverend Mother. She seems to be in a trance. There is nothing left of the old Jessica. A child of four years old, with an adult face, is sitting beside her. Her eyes are made up like priestesses' eyes. Her calm and serious attitude are not normal for a little girl of this age."],["a","A group of women is bringing in a woman who is nine months pregnant. She is writhing, almost dying in pain. A man follows the processions. The parturient is set down in front of Jessica's throne, and her arms and legs are bound. The woman is screaming in pain."],["d","THE FREMEN","(to Jessica). My son cannot be born ; my wife is going to die. Give her your blessing, Reverend Mother."],["a","Jessica gets up and examines the woman. She feels her forehead covered in sweat and takes her pulse. The fever is very high."],["d","JESSICA","An infection. There's nothing we can do."],["a","The man falls to his knees and intones a funeral chant. Everyone present comes closer and sings, led by Jessica"],["a","Alia gets up, with her eyes open wide and shining as if she were drunk ; she comes near the dying woman and places her hands on her voluminous stomach. The woman calms down, breathes and relaxes."],["d","ALIA","(talking like an adult). Take off her clothes. I am going to bring forth the child."],["d","THE MAN","(murmuring to Jessica). She's a witch !"],["d","JESSICA","I trust my daughter. While still within me, she received the knowledge of the Ancient Mothers."],["a","The woman is undressed. Alia gets undressed and lies down, naked, on the stomach of the woman, making movements with both her hands on it to impose"],["p",267],["a","a breathing rhythm."],["a","Alia, pressing with her feet and her hands on the stomach, seems to be a part of it, and starts weeping like a baby and pushing, gradually sliding on the stomach as far as the sex. She falls between the woman's legs, kneels down, takes the head of the foetus between her fingers and brings it into the world. Jessica lifts the baby in triumph and cuts the umbilical cord. The child is crying."],["a","Alia laughs strangely."]]},{"n":127,"h":"EXTERIOR. THE DESERT : A SPICE FIELD. DAWN.","b":[["a","A harvester, activated by smugglers, is extracting spice. Chani, Paul and his Fedaykins are watching them, hidden behind a dune."],["d","STILGAR","They never used to come so far before !"],["d","CHANI","Perhaps they're spies !"],["d","PAUL","We'll have to kill them."],["a","He makes a signal. The fremens equip a rocket-thrower, put a rocket in it, and fire. The harvester explodes. The fremens go into attack."],["a","The fight is engaged between them and the surviving smugglers. In the middle of a group of fremens, a smuggler is desperately defending himself. Shouts of anger, can be heard. Dust flies. The last one remains ; all the others are dead. Paul, followed by Chani and Stilgar, approaches the group. He moves aside the fremens. The smuggler is none other than Gurney Halleck, covered with wounds, about to be killed but resolutely fighting to the end."],["d","PAUL","Stop !"],["a","The fremens obey and stop their attack on Halleck."],["d","PAUL","Put away your sword, Gurney Halleck !"],["d","HALLECK","You know my name ?"],["a","Paul takes away the veil and the filters covering his face, and moves forward his hand ; the ducal ring is shining on his finger. Halleck gradually understands."],["d","HALLECK","(in a murmur). Paul (shouting) It is you, Paul ?"],["a","Paul opens his arms."],["a","Halleck throws down his sword."],["d","HALLECK","They said you were dead..."],["a","He runs and takes Paul in his arms, shouting for joy. The effort exhausts him. His wounds have made him lose too much blood. He faints in Paul's arms. He is laid on a stretcher. A fremen carries his balisette, plucks a few strings near Halleck's ears. Halleck, without opening his eyes, utters a few groans, takes the balisette, presses it against him and again loses consciousness. The fremens leave, taking the wounded man with them."]]},{"n":128,"h":"INTERIOR. A SIETCH CAVE.","b":[["a","The fremens enter the sietch, and close off the entrance with a plastic door."],["a","The women run to greet their warriors."],["a","Alia appears, also running, and throws herself into Paul's arms."],["a","She sees Halleck, unconscious and covered with blood-stained bandages pressing his balisette against him."],["d","ALIA","Gurney Halleck. I saw him in Jessica's memories."],["d","PAUL","Help his wounds to heal. He must live !"],["d","ALIA","He'll live !"],["a","Paul leaves the group, takes a tunnel, lifts a tapestry and enters a room cut into the rock."]]},{"n":129,"h":"INTERIOR. A SMALL CAVE.","b":[["a","The little grotto is covered with tapestries. Cushions form a bed. On a foot-table made of forged copper, cups of coffee can be seen, together with a coffee pot where a blue spice coffee is boiling; this is Jessica's bedroom."],["a","Paul enters. Jessica is meditating, her legs crossed. Paul sits down opposite her, in the same position."],["d","JESSICA","Halleck is alive."],["d","PAUL","Yes (he takes out a roll of paper). We found this message on the body of a Harkonnen. It's the order to exterminate all the fremens."],["d","JESSICA","The time has come. Our men know the military arts of Bene Guesserit. You have given them new arms. The leaders of the sietchs are together in the large cave, awaiting your decision. You must challenge Stilgar, kill him and assume command of the armies. They are all prepared to follow you."],["d","PAUL","Stilgar saved our lives. He is our friend."],["d","JESSICA","This is the Law. To become leader, you must kill the old leader."],["d","PAUL","I prefer not to fight for the command."],["d","JESSICA","You cannot oppose fate. It is written. You are Lisan Al Gaib, the only man capable of uniting the fremens. Stilgar will give his life with joy."],["d","PAUL","You aren't at all human ! Like all the Bene Guesserit, you don't mind killing if you achieve your purposes : destruction, fanatical crusades, power !"],["d","JESSICA","So you prefer to be a slave ? In this world, you must kill or be killed !"],["p",271],["d","PAUL","I'm tired of being just a pawn ! I don't want to be used... Look what you did with me... I already know what we're going to say, and what's going to happen. I know the future, to the thousandth of a second. The present is past for me. I'm outside time, since I've already seen myself die. All you're interested in is to be mother of Kwisatz Haderach. You continue to obey the Bene Guesserit conditioning. You used me, my friends and my father too."],["a","Jessica can no longer contain herself, and gives Paul a strong slap on the face."],["d","JESSICA","Don't sully my relations with your father !"],["d","PAUL","You're no longer Jessica, no longer my mother. You are my enemy, a witch. I'm Paul, a human being. I don't want to travel from planet to planet, exterminating millions of men ! I don't want fire, nor violence!"],["d","JESSICA","(coldly). The leaders are waiting for you. If you don't do it, I'll challenge Stilgar and take command."]]},{"n":130,"h":"INTERIOR. CAVE FOR THE GREAT CEREMONY.","b":[["a","The leaders of the various sietchs are gathered together in an assembly. These are the strongest men of the fremen race, together with their delegations. Stilgar is waiting."],["a","Paul takes his place on a stone seat."],["a","The leaders watch him intensely, looking out for the challenge."],["d","A LEADER","Muad'Dib, strong man among strong men, now has come the time for revenge. We would like you to be our leader."],["d","STILGAR","Muad'Dib, respect the customs. Spill my blood for the good of the tribe."],["d","PAUL","The customs must change, Stilgar."],["a","A disapproving murmur can be heard among the leaders"],["d","PAUL","Stilgar, do you think I want to cut off my right hand ? Do you think I want to rob the tribe of its strength and wisdom ?"],["a","Paul draws his dagger and hands it to Stilgar."],["d","PAUL","Let me not be treated as a coward ! If blood must run for the good of the tribe, let it be mine."],["a","He stands in front of Stilgar with open arms."],["a","Stilgar drops the dagger."],["d","STILGAR","The fremens know you are stronger. I cannot kill Lisan Al Gaib. Customs change."],["d","PAUL","Everything which hinders our development must change. We have cut, for long enough, the best branches off our tree. The fremens must stop spilling fremen blood. Among us, violence will not exist. We form one body only, one mind only. We have an important task ahead. Each of my leaders represents an arm... Would you destroy a knife just before the battle ? When Dune will be ours, we shall need strong men to make the desert fertile ... Stilgar will be the governor of this planet...He is honest and wise... He is our right arm...We are an army at war... We must stop killing our own generals."],["p",273],["a","The leaders rise, shouting enthusiastically."],["d","THE LEADERS","Muad'Dib ! Lisan Al Gaib !"],["d","PAUL","Death the Harkonnens !"],["d","THE LEADERS","Death !"],["a","Followed by Chani, Alia runs in and rushes into Paul's arms. Paul utters a despairing cry and runs out."]]},{"n":131,"h":"INTERIOR. IN THE SMALL CAVE.","b":[["a","Paul, Alia and Chani burst in to Jessica's room. Although paralysed, Halleck is holding Jessica between his arms. He is threatening her neck with a sword."],["d","HALLECK","Don't move, Paul ! The witch froze me for a moment but I'm now free from the hold of her voice."],["d","PAUL","(in the VOICE) Stop !"],["a","Halleck again freezes, but without letting Jessica go."],["d","PAUL","(in the VOICE). Free my mother !"],["d","HALLECK","No ! Nobody can prevent my revenge. This woman killed your father, Paul !"],["d","PAUL","You're wrong, Halleck. Yueh killed him."],["d","HALLECK","I saw Vladimir Harkonnen's message !"],["d","PAUL","Please, Halleck, don't hurt my mother. I can answer for her, on my life. It was a trick. Who do you have to believe, a Harkonnen or an Atreides ?"],["d","HALLECK","How she's bewitched you !"],["d","PAUL","(alarmed). If you hurt her, I'll cut you into pieces !"],["d","HALLECK","What do I care. I have only survived to take my revenge."],["d","PAUL","I know how much my father loved her ! I saw her sobbing on my father's corpse !"],["a","He throws down his arms, takes a tape-recorder on the table and plays Yueh's message."],["d","VOICE OF YUEH","When you hear this, the Duke and I shall be dead."],["d","PAUL","This is the voice of a traitor confessing his crime. Free her, Gurney."],["a","Gurney lets Jessica go and falls to his knees on the ground."],["d","HALLECK","Madam... kill me... please..."],["d","JESSICA","You thought you were avenging Leto, and this is honourable. You have shown the strength of your love for the Duke, I forgive you. (she kneels down beside Halleck and embraces"],["p",275],["a","him). It was a fight between old friends..."],["a","Halleck hides his face in Jessica's breast and bursts out in sobs. Chani and Alia kiss and calm Paul who has also collapsed, half unconscious. Jessica and Halleck come closer to them and they all embrace in a compact group."],["d","JESSICA","(to Paul, with much tenderness). Paul, there are times when I am myself... Yes, I manipulated you, changed you to make you follow my path... A path that my education has made me choose. Paul, free yourself from me. You have a wife, a son, this desert that you love... Leave everything. Let there be no obstacles in the way of your happiness."],["d","PAUL","I am Paul, your son. But I'm also Muad'Dib, the leader of the fremens. My wife will scorn me if I abandon my people. You are Jessica, and you're also the Reverend Mother. You can't abandon your people either. Until now, I have followed your path. Now, it's up to you to follow me. I will take you where you cannot go alone. Together, we shall create the Kwisatz Haderach. Make me undergo the test of the poison."]]},{"n":132,"h":"INTERIOR. CAVE FOR THE GREAT CEREMONY.","b":[["a","The fremens are filling the cave. There seems to be thousands of them, with their leaders in the first row. Chani, Jessica, Stilgar, Halleck and Alia are watching : a small worm is being drowned. The poison forms."],["a","Jessica hands a tube to Paul."],["d","JESSICA","This is the test that no man has undergone successfully. You are going to take a path littered with the dead. If you return, you will be the prophet !"],["a","Paul puts the tube in his mouth and drinks in large gulps. He starts trembling straight away, writhing in pain and contracting. Then he falls into a catalepsy. A stream of blue foam comes out of his mouth."],["a","Paul begins speaking with a deep voice, very different from his own."],["d","PAUL","The poison has been transformed. Come!"],["a","Jessica approaches Paul's body."],["d","PAUL","I shall show you the place you cannot enter. Lie on top of me. Let us mingle our salivas."],["a","Jessica stretches out on top of Paul and presses her mouth to her son's."],["a","A long kiss, surrounded by foam, brings them very close together."]]},{"n":133,"h":"EXTERIOR. THE CENTRE OF THE UNIVERSE.","b":[["a","The camera travels through the universe, leaving behind it suns and planets and galaxies ; it plunges towards the centre."],["d","VOICE OF PAUL","Still further. Let's go towards the centre."],["d","VOICE OF JESSICA","I am the universe - stomach !"],["d","VOICE OF PAUL","I am the son-father penetrating you towards the centre, still further."],["d","VOICE OF JESSICA","As far as the root."],["d","VOICE OF PAUL","To the place which you cannot see because it is yourself."],["d","VOICE OF JESSICA","You carry me towards myself."],["d","PAUL","Because I am you... You are the light, the path, the life..."],["d","JESSICA","There's the centre !"],["a","The shot draws closer to the centre of the universe : a sphere of blinding silver light."]]},{"n":134,"h":"INTERIOR. THE CENTRE OF THE UNIVERSE, IN THE SILVER LIGHT.","b":[["a","Paul is stretched out naked on his stomach against Jessica, lying naked on her back, her legs open. Like statues, mother and son, motionless, with their lips joined, are in a coital position."],["a","An abundant blue foam is running from their mouths."],["a","The bodies revolve until they look only like a wheel. The camera comes down into the centre of this wheel of flesh."],["d","VOICE OF PAUL","We have seen the forbidden place."],["d","VOICE OF JESSICA","Because I am you."],["d","VOICE OF PAUL","We are a single extended being."]]},{"n":135,"h":"TECHNICAL EFFECT.","b":[["a","Jessica's long sobs can be heard. Paul's face breaks into pieces which fall, revealing the face of Duke Leto."]]},{"n":136,"h":"INTERIOR. HALL FOR THE GREAT CEREMONY.","b":[["a","Jessica, stretched out on the stone ground, is weeping violently, her shoulders shaking in convulsions."],["a","The Fremens genuflect in front of Paul who moves towards them, as if he were a god. They are at the height of religious fervour."],["d","PAUL","I am Paul Muad'Dib, Lisan Al Gaib, the Kwisatz Haderach."],["d","ALL","Bilal Kaifa."],["d","PAUL","I am the Voice, the Light, the Path."],["d","ALL","Bilal Kaifa."],["d","PAUL","I am the Truth and the Life"],["d","ALL","Bilal Kaifa"],["d","PAUL","I am the sand, the worm and the water"],["d","ALL","Bilal Kaifa"],["d","PAUL","All will be for me You will give me your water and I will give you oceans You will give me this planet and I will give you the universe You will give me your life and I will give you immortality."],["d","ALIA","Lisan Al Gaib, Mahdi, Mahdi."],["a","Paul comes closer to a fremen, takes his Krys and lifts it."],["d","PAUL","Fire, tears and blood !"],["a","The Fremens are overcome by madness : they draw their krys and utter war cries."]]},{"n":137,"h":"EXTERIOR. DESERT. EVENING.","b":[["a","An enormous group of Fremens in arms, women as well as men, are running in the desert, screaming their religious and military fervour. They are led by Paul, together with Jessica, Alia, Chani and Stilgar."],["a","More groups of Fremens, with black and green banners, come from all parts of the desert to join in the crusade."],["a","There are thousands of them."]]},{"n":138,"h":"EXTERIOR. A TOWN IN THE DESERT. ALMOST NIGHT.","b":[["a","Like a tide, the Fremens, led by Paul, invade a town defended by the Harkonnen."],["a","The Fremen army goes on its way leaving behind it the town in flames, filled with the bodies of the Harkonnen."]]},{"n":139,"h":"EXTERIOR. DESERT NIGHT.","b":[["a","All the Harkonnen forces are grouped together in a circle. The Fremens are turning around them, attacking them relentlessly. The Harkonnen soldiers are falling and the circle is gradually being reduced. Finally a single ring of soldiers remains, defending a small mountain of shields, capes and feathers."],["a","The fremens kill the last of the Harkonnens. They move aside, making way for Paul to approach, followed by Jessica, Chani, Halleck, Alia and Stilgar."],["a","They surround the pile of shields."],["a","The Fremens begin to take down the mountain throwing away the remains."],["a","Beneath the rubbish, they find Rabban the Beast, whining on all fours with his head buried in the sand."],["a","Stilgar takes an arm in disgust and fires a bullet in Rabban's behind. Rabban dies."],["a","A long lance is raised in the middle of the groups of Fremens, with Rabban's head on the end."],["a","A great cry of triumph breaks out in the Fremen ranks."],["d","THE FREMENS","Muad'Dib, Lisan Al Gaib, Mahdi !"]]},{"n":140,"h":"EXTERIOR. NIGHT. A ROCK.","b":[["a","Paul is conferring with the Fremen leaders on the flat top of an enormous rock. Jessica, Alia, Halleck, Stilgar and Chani are all beside him."],["a","Down below in the desert, the Fremen troops wait for their leaders' decision ; they are sitting in perfect order, as motionless as statues."],["a","The order of the armies and silence of each man give the scene an unreal atmosphere."],["d","PAUL","The planet is ours, but we have not yet won the war. In the very near future, I see an attacking fleet of thousands of ships landing on Dune. The Emperor and his Sardaukars, the space Guild, the Major and Minor Houses will all come running to defend the spice. The wind will be our friend. We shall hide in the great flat land. Their blows will hit the air without landing on anyone, but when the strongest tempest ever known begins, we shall gather to attack."],["a","The leaders bow. With their foreheads, they touch the ground at Paul's feet then they slide down the rock with the help of ropes and run back to their armies."],["a","Paul, Jessica, Chani, Alia, Halleck and Stilgar watch the Fremens scatter in all directions. Dawn is breaking. Paul and his friends are still on the rock. There is no longer a single fremen in the desert."],["d","PAUL","Alia, the Emperor will be looking for millions of Fremens on Dune. He'll only find a child."]]},{"n":141,"h":"EXTERIOR. INTERPLANETARY SPACE. VIEW FROM THE PLANET DUNE.","b":[["a","An enormous fleet of space war-ships is approaching Dune threateningly."],["a","These ships, bearing the Emperor's emblem, look sinister. They are completely covered in claws, spikes and teeth."]]},{"n":142,"h":"EXTERIOR. ROCKS BY THE DESERT. DAYLIGHT.","b":[["a","A great number of ships have landed in the desert, where a military encampment has been set up. Tents can be seen, preparations are being made, and soldiers are putting cannons into place. Sardaukars have disembarked in entire legions."],["a","In the middle of the encampment stands the Emperor's huge campaign tent, made out of silver metal leaves. It is gigantic and has several levels ; the whole tent is covered with banners, emblems and coloured ribbons."],["a","A military detachment comes in from the desert, covered in dust and on the edge of exhaustion. Fenring is their leader. Tiredness, disappointment and muted anger can be read on the faces. The soldiers collapse on the ground. Their friends run to help them, giving them water to drink. Fenring enters the Emperor's metallic tent."]]},{"n":143,"h":"INTERIOR. THE EMPEROR'S METALLIC TENT.","b":[["a","The walls of the metallic tent are decorated with unheard-of luxury. In the centre of the room, on the floor covered with brocade and lace, a throne cut into a transparent stone changes its luminous colouring constantly."],["a","The Emperor is accompanied by his courtiers : luxury spongers, woman dressed with mad extravagance, jesters, musicians, favourites, young adolescents, courtesans, doctors, etc. The Reverend Mother Bene Guesserit is also present beside the throne."],["a","The Emperor, followed by his worshippers, walks like a lion in a cage. Fenring, accompanied by Lady Fenring eight months pregnant, listens to him with patience."],["d","THE EMPEROR","It's been weeks since we've been in this ghastly place, and we've not seen a single Fremen. What kind of war is this ? Where's the enemy ?"],["d","FENRING","Our detachments have covered every little bit of desert, destroyed their gardens, bombarded their caves with cannon fire. They've abandoned everything."],["d","THE EMPEROR","It's all because of this Vladimir Harkonnen. I don't dare to think of the cost of such an expedition ! Keep looking ! They can hardly have changed into sand ! Find these cowards and exterminate them !"]]},{"n":144,"h":"EXTERIOR. DESERT. DAYLIGHT.","b":[["a","The Emperor's army, with Fenring at its head, is advancing in the desert."],["a","Suddenly a child emerges from the dunes. It is Alia. She walks forward towards the army, as if she's going to attack the thousands of soldiers all by herself."],["a","The alarm warning spreads among the Sardaukars."],["a","The army takes up an attacking position as the soldiers prepare their arms. A hundred cannons are pointed at the little girl."],["a","Fenring detaches several men who run off in various directions and finally come together again surrounding Alia."],["a","About twenty Sardaukars, filled with apprehension at the thought of a possible bomb explosion, walk slowly forward towards Alia."],["a","She laughs, drops the cape covering her and stands completely naked."],["a","The twenty Sardaukars roar out and run, with raised spears, towards the little girl."],["d","FENRING","(shouting) Halt !"],["a","The Sardaukars stop dead, with their spears raised. Fenring approaches and takes Alia in his arms in a paternal gesture. Alia shows him Duke Leto's ring."],["d","ALIA","I've a message for the Emperor."]]},{"n":145,"h":"EXTERIOR. ROCKS BY THE DESERT. DAYLIGHT.","b":[["a","The hurricane is blowing and become stronger. Black clouds are rapidly passing over the sky."],["a","A rock moves, revealing the entrance to a small shelter. Paul comes out of it, holding a telescope. His friends and warriors are with him, together with Jessica and Chani."],["a","Down below, the Emperor's encampment can be seen."],["a","An energy screen protects the metallic tent and the ships."],["d","PAUL","The shield protects them from the hurricane. But the fremens will come with the wind."],["d","JESSICA","The atom bomb is ready."],["d","STILGAR","The cannons as well."],["d","PAUL","As soon as the bomb destroys the protective shield, demolish the planes. Let the army attack taking account of the wind direction."],["d","CHANI","Blow, powerful voice of the desert : Help us, great animal ! For we are the sons of the wind and the sand !"],["a","The hurricane is now blowing with a frightening strength."],["a","The rock is covered with clouds of sand."]]},{"n":146,"h":"INTERIOR. THE EMPEROR'S METALLIC HALL.","b":[["a","The courtiers stiffly and silently surround the throne. The reverend mother Bene Guesserit looks like a wax statue."],["a","Sitting on the throne, the severe looking Emperor is holding Alia on her knees against him."],["a","Some Sardaukars bring in Baron Vladimir Harkonnens, as if he were a prisoner. He is shown to a small bench in front of the throne."],["a","Vladimir is mad with terror."],["d","THE EMPEROR","Traitor !"],["d","VLADIMIR","Your Majesty !..."],["d","THE EMPEROR","You wanted to unite the Fremens against your Emperor !"],["d","VLADIMIR","Never ..."],["d","THE REVEREND MOTHER","Liar !"],["d","THE EMPEROR","You sack of potatoes ! . Didn't you know that the Fremens had a leader, a prophet : Muad'Dib ?"],["d","VLADIMIR","A fanatic, a madman..."],["d","ALIA","Frighten him a bit more, Padishah. I like to see this stinking podge tremble !"],["d","THE EMPEROR","Do you know who she is ?"],["d","VLADIMIR","It's a dwarf."],["d","THE EMPEROR","She's Muad'Dib's sister. The daughter of Duke Leto. Muad'Dib is Paul Atreides : Duke and legal governor of Dune. He's a god for ten million fremens ! And it's all your fault, fat ass !"],["d","ALIA","(pointing to the reverend mother) The old woman is guilty as well. The genetic plan of the Bene Guesserit."],["a","THE REVEREND MOTHER (in the VOICE) - Silence !"],["d","ALIA (laughing)","You don't affect me. I'm more powerful than you (in the VOICE). Down on your knees before me !"],["p",291],["a","The reverend mother, under dreadful pain, takes her head in her hands. Then, unable to resist, she falls to her knees in front of Alia."],["d","REVEREND MOTHER","This child is a monster ! She has even got into my mind. Get out, devil ! Enough, have mercy !"],["d","ALIA","Our powers are greater than those of Bene Guesserit... I'm older than you... I know where you come from and where you can't go..."],["d","REVEREND MOTHER","Kill her...."],["d","EMPEROR","Be quiet ! If you can read people's minds, get in touch with your brother and tell him to surrender in exchange for your life."],["d","ALIA","Don't give me orders, you clown. The emperor of the world is Paul Muad'Dib. Tremble in your skin. The forces of the sky and the earth help him... He will come soon ! ..."]]},{"n":147,"h":"EXTERIOR. ROCKS BY THE DESERT. DAYLIGHT.","b":[["a","The storm is at its height. The sky is black with sand. An atom bomb explodes beside the protective shield in the encampment."],["a","The shield splits open, the hurricane rushes in, and the tents and arms of the Sardaukars fly away."],["a","Thousands of Fremens emerge from all sides. Rocks open up, revealing cannons which bombard and destroy the airships."],["a","The fremens attack the Sardaukars who, disorientated and seized with panic, run loose in the hurricane. The wind is beginning to destroy the emperor's great metallic tent."]]},{"n":148,"h":"INTERIOR. THE EMPEROR'S METALLIC HALL.","b":[["a","The room vibrates and trembles around the Emperor and his courtiers. An avalanche of sand drops down behind the throne. The wall cracks, letting arrows of wind enter ; the clothes and wall-hanging are blown about."],["d","ALIA","When I told you my brother would arrive..."],["a","Baron Vladimir attacks Alia and holds her prisoner between his arms, shouting."],["d","VLADIMIR","I'm holding the monster, kill her !"],["d","ALIA","Sorry, old man..."],["a","With a poisoned needle hidden under the skin of one of her arms. Alia stabs Vladimir's neck."],["d","VLADIMIR","Aaaaahg !"],["a","Vladimir dies. His face immediately becomes a purplish colour. His swollen tongue hangs out of his mouth. One of the walls collapses. A whirl of wind and sand blows into the tent."],["a","The courtiers utter a cry of horror. The Sardaukars protect the Emperor and the Reverend Mother. The doors burst open. The fremens, brandishing their blood-stained Krys, come in with the sand."],["a","Alia is given a Krys and rushes to attack and kill the courtiers."],["a","A fierce struggle takes place with the Sardaukars who make a rampart out of their bodies to ensure the Emperor's safety. The Sardaukars manage to take the Emperor away through a breach in the wall."]]},{"n":149,"h":"EXTERIOR. SARDAUKAR ENCAMPMENT. DAYLIGHT.","b":[["a","The soldiers take the Emperor through the middle of the battle which is covering the encampment with blood. The reverend mother is also with them."],["a","The ground is littered with Sardaukars' bodies. Among the clouds of dust, and in the wind blowing a storm, the dark silhouettes of the fremens can be sensed, finishing off their decimation of the Emperor's army. The Emperor, his eyes starting out of his head, sees gigantic worms driven by fremens invading the encampment."],["a","The worms carry off the ships and the large metallic tent."]]},{"n":150,"h":"EXTERIOR. ON A WINDING PATH BETWEEN ROCKS NEAR THE ENCAMPMENT. DAYLIGHT.","b":[["a","The faithful Sardaukars lead the Emperor and the Reverend Mother on to a winding path between rocks. Outside, the tempest is raging. The battle continues. The fremens are still arriving like a black ocean and join in the battle."],["a","Other Sardaukars are bringing Fenring and his wife into the shelter."],["d","FENRING","We were able to save a part of the court group. They are in the course of eliminating our battalions of Sardaukars."],["a","The EMPEROR : For the moment, we are losing. But we still have the space Guild, the Major and Minor Houses, and ..."],["d","FENRING","Treason, your Majesty ?"],["d","THE EMPEROR","Yes, Fenring, the arm of intelligence."],["a","With humour, the Emperor takes off his white shirt, attaches it to Fenring's sword like a flag and goes out with dignity, waving it."]]},{"n":151,"h":"INTERIOR. GOVERNMENT PALACE HALL. DUNE","b":[["a","The hall of the government Palace has been rid of all the Harkonnen fittings. It is now a large room with bare walls. On a low platform, carpets, cushions and foot-tables have been arranged, all in the purest fremen style. The green and black banner of Muad'Dib is hanging on a wall. Paul, Jessica, Alia, Chani, Stilgar and Halleck are sitting on the platform, their legs crossed. The fremen leaders, about thirty warriors, are beside them."],["a","The doors open and the prisoners enter : Emperor Padishah, Reverend Mother Bene Guesserit, Count Fenring and Lady Fenring, Thufir Hawatt, Feyd Rautha, ten officials of the space Guild and a few surviving courtiers, some women whose luxurious costumes are now nothing but rags and some spongers in a pitiful state. The Emperor is with his wife and his daughter, who have an imposing stature."],["a","A group of fremen soldiers is watching over the prisoners."],["a","Paul and Jessica rise."],["d","PAUL","(to Hawatt) What are you doing among these prisoners. Hawatt? Your place is beside your Duke."],["a","Hawatt, livid and very weak, can hardly walk. He lowers his eyes in shame."],["d","HALLECK","I told him everything... but he insisted on staying there."],["a","The emperor is waiting tensely. Fenring also. Paul perceives how they are feeling."],["d","PAUL","Free him, Halleck."],["d","HALLECK","We haven't searched him !"],["d","PAUL","Free him, Halleck."],["a","Halleck takes off Hawatt's chains. Hawatt takes a few steps towards Jessica. Paul intervenes, opens his arms."],["d","PAUL","I've glimpsed this scene thousands of times. Halleck frees you... You move towards my mother, I intervene and open my arms. You're holding a poisoned needle in your hand... You are in distress because you'll only be given the antidote after you've killed us. You are the Emperor's instrument of treason."],["a","Hawatt stops and begins to convulsively. He reveals the poisoned needle"],["p",297],["a","and aims it at Paul."],["d","PAUL","Thufir, in the name of all those years when you faithfully served my family, you can ask of me what you want. My life ? you can have it."],["a","Patiently, Paul waits for Thufir to come forward. Thufir stretches out his hand and pushes him aside. He moves forward, the poisoned tip pointed towards Jessica. Paul does nothing to stop him. Jessica impassively opens her arms in turn."],["d","HALLECK","Lady Jessica ; now I realize my mistake. My body is suffering but I'm happy in the knowledge that Duke Leto's wife was a real woman."],["a","Hawatt plunges the needle in his chest and dies instantaneously. Paul embraces the body."],["d","PAUL","Let the Fremen people recover his water and honour him as a hero! Let the wind and sand receive him, Let him rest in the breast of Shai-Hulud, because he was always faithful to his truth !"],["d","ALL THE FREMENS","Bilal Kaifa"],["a","They carry Hawatt's body away."],["d","THE EMPEROR","Paul Atreides thinks he is the victor but, at this very moment, above Dune, five thousand Guild ships carrying armies from all the Houses in the Galaxy only await a word from me to make their attack."],["d","PAUL","I knew that... They won't attack (to the guild officials). Go immediately and order your ships to withdraw."],["d","A GUILD OFFICIAL","The space guild doesn't accept orders from a usurper."],["a","Paul signals. A group of Fremens brings in two voluminous objects hidden under tarpaulins. Each of the two objects is placed on a rolling platform."],["a","The fremens reveal one of the two objects. It is a glass cage containing a worm about twelve feet long."],["a","Paul approaches and throws a phial inside the cage. A red gas escapes from the phial. The worm writhes and dies."],["d","PAUL","We are the masters of what we can destroy ! I am now"],["p",298],["a","in a position to exterminate all the worms on Dune. The death of the worm means the end of the spice !"],["a","He signals again, and the fremens reveal the other object. A navigator mutant of the guild is floating in a transparent basin. The bluish water vibrates and makes the whistling noise of spice. The mutant is half-man, half-fish."],["a","Paul signals again. The fremens tear away the dark glasses worn by the guild officials. They all have completely blue eyes."],["d","PAUL","Without spice, the Guild is condemned. If your ships don't move away, they'll be no more spice !"],["a","Guild officials, crestfallen, press nervously around the mutant, like ants."],["a","They bow to Paul."],["d","THE GUILD OFFICIALS","At this very instant, the guild ships are returning to their planet of origin."],["d","PAUL","From now on, the space guild is at the service of Muad'Dib."],["d","THE FREMENS","Bilal Kaifa."],["d","PAUL","(coming up to the reverend mother). The Bene Guesserit also needs spice to acquire its powers. Without spice you will die. I want you to put your science at the fremens disposal."],["d","THE REVEREND MOTHER","Jessica, how your son has changed since the last time I saw him on Caladan ! He has turned out to be the one we were looking for ! Since you gave birth to the Kwisatz Haderach, perhaps we shall forgive you your monstrous daughter."],["d","JESSICA","You have no right to forgive me anything. Stay in your place, poor old woman. You created us for the sole purpose of using us, but we are not obeying any more. The Bene Guesserit will have to follow us, because we have gone much further than it has."],["a","REVEREND MOTHER (in the VOICE). Ungrateful woman I'm going to ..."],["d","JESSICA","(in the VOICE) Be quiet !"],["a","The reverend mother stays quiet."],["d","JESSICA","Take a knife ! (the reverend mother obeys). Stick it in your heart !"],["p",299],["a","The horrified Reverend Mother is forced to slowly plunge the dagger into her breast. Trickle of blood appears."],["d","JESSICA","Stop !"],["a","The reverend mother drops the knife, crouches down and heaves a deep sigh."],["d","PAUL","And don't think you still have hopes (pointing to Dame Fenring's stomach), this one isn't the Kwisatz Haderach. You were joined with a Harkonnen, Feyd Rautha, and you will give birth to a negative, brainless mutant."],["d","DAME FENRING","That's not true !"],["d","PAUL","In all the possible futures, multiplied till infinity, I have seen your son, motionless like a vegetable object."],["a","Dame Fenring takes her stomach between her hands and starts weeping."],["d","ALL THE FREMENS","Bilal Kaifa."],["a","Paul looks at the emperor."],["d","PAUL","An emperor must be able to control the commerce of spice. Without spice, the galaxy is in mortal danger. Padishah, you no longer have control over anything, you're no longer emperor."],["d","EMPEROR","How does a fanatical murderer dare to say that ?"],["d","PAUL","Don't behave like a fool. You've lost, and you know it. You will give me your daughter, Princess Irulan."],["d","CHANI","Must I leave ?"],["d","PAUL","(embracing her) I shall marry her, but never touch her, you will always be my wife. One of your sons will inherit the throne..."],["d","EMPEROR","The son of a concubine ... a ..."],["d","PRINCESS IRULAN","Enough play-acting, father. This man is worthy to be your son and occupy the throne. (kneeling before Paul). I bow down before my lord, new emperor of the galaxy."],["a","All the courtiers, seeing that the battle is lost and wanting to make a good impression on the victor, bow down before Paul, including the Guild officials and the Reverend Mother. Beside the emperor, Fenring remains standing, although Lady Fenring has also bowed down."],["p",300],["a","On the other side, Feyd Rautha remains standing."],["d","ALL THE FREMENS","Bilal Kaifa."],["d","HALLECK","(pointing to Rautha). One Harkonnen remains. I request the right to take revenge... Immediately."],["d","PAUL","Granted !"],["d","RAUTHA","Paul Muad'Dib, coward ! You hide behind your women and send me a servant ! If you haven't lost every notion of honour among your savages... Take up my challenge !"],["d","HALLECK","My Lord ..."],["d","PAUL","No, Halleck..."],["d","JESSICA","It's not necessary..."],["d","PAUL","This Harkonnen has my father's blood on his hands, Duncan Idaho's too, Thufir Hawatt's, Farok's and that of thousands of friends. I accept his challenge. . ."],["d","THE FREMENS","Bilal Kaifa."],["a","Paul takes off his cape and shirt, and remains naked from the waist up. Feyd Rautha is unbound and given the emperor's sword."],["a","The fremens stand silently in a circle, as for a holy ceremony. Jessica and Alia join the circle, as do the prisoners and, opposite them, the emperor and Fenring."],["a","Feyd Rautha strips off his clothes and remains half-naked also."],["a","Paul cautiously stands opposite Feyd. He makes a rapid leap into the future."],["a","Paul is on the same spot, in the same position exactly, but his opponent is Count Fenring. Fenring holds him down on his knees on the ground and plunges his sword into Paul's back. Paul sees himself falling forward, dead. COming back into reality, he confronts Feyd. The two opponents turn, watching each other."],["a","Feyd makes a feint to the right, changes his sword to his other hand, and rapidly attacks to the left."],["a","As if he had always known this, Paul performs the same movements and wards off this attack. They again turn silently."],["a","Feyd attacks Paul savagely, aiming blow after blow at him, like a madman."],["p",301],["a","Paul wards them all off, then attacks with strength."],["a","Feyd pretends to trips a lets himself fall to the ground. As Paul approaches to kill him, Feyd takes out a needle from one of the seams of his costume and throws it at Paul. The needle falls into an arm."],["a","Immediately Paul lets out a cry."],["a","The needle burns him as if the poison it was dipped in were acid. Paul tears out the needle. Feyd has had the time to get up. He laughs :"],["d","FEYD","You're poisoned. You'll die in one minute. Don't worry about your mother, I'll find a way of consoling her..."],["a","Bold laughs."],["a","Paul's movements have slowed. He can hardly lift his sword. He approaches Feyd Rautha, staggering. Rautha lifts his sword to behead him. At the same time, Paul recovers some of his strength and stabs him in the chest with his krys."],["d","FEYD","That's impossible."],["d","PAUL","The Kwisatz Haderach has the capacity of transforming poisons."],["a","Feyd Rautha dies."],["a","Paul falls to his knees, sick, still under the poisons effect. Fenring makes a cat-like leap forward, immobilizes Paul and puts the blade of his sword to his neck."],["d","EMPEROR","Cut his head off !"],["a","The fremens try to attack the count."],["d","FENRING","Let nobody move or I'll cut his head off."],["a","Everyone stops."],["d","EMPEROR","What are you waiting for ? Kill him."],["d","FENRING","We'd gain nothing by it. This man belongs to legend. He's shown the fremens how to kill worms and control the spice, how to get the better of the Guild, how to dominate the galaxy. Even without him, the fremen legions will invade the universe... If I kill him, they'll say that he gave his life so that his mind could guide them. If I leave him his life, they'll say that nobody can match Muad'Dib. We have lost..."],["d","THE EMPEROR","(rushing towards Fenring and trying to tear his sword away from him) : Let me kill him."],["a","Paul starts laughing and looks calmly at the emperor."],["d","PAUL","Too late... You have put the finishing touch to the creation of the real Kwisatz Haderach, the man who lives everywhere all the time... You can't kill me."],["d","JESSICA (suddenly talking in Paul's voice)","Because to kill the Kwisatz Haderach, you'd have to kill me."],["d","CHANI","(in Paul's voice). Me as well. I can live in all sorts of bodies..."],["a","ALIA (in Paul's voice). You'd have to kill me, I'm Muad'Dib !"],["a","STILGAR (in Paul's voice) I'm Paul Muad'Dib !"],["a","A FREMEN (Paul's voice). I'm Paul Muad'Dib, the Kwisatz Haderach."],["a","Hundreds and hundreds of fremens enter through the door, filling the whole room, and all talking in Paul's voice."],["d","A GROUP OF FREMENS","You ought to kill me..."],["d","ANOTHER GROUP","I'm Muad'Dib."],["d","ANOTHER GROUP","I'm the Kwisatz Haderach."],["a","All the Fremens shout, in Paul's voice :"],["a","I'am the man who lives in everyone's body at once."],["a","Paul, his eyes shining, gets up."],["a","He speaks and all the fremens form a chorus accompanying him, all in the same voice."],["d","PAUL AND ALL THE FREMENS","I know the place where nobody has ever been ; you can go there : trust me, I am the collective man."],["a","Paul, Jessica, Chani, Alia, Stilgar and Halleck are covered by the bodies of the Fremen warriors. They form a homogeneous mass, crying to the Emperor :"],["d","ALL THE FREMENS (in Paul's voice)","The Universe of Love has but one path The Kwisatz Haderach."],["a","Suddenly, the fremens recover their own voice. They draw their swords and, filled with religious and military fervour, brandish them shouting :"],["d","THE FREMENS","Mahdi, Mahdi, Lisan Al Gaib, Muad'Dib !"]]},{"n":152,"h":"INTERIOR. MUSEUM.","b":[["a","Inside the museum, the being-dogs watch the last images of the film projected by the robot."],["a","Fremens can be seen brandishing their swords and crying \"Muad'Dib\"."],["a","Thousands of ships in the green and black fremen colours are leaving the planet. The \"Muad'Dib\" cry resounds in space."],["a","The film ends. The screen folds. The robot has a short circuit and his head explodes, letting some smoke and sparks escape."],["a","The dogs slowly leave the museum."],["a","Before leaving one of them says."],["d","THE DOG","The master will never return."],["a","They leave moaning in pain."]]},{"n":153,"h":"EXTERIOR. MUSEUM OF MAN.","b":[["a","DAYLIGHT"],["a","The dogs return to the vehicle, still moaning."],["a","One of them stops and shouts :"],["d","THE DOG","The master's return matters little."],["a","One day, we'll go and look for him.."]]},{"n":154,"h":"EXTERIOR. GALACTIC SPACE.","b":[["a","The being-dogs' ship is flying at a dizzy speed towards the centre of the universe."],["a","It goes further and further away, as yelps of joy can be heard from the dogs."],["a","On this image of the ship going off into the distance, the end titles are superimposed."]]}],"pages":{"192":1,"263":115,"270":115,"264":116,"271":116,"265":117,"269":67,"272":125,"273":132,"274":134,"403":53,"68":141,"312":43,"404":51},"reels":{"one-shot":[1,19],"gold":[20,31],"caladan":[32,38],"giedi":[39,42],"training":[43,43],"arrakis":[44,89],"desert":[90,115],"water":[116,136],"war":[137,150],"fin":[151,154]}};
